	URL    string      `yaml:"url"`
}

// ParseURL parses a datasource URL string, converting absolute paths
// to file:// URLs.
func ParseURL(s string) (*url.URL, error) {
	if strings.HasPrefix(s, "/") {
		// absolute path => file URL. url.Parse("file:///tmp/...") would
		// treat another leading slash etc correctly; mimic original
		// by prefixing file://
