{"command":"cat > config.go <<'GO'
package gomplate

import (
	"errors"
	"fmt"
	"strings"
	"time"

	"example.com/gomplate/internal/config"
	"gopkg.in/yaml.v3"
)

// Config holds gomplate configuration. Field order matters for YAML dumps.
type Config struct {
	Datasources       map[string]config.DataSource `yaml:"datasources,omitempty"`
	Context           map[string]config.DataSource `yaml:"context,omitempty"`
	Templates         map[string]config.DataSource `yaml:"templates,omitempty"`
	Plugins           map[string]PluginConfig      `yaml:"plugins,omitempty"`
	In                string                       `yaml:"in,omitempty"`
	InputDir          string                       `yaml:"inputDir,omitempty"`
	Excludes          []string                     `yaml:"excludes,omitempty"`
	ExcludeProcessing []string                     `yaml:"excludeProcessing,omitempty"`
	InputFiles        []string                     `yaml:"inputFiles,omitempty"`
	OutputDir         string                       `yaml:"outputDir,omitempty"`
	OutputMap         string                       `yaml:"outputMap,omitempty"`
	OutputFiles       []string                     `yaml:"outputFiles,omitempty"`
	Chmod             string                       `yaml:"chmod,omitempty"`
	LeftDelim         string                       `yaml:"leftDelim,omitempty"`
	RightDelim        string                       `yaml:"rightDelim,omitempty"`
	MissingKey        string                       `yaml:"missingKey,omitempty"`
	PostExec          []string                     `yaml:"postExec,omitempty"`
	PluginTimeout     time.Duration                `yaml:"pluginTimeout,omitempty"`
	ExecPipe          bool                         `yaml:"execPipe,omitempty"`
	Experimental      bool                         `yaml:"experimental,omitempty"`
}

func (c *Config) String() string {
	out, _ := yaml.Marshal(c)
	return string(out)
}

// PluginConfig configures a plugin.
type PluginConfig struct {
	Cmd     string        `yaml:"cmd"`
	Args    []string      `yaml:"args,omitempty"`
	Timeout time.Duration `yaml:"timeout,omitempty"`
	Pipe    bool          `yaml:"pipe,omitempty"`
}

func (p *PluginConfig) UnmarshalYAML(value *yaml.Node) error {
	switch value.Kind {
	case yaml.ScalarNode:
		var s string
		if err := value.Decode(&s); err != nil {
			return err
		}
		p.Cmd = s
		return nil
	case yaml.MappingNode:
		type plain PluginConfig
		var v plain
		if err := value.Decode(&v); err != nil {
			return err
		}
		*p = PluginConfig(v)
		return nil
	case yaml.DocumentNode:
		if len(value.Content) == 0 {
			return nil
		}
		return p.UnmarshalYAML(value.Content[0])
	default:
		// null node is a scalar with tag !!null - yaml.v3 Kind is ScalarNode
		// for null, handled above (Decode into string yields "")
		return errors.New("plugin config must be a string or map")
	}
}

// applyDefaults fills empty fields with defaults.
func (c *Config) applyDefaults() {
	if c.ExecPipe {
		c.OutputFiles = []string{"-"}
	}
	if c.InputDir != "" && c.OutputMap == "" && c.OutputDir == "" {
		c.OutputDir = "."
	}
	if c.In == "" && len(c.InputFiles) == 0 && c.InputDir == "" {
		c.InputFiles = []string{"-"}
	}
	if len(c.OutputFiles) == 0 && c.OutputDir == "" && c.OutputMap == "" && !c.ExecPipe {
		// only default output when not using directory outputs
		c.OutputFiles = []string{"-"}
	}
	if c.LeftDelim == "" {
		c.LeftDelim = "{{"
	}
	if c.RightDelim == "" {
		c.RightDelim = "}}"
	}
	if c.MissingKey == "" {
		c.MissingKey = "error"
	}
	if c.PluginTimeout == 0 {
		c.PluginTimeout = 5 * time.Second
	}
}

func (c *Config) validate() error {
	c.applyDefaults()
	fail := func(format string, args ...interface{}) error {
		msg := fmt.Sprintf(format, args...)
		return fmt.Errorf("failed to validate config: %s\n---\n%s", msg, c.String())
	}
	// missing-key check first? Original checks it before some others in
	// cases we observed (e.g. outputDir+outputMap conflict with bad
	// missing-key reported missing-key). Order matters: probe shows
	// missing-key error takes precedence over outputDir/outputMap conflict.
	allowed := map[string]bool{"": true, "error": true, "zero": true, "default": true, "invalid": true}
	if !allowed[c.MissingKey] {
		return fail("not allowed value for the 'missing-key' flag: %s. Allowed values: ,error,zero,default,invalid", c.MissingKey)
	}
	// only-one checks
	// 'in', 'inputFiles' - note inputFiles defaults to ["-"] when both in
	// and inputDir are empty, so In != "" implies InputFiles wasn't defaulted.
	if c.In != "" && len(c.InputFiles) > 0 && !(len(c.InputFiles) == 1 && c.InputFiles[0] == "-" && c.WasInputFilesDefaulted()) {
		// The defaulting above doesn't add InputFiles when In != "", so any
		// InputFiles here are explicit.
		return fail("only one of these options is supported at a time: 'in', 'inputFiles'")
	}
	if c.In != "" && c.InputDir != "" {
		return fail("only one of these options is supported at a time: 'in', 'inputDir'")
	}
	if c.InputDir != "" && len(c.InputFiles) > 0 {
		return fail("only one of these options is supported at a time: 'inputDir', 'inputFiles'")
	}
	if c.OutputDir != "" && c.OutputMap != "" {
		return fail("only one of these options is supported at a time: 'outputDir', 'outputMap'")
	}
	if len(c.OutputFiles) > 0 && c.OutputDir != "" && c.IsOutputFilesExplicitForValidate() {
		return fail("only one of these options is supported at a time: 'outputFiles', 'outputDir'")
	}
	if len(c.OutputFiles) > 0 && c.OutputMap != "" && c.IsOutputFilesExplicitForValidate() {
		return fail("only one of these options is supported at a time: 'outputFiles', 'outputMap'")
	}
	if c.OutputDir != "" && c.InputDir == "" {
		return fail("these options must be set together: 'outputDir', 'inputDir'")
	}
	if c.OutputMap != "" && c.InputDir == "" {
		return fail("these options must be set together: 'outputMap', 'inputDir'")
	}
	if c.ExecPipe && len(c.PostExec) == 0 {
		return fail("execPipe may only be used with a postExec command")
	}
	// count check for outputFiles vs input count, only when not using
	// inputDir/outputMap/outputDir
	if c.InputDir == "" && c.OutputMap == "" {
		inCount := 0
		if c.In != "" {
			inCount = 1
		} else {
			inCount = len(c.InputFiles)
		}
		if len(c.OutputFiles) != inCount {
			return fail("must provide same number of 'outputFiles' (%d) as 'in' or 'inputFiles' (%d) options", len(c.OutputFiles), inCount)
		}
	}
	return nil
}

// WasInputFilesDefaulted is a placeholder (defaults don't set InputFiles when In set)
func (c *Config) WasInputFilesDefaulted() bool { return false }

// IsOutputFilesExplicitForValidate - outputFiles defaults only when no
// outputDir/outputMap; if outputFiles is ["-"] and it was forced by execPipe
// it still counts as explicit for conflict reporting (observed).
func (c *Config) IsOutputFilesExplicitForValidate() bool {
	// When InputDir is set and OutputDir was defaulted to ".", a plain
	// outputFiles default would not have been added, so any OutputFiles
	// present is explicit (from CLI/config/execPipe).
	return true
}

