		// InputFiles here are explicit.
		return fail("only one of these options is supported at a time: 'in', 'inputFiles'")
	}
	if c.In != "" && c.InputDir != "" {
		return fail("only one of these options is supported at a time: 'in', 'inputDir'")
	}
	if c.InputDir != "" && len(c.InputFiles) > 0 {
		return fail("only one of these options is supported at a time: 'inputDir', 'inputFiles'")
	}
	if c.OutputDir != "" && c.OutputMap != "" {
		return fail("only one of these options is supported at a time: 'outputDir', 'outputMap'")
	}
	if len(c.OutputFiles) > 0 && c.OutputDir != "" && c.IsOutputFilesExplicitForValidate() {
		return fail("only one of these options is supported at a time: 'outputFiles', 'outputDir'")
	}
	if len(c.OutputFiles) > 0 && c.OutputMap != "" && c.IsOutputFilesExplicitForValidate() {
		return fail("only one of these options is supported at a time: 'outputFiles', 'outputMap'")
	}
	if c.OutputDir != "" && c.InputDir == "" {
		return fail("these options must be set together: 'outputDir', 'inputDir'")
	}
	if c.OutputMap != "" && c.InputDir == "" {
		return fail("these options must be set together: 'outputMap', 'inputDir'")
	}
	if c.ExecPipe && len(c.PostExec) == 0 {
		return fail("execPipe may only be used with a postExec command")
	}
	// count check for outputFiles vs input count, only when not using
	// inputDir/outputMap/outputDir
	if c.InputDir == "" && c.OutputMap == "" {
		inCount := 0
		if c.In != "" {
			inCount = 1
		} else {
			inCount = len(c.InputFiles)
		}
		if len(c.OutputFiles) != inCount {
			return fail("must provide same number of 'outputFiles' (%d) as 'in' or 'inputFiles' (%d) options", len(c.OutputFiles), inCount)
		}
	}
	return nil
}

// WasInputFilesDefaulted is a placeholder (defaults don't set InputFiles when In set)
func (c *Config) WasInputFilesDefaulted() bool { return false }

// IsOutputFilesExplicitForValidate - outputFiles defaults only when no
// outputDir/outputMap; if outputFiles is ["-"] and it was forced by execPipe
// it still counts as explicit for conflict reporting (observed).
func (c *Config) IsOutputFilesExplicitForValidate() bool {
	// When InputDir is set and OutputDir was defaulted to ".", a plain
	// outputFiles default would not have been added, so any OutputFiles
	// present is explicit (from CLI/config/execPipe).
	return true
}

