package datafs

import (
	"errors"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

// CleanAbs returns absolute cleaned path for name, relative to cwd if needed.
func CleanAbs(name string) string {
	if name == "" {
		name = "."
	}
	abs, err := filepath.Abs(name)
	if err != nil {
		return filepath.Clean("/" + name)
	}
	return abs
}

// RootName converts an absolute path to a name relative to "/" (no leading slash).
// Root itself becomes ".".
func RootName(abs string) string {
	abs = filepath.Clean(abs)
	if abs == "/" {
		return "."
	}
	return strings.TrimPrefix(abs, "/")
}

// RewritePathErr rewrites a *os.PathError (or fs.PathError) path to root-relative.
func RewritePathErr(err error) error {
	if err == nil {
		return nil
	}
	var pe *os.PathError
	if errors.As(err, &pe) {
		// copy to avoid mutating original? mutation is fine but do copy
		npe := *pe
		if filepath.IsAbs(npe.Path) {
			npe.Path = RootName(npe.Path)
			if npe.Path == "." {
				// os root errors for "/" itself? keep "."
			}
		}
		return &npe
	}
	var le *os.LinkError
	if errors.As(err, &le) {
		return err
	}
	return err
}

func rewriteWithPath(err error, path string) error {
	if err == nil {
		return nil
	}
	var pe *os.PathError
	if errors.As(err, &pe) {
		npe := *pe
		npe.Path = path
		return &npe
	}
	return err
}

// Open opens name (abs or relative to cwd) as if through a root at "/".
func Open(name string) (*os.File, error) {
	abs := CleanAbs(name)
	f, err := os.Open(abs)
	if err != nil {
		return nil, RewritePathErr(err)
	}
	return &rootFile{File: f, rootName: RootName(abs)}, nil
}

// rootFile wraps *os.File to rewrite read error paths to root-relative.
type rootFile struct {
	*os.File
	rootName string
}

func (f *rootFile) Read(p []byte) (int, error) {
	n, err := f.File.Read(p)
	if err != nil && err != io.EOF {
		err = rewriteWithPath(err, f.rootName)
	}
	return n, err
}
func (f *rootFile) ReadAt(p []byte, off int64) (int, error) {
	n, err := f.File.ReadAt(p, off)
	if err != nil && err != io.EOF {
		err = rewriteWithPath(err, f.rootName)
	}
	return n, err
}
func (f *rootFile) Readdirnames(n int) ([]string, error) {
	names, err := f.File.Readdirnames(n)
	if err != nil && err != io.EOF {
		err = rewriteWithPath(err, f.rootName)
	}
	return names, err
}

// ReadFile reads a whole file through root semantics.
func ReadFile(name string) ([]byte, error) {
	f, err := Open(name)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	b, err := io.ReadAll(f)
	if err != nil {
		return nil, err
	}
	return b, nil
}

