package funcs

import (
	"context"
	"text/template"

	"example.com/gomplate/tmpl"
)

// State carries callbacks into the renderer/datasource layer, stored in ctx.
type State struct {
	Datasource          func(ctx context.Context, alias string, args ...string) (interface{}, error)
	DatasourceExists    func(alias string) bool
	DatasourceReachable func(ctx context.Context, alias string) bool
	ListDatasources     func() []string
	DefineDatasource    func(alias, url string) (string, error)
	Include             func(ctx context.Context, alias string, args ...string) (string, error)
	Experimental        bool
}

type stateKey struct{}

func WithState(ctx context.Context, s *State) context.Context {
	return context.WithValue(ctx, stateKey{}, s)
}

func stateFrom(ctx context.Context) *State {
	if ctx != nil {
