package tmpl

import (
	"bytes"
	"fmt"
	"path/filepath"
	"text/template"
)

// Template is the tmpl namespace object.
type Template struct {
	root       *template.Template
	defaultCtx interface{}
	path       string
}

func New(root *template.Template, defaultCtx interface{}, path string) *Template {
	return &Template{root: root, defaultCtx: defaultCtx, path: path}
}

func (t *Template) SetRoot(root *template.Template) { t.root = root }

func (t *Template) Path() string { return t.path }

func (t *Template) PathDir() string { return filepath.Dir(t.path) }

// Exec executes a named template and returns output as string.
func (t *Template) Exec(name string, ctx ...interface{}) (string, error) {
	if t.root == nil || t.root.Lookup(name) == nil {
		return "", fmt.Errorf("template %q not defined", name)
	}
	var data interface{}
	if len(ctx) > 0 {
		data = ctx[0]
	}
	buf := &bytes.Buffer{}
	if err := t.root.ExecuteTemplate(buf, name, data); err != nil {
		return "", err
	}
	return buf.String(), nil
}

// Inline renders a template string. Args are:
//   Inline in [context]
//   Inline name in [context]
func (t *Template) Inline(args ...interface{}) (string, error) {
	if len(args) == 0 || len(args) > 3 {
		return "", fmt.Errorf("want 1, 2, or 3 - got %d", len(args))
	}
	var name, in string
	var data interface{} = t.defaultCtx
	switch len(args) {
	case 1:
		in = toString(args[0])
	case 2:
		// 2-arg form is in+context (observed)
		in = toString(args[0])
		data = args[1]
	case 3:
		name = toString(args[0])
		in = toString(args[1])
		data = args[2]
	}
	var tmpl *template.Template
	var err error
	if name != "" && t.root != nil {
		// Adding to root makes it reusable via {{template "name" ...}}
		// If a template with name already exists, New returns it and
		// Parse replaces its definition (matching text/template).
		tmpl = t.root.New(name)
		_, err = tmpl.Parse(in)
		if err != nil {
			return "", err
		}
	} else if t.root != nil {
		// Clone root so defines from inline don't pollute? Original
		// behaviour for unnamed: use a new template associated with
		// root's funcs/templates. Clone gives us same associated set.
		cloned, cerr := t.root.Clone()
		if cerr != nil {
			return "", cerr
		}
		// New template with empty name shadows root name? Use a unique
		// internal name derived from root name if possible.
		tmpl = cloned.New(cloned.Name())
		// cloned.New(rootName) returns existing root template of clone;
		// parse into it.
		_, err = tmpl.Parse(in)
		if err != nil {
			return "", err
		}
	} else {
		tmpl, err = template.New("").Parse(in)
		if err != nil {
			return "", err
		}
	}
	buf := &bytes.Buffer{}
	if err := tmpl.Execute(buf, data); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func toString(v interface{}) string {
	if s, ok := v.(string); ok {
		return s
	}
	return fmt.Sprint(v)
}
GO"}

