{"command":"cat > funcs/conv.go <<'GO'
package funcs

import (
	"context"
	"fmt"
	"net/url"
	"reflect"
	"strconv"
	"strings"
)

// ---- core conversion helpers ----

func toString(in interface{}) string {
	if in == nil {
		return "nil"
	}
	switch v := in.(type) {
	case string:
		return v
	case []byte:
		return string(v)
	case error:
		return v.Error()
	case fmt.Stringer:
		return v.String()
	default:
		return fmt.Sprintf("%v", in)
	}
}

func toBool(in interface{}) bool {
	if in == nil {
		return false
	}
	switch v := in.(type) {
	case bool:
		return v
	case string:
		switch strings.ToLower(v) {
		case "1", "t", "true", "yes":
			return true
		}
		if f, err := toFloat64(v); err == nil && f == 1 {
			return true
		}
		return false
	case []byte:
		return toBool(string(v))
	}
	// numeric kinds
	rv := reflect.ValueOf(in)
	switch rv.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return rv.Int() == 1
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return rv.Uint() == 1
	case reflect.Float32, reflect.Float64:
		return rv.Float() == 1
	}
	return false
}

func cleanNumString(s string) string {
	return strings.ReplaceAll(s, ",", "")
