{"command":"cat > funcs/math.go <<'GO'
package funcs

import (
	"context"
	"errors"
	"fmt"
	gomath "math"
	"reflect"
	"strconv"
)

type MathFuncs struct {
	ctx context.Context
}

func IsIntValue(in interface{}) bool {
	if in == nil { return false }
	switch v := in.(type) {
	case string:
		_, err := strconv.ParseInt(v, 0, 64)
		if err == nil { return true }
		// unsigned big integers that fit uint64 but not int64?
		if _, err := strconv.ParseUint(v, 0, 64); err == nil { return true }
		return false
	}
	rv := reflect.ValueOf(in)
	switch rv.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
		reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return true
	}
	return false
}

func IsFloatValue(in interface{}) bool {
	if in == nil { return false }
	if s, ok := in.(string); ok {
		if IsIntValue(s) { return false }
		_, err := strconv.ParseFloat(s, 64)
		return err == nil
	}
	rv := reflect.ValueOf(in)
	return rv.Kind() == reflect.Float32 || rv.Kind() == reflect.Float64
}

func anyFloat(args ...interface{}) bool {
	for _, a := range args { if IsFloatValue(a) { return true } }
	return false
}

func (f *MathFuncs) IsInt(in interface{}) bool { return IsIntValue(in) }
func (f *MathFuncs) IsFloat(in interface{}) bool { return IsFloatValue(in) }
func (f *MathFuncs) IsNum(in interface{}) bool { return IsIntValue(in) || IsFloatValue(in) }

func (f *MathFuncs) Abs(in interface{}) (interface{}, error) {
	fv, err := toFloat64(in)
	if err != nil { return nil, fmt.Errorf("expected a number: %w", err) }
	if IsFloatValue(in) {
		return gomath.Abs(fv), nil
	}
	return int64(gomath.Abs(fv)), nil
}

func (f *MathFuncs) Add(n ...interface{}) (interface{}, error) {
	if anyFloat(n...) {
		var x float64
		for _, v := range n {
			fv, err := toFloat64(v); if err != nil { return nil, fmt.Errorf("expected number inputs: %w", err) }
			x += fv
		}
		return x, nil
	}
	var x int64
	for _, v := range n {
		iv, err := toInt64(v); if err != nil { return nil, fmt.Errorf("expected number inputs: %w", err) }
		x += iv
	}
	return x, nil
}

func (f *MathFuncs) Mul(n ...interface{}) (interface{}, error) {
	if anyFloat(n...) {
		x := 1.0
		for _, v := range n {
			fv, err := toFloat64(v); if err != nil { return nil, fmt.Errorf("expected number inputs: %w", err) }
			x *= fv
		}
		return x, nil
	}
	var x int64 = 1
	for _, v := range n {
		iv, err := toInt64(v); if err != nil { return nil, fmt.Errorf("expected number inputs: %w", err) }
		x *= iv
	}
	return x, nil
}

func (f *MathFuncs) Sub(a, b interface{}) (interface{}, error) {
	if anyFloat(a, b) {
		av, err := toFloat64(a); if err != nil { return nil, fmt.Errorf("expected a number: %w", err) }
		bv, err := toFloat64(b); if err != nil { return nil, fmt.Errorf("expected a number: %w", err) }
		return av - bv, nil
	}
	av, err := toInt64(a); if err != nil { return nil, fmt.Errorf("expected a number: %w", err) }
	bv, err := toInt64(b); if err != nil { return nil, fmt.Errorf("expected a number: %w", err) }
	return av - bv, nil
}

func (f *MathFuncs) Div(a, b interface{}) (float64, error) {
	av, err := toFloat64(a); if err != nil { return 0, fmt.Errorf("expected a number: %w", err) }
	bv, err := toFloat64(b); if err != nil { return 0, fmt.Errorf("expected a number: %w", err) }
	if bv == 0 { return 0, errors.New("error: division by 0") }
	return av / bv, nil
}

func (f *MathFuncs) Rem(a, b interface{}) (int64, error) {
	av, err := toInt64(a); if err != nil { return 0, fmt.Errorf("expected a number: %w", err) }
	bv, err := toInt64(b); if err != nil { return 0, fmt.Errorf("expected a number: %w", err) }
	// Deliberately let runtime panic on divide by zero - text/template
	// recovers it and returns "runtime error: integer divide by zero",
	// matching original behaviour.
	return av % bv, nil
}

func (f *MathFuncs) Pow(b, n interface{}) (interface{}, error) {
	bv, err := toFloat64(b); if err != nil { return nil, fmt.Errorf("expected a number: %w", err) }
	nv, err := toFloat64(n); if err != nil { return nil, fmt.Errorf("expected a number: %w", err) }
	r := gomath.Pow(bv, nv)
	if IsFloatValue(b) { return r, nil }
	return int64(r), nil
}

func (f *MathFuncs) Ceil(in interface{}) (float64, error) {
	fv, err := toFloat64(in); if err != nil { return 0, fmt.Errorf("n must be a number: %w", err) }
	return gomath.Ceil(fv), nil
}
func (f *MathFuncs) Floor(in interface{}) (float64, error) {
	fv, err := toFloat64(in); if err != nil { return 0, fmt.Errorf("n must be a number: %w", err) }
	return gomath.Floor(fv), nil
}
func (f *MathFuncs) Round(in interface{}) (float64, error) {
	fv, err := toFloat64(in); if err != nil { return 0, fmt.Errorf("n must be a number: %w", err) }
	return gomath.Round(fv), nil
}

func (f *MathFuncs) Max(n interface{}, rest ...interface{}) (interface{}, error) {
	args := append([]interface{}{n}, rest...)
	if anyFloat(args...) {
		m := gomath.Inf(-1)
