func slugify(in string) string {
	// lower first (with special handling for İ etc)
	s := cases.Lower(language.Und).String(in)
	// replace special runes before decomposition
	var b1 strings.Builder
	for _, r := range s {
		if rep, ok := slugSpecial[r]; ok { b1.WriteString(rep); continue }
		if rep, ok := cyrillic[r]; ok { b1.WriteString(rep); continue }
		if rep, ok := greek[unicode.ToLower(r)]; ok && (r >= 0x370 && r <= 0x3ff) { b1.WriteString(rep); continue }
		// uppercase Cyrillic/Greek already lowered
		b1.WriteRune(r)
	}
	s = b1.String()
	// strip diacritics via NFD
	t := transform.Chain(norm.NFD, runes.Remove(runes.In(unicode.Mn)), norm.NFC)
	if out, _, err := transform.String(t, s); err == nil {
		s = out
	}
	var out strings.Builder
	lastDash := false
	for _, r := range s {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '_' {
			out.WriteRune(r)
			lastDash = false
		} else if r == '-' {
			if !lastDash && out.Len() > 0 { out.WriteRune('-'); lastDash = true }
		} else {
			// any other char becomes dash separator
			if !lastDash && out.Len() > 0 { out.WriteRune('-'); lastDash = true }
		}
	}
	return strings.Trim(out.String(), "-")
}

