// helpers for case conversions
func caseTokensSnake(in string) []string {
	var toks []string
	var cur []rune
	for _, r := range in {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			cur = append(cur, unicode.ToLower(r))
			// special multi-rune lower for İ etc: cases.Lower on whole token later
		} else {
			if len(cur) > 0 { toks = append(toks, string(cur)); cur = nil }
		}
	}
	if len(cur) > 0 { toks = append(toks, string(cur)) }
	// Apply full lower to each token (handles İ, ß staying)
	for i, t := range toks { toks[i] = cases.Lower(language.Und).String(t) }
	return toks
}

func preserveFirstCase(in, joined string) string {
	if in == "" || joined == "" { return joined }
	r, _ := utf8.DecodeRuneInString(in)
	jr, size := utf8.DecodeRuneInString(joined)
	if unicode.IsUpper(r) {
		// Uppercase first rune (full mapping only simple)
		return string(unicode.ToUpper(jr)) + joined[size:]
	}
	// If first rune is non-letter, output first letter was lowercased anyway
	return joined
}

func snakeKebab(in string, sep string) string {
	toks := caseTokensSnake(in)
	joined := strings.Join(toks, sep)
	return preserveFirstCase(in, joined)
}

func camelCase(in string) string {
	runesIn := []rune(in)
	var out []rune
	upperNext := false
	prevIsDigit := false
	prevIsLetter := false
	isFirstOut := true
	for _, r := range runesIn {
		if unicode.IsLetter(r) {
			lr := unicode.ToLower(r)
			if upperNext || prevIsDigit {
				lr = unicode.ToUpper(lr)
			} else if isFirstOut {
				// preserve case if this letter is at position 0 and is ASCII lower
				// or is upper; if input starts with non-ASCII, original title-cases
				if len(runesIn) > 0 && runesIn[0] == r && r < 128 {
					lr = r
					// but rest of first word should be lower: r could be upper H remains H,
					// lower h remains h. Subsequent letters use lower branch.
					if unicode.IsUpper(r) { lr = r } else { lr = unicode.ToLower(r) }
				} else {
					lr = unicode.ToUpper(lr)
				}
			}
			out = append(out, lr)
			isFirstOut = false
			upperNext = false
			prevIsDigit = false
			prevIsLetter = true
		} else if unicode.IsDigit(r) {
			out = append(out, r)
			isFirstOut = false
			upperNext = false
			prevIsDigit = true
			prevIsLetter = false
		} else {
			// separator: exception set doesn't capitalise following letter
			if (r == '_' || r == '.' || r == ':' || r == '\'' || r == '’') && prevIsLetter {
				upperNext = false
			} else {
				upperNext = true
			}
			prevIsDigit = false
			prevIsLetter = false
		}
	}
	// Handle special lower/upper multi-runewise? Keep simple.
	return string(out)
}

