func (f *StringFuncs) WordWrap(args ...interface{}) (string, error) {
	if len(args) < 1 || len(args) > 3 {
		return "", fmt.Errorf("expected 1, 2, or 3 args, got %d", len(args))
	}
	width := 80
	lbseq := "\n"
	in := toString(args[len(args)-1])
	// Parse optional args by position/type similar to Indent (probed later)
	switch len(args) {
	case 2:
		// first could be width (int) or lbseq (string)
		if iv, err := toInt64(args[0]); err == nil {
			// only treat as width if arg is not a string that is non-numeric?
			// Probe: WordWrap "|" "input" is 2-arg? Actually lbseq form needs width too.
			// We'll treat int-kind or numeric string as width, other string as lbseq.
			if _, isStr := args[0].(string); isStr {
				if _, err2 := strconv.ParseInt(args[0].(string), 0, 64); err2 != nil {
					lbseq = args[0].(string)
					break
				}
			}
			width = int(iv)
		} else if s, ok := args[0].(string); ok {
			lbseq = s
		}
	case 3:
		if iv, err := toInt64(args[0]); err == nil { width = int(iv) }
		lbseq = toString(args[1])
	}
	if width <= 0 {
		return in, nil
	}
	words := strings.Fields(in)
	if len(words) == 0 { return in, nil }
	var lines []string
	cur := words[0]
	for _, w := range words[1:] {
		if utf8.RuneCountInString(cur)+1+utf8.RuneCountInString(w) <= width {
			cur += " " + w
		} else {
			lines = append(lines, cur)
			cur = w
		}
	}
	lines = append(lines, cur)
	return strings.Join(lines, lbseq), nil
}

func (f *StringFuncs) RuneCount(args ...interface{}) int {
	s := ""
	for _, a := range args { s += toString(a) }
	return utf8.RuneCountInString(s)
}
