// --- Abbrev ---
func abbrev(offset, width int, in string) (string, error) {
	if width < 4 {
		return "", errors.New("stringutils illegal argument: Minimum abbreviation width is 4")
	}
	if len(in) <= width {
		return in, nil
	}
	if offset > len(in) {
		offset = len(in)
	}
	if len(in)-offset < width-3 {
		offset = len(in) - (width - 3)
	}
	if offset <= 4 {
		return in[:width-3] + "...", nil
	}
	if width < 7 {
		return "", errors.New("stringutils illegal argument: Minimum abbreviation width with offset is 7")
	}
	if offset+width-3 < len(in) {
		s, err := abbrev(0, width-3, in[offset:])
		if err != nil { return "", err }
		return "..." + s, nil
	}
	return "..." + in[len(in)-(width-3):], nil
}

