	}
	lines = append(lines, cur)
	return strings.Join(lines, lbseq), nil
}

func (f *StringFuncs) RuneCount(args ...interface{}) int {
	s := ""
	for _, a := range args { s += toString(a) }
	return utf8.RuneCountInString(s)
