{"command":"cat > funcs/coll.go <<'GO'
package funcs

import (
	"context"
	"errors"
	"fmt"
	"reflect"
	"sort"
	"strings"
	"time"
)

type CollFuncs struct { ctx context.Context }

func (f *CollFuncs) Dict(in ...interface{}) map[string]interface{} {
	out := make(map[string]interface{})
	for i := 0; i < len(in); i += 2 {
		k := toString(in[i])
		var v interface{} = ""
		if i+1 < len(in) { v = in[i+1] }
		out[k] = v
	}
	return out
}

func (f *CollFuncs) Slice(in ...interface{}) []interface{} {
	out := make([]interface{}, len(in))
	copy(out, in)
	return out
}

func toSlice(in interface{}) ([]interface{}, error) {
	if in == nil {
		return nil, errors.New("expected an array or slice, but got a reflect.Value")
	}
	rv := reflect.ValueOf(in)
	rv = indirectValue(rv)
	if rv.Kind() != reflect.Slice && rv.Kind() != reflect.Array {
		return nil, errors.New("expected an array or slice, but got a reflect.Value")
	}
	out := make([]interface{}, rv.Len())
	for i := 0; i < rv.Len(); i++ { out[i] = rv.Index(i).Interface() }
	return out, nil
}

func indirectValue(rv reflect.Value) reflect.Value {
	for rv.IsValid() && (rv.Kind() == reflect.Interface || rv.Kind() == reflect.Ptr) {
		if rv.IsNil() { break }
		rv = rv.Elem()
	}
	return rv
}

// GoSlice replicates text/template's slice function.
func (f *CollFuncs) GoSlice(item interface{}, indexes ...interface{}) (interface{}, error) {
	if item == nil {
		return nil, errors.New("can't slice item of type <nil>")
	}
	rv := indirectValue(reflect.ValueOf(item))
	if !rv.IsValid() {
		return nil, errors.New("can't slice item of type <nil>")
	}
	if len(indexes) > 3 {
		return nil, fmt.Errorf("too many slice indexes: %d", len(indexes))
	}
	kind := rv.Kind()
	if kind != reflect.Array && kind != reflect.Slice && kind != reflect.String {
		return nil, fmt.Errorf("can't slice item of type %s", rv.Type())
	}
	if kind == reflect.String && len(indexes) == 3 {
		return nil, errors.New("cannot 3-index slice a string")
	}
	capv := rv.Len()
	if kind == reflect.Slice { capv = rv.Cap() }
	idx := make([]int, len(indexes))
	for i, ix := range indexes {
		iv, err := sliceIndexValue(ix)
		if err != nil { return nil, err }
		idx[i] = iv
	}
	low, high, max := 0, rv.Len(), capv
	switch len(idx) {
	case 0:
		return rv.Interface(), nil
	case 1:
		low = idx[0]
	case 2:
		low, high = idx[0], idx[1]
	case 3:
		low, high, max = idx[0], idx[1], idx[2]
	}
	// validation mimicking Go template slice()
	if low < 0 || low > rv.Len() {
		return nil, fmt.Errorf("index out of range: %d", low)
	}
	if high < 0 || high > max {
		// for strings/arrays max==len; for slices high may be <=cap in 2-index? Go template checks?
		if len(idx) < 3 && high > rv.Len() {
			return nil, fmt.Errorf("index out of range: %d", high)
		}
		if len(idx) == 3 && high > max {
			return nil, fmt.Errorf("index out of range: %d", high)
		}
	}
	if low > high {
		return nil, fmt.Errorf("invalid slice index: %d > %d", low, high)
	}
	if len(idx) == 3 {
		if max < 0 || max > capv {
			return nil, fmt.Errorf("index out of range: %d", max)
		}
		if high > max {
			return nil, fmt.Errorf("invalid slice index: %d > %d", high, max)
		}
		return rv.Slice3(low, high, max).Interface(), nil
	}
	return rv.Slice(low, high).Interface(), nil
}

func sliceIndexValue(ix interface{}) (int, error) {
	rv := indirectValue(reflect.ValueOf(ix))
	if !rv.IsValid() { return 0, errors.New("cannot use nil as slice index") }
	switch rv.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return int(rv.Int()), nil
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return int(rv.Uint()), nil
	case reflect.Float32, reflect.Float64:
		return int(rv.Float()), nil
	}
	iv, err := toInt64(ix)
	if err != nil { return 0, fmt.Errorf("cannot use %v as slice index", ix) }
	return int(iv), nil
}

func (f *CollFuncs) Has(in interface{}, item string) bool {
	if in == nil { return false }
	rv := indirectValue(reflect.ValueOf(in))
	if !rv.IsValid() { return false }
	switch rv.Kind() {
	case reflect.Map:
		kt := rv.Type().Key()
		var kv reflect.Value
		if kt.Kind() == reflect.String {
			kv = reflect.ValueOf(item).Convert(kt)
		} else {
			// try convert string to key type via conversion helpers
			// int keys etc
			switch kt.Kind() {
			case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
				if iv, err := toInt64(item); err == nil { kv = reflect.ValueOf(iv).Convert(kt) }
			default:
				return false
			}
			if !kv.IsValid() { return false }
		}
		return rv.MapIndex(kv).IsValid()
	case reflect.Slice, reflect.Array:
		for i := 0; i < rv.Len(); i++ {
			if reflect.DeepEqual(rv.Index(i).Interface(), item) { return true }
		}
		return false
	case reflect.Struct:
		return rv.FieldByName(item).IsValid()
	}
	return false
}

func (f *CollFuncs) Index(args ...interface{}) (interface{}, error) {
	if len(args) < 2 {
		return nil, fmt.Errorf("wrong number of args: wanted at least 2, got %d", len(args))
	}
	cur := args[len(args)-1]
	for _, ix := range args[:len(args)-1] {
		v, err := indexOne(cur, ix)
		if err != nil { return nil, err }
		cur = v
	}
	return cur, nil
}

func indexOne(item interface{}, ix interface{}) (interface{}, error) {
	if item == nil {
		return nil, errors.New("can't index item of type <nil>")
	}
	rv := indirectValue(reflect.ValueOf(item))
	if !rv.IsValid() { return nil, errors.New("can't index item of type <nil>") }
	switch rv.Kind() {
	case reflect.Map:
		kt := rv.Type().Key()
		var kv reflect.Value
		ixv := reflect.ValueOf(ix)
		if !ixv.IsValid() {
			return nil, fmt.Errorf("can't index item of type %s", rv.Type())
		}
		if ixv.Type().AssignableTo(kt) {
			kv = ixv
		} else if ixv.Type().ConvertibleTo(kt) {
			// Be careful with int->string conversion semantics: template's index
			// would require assignable kind? Use only same-kind conversions
			if ixv.Kind() == kt.Kind() || (isNumericKind(ixv.Kind()) && isNumericKind(kt.Kind())) {
				kv = ixv.Convert(kt)
			}
		}
		if !kv.IsValid() {
			// map key display
			return nil, fmt.Errorf("map has no key %v", ix)
		}
		mv := rv.MapIndex(kv)
		if !mv.IsValid() {
			return nil, fmt.Errorf("map has no key %v", ix)
		}
		return mv.Interface(), nil
	case reflect.Slice, reflect.Array, reflect.String:
		i, err := sliceIndexValue(ix)
		// string index into string via reflect returns byte for template index builtin
		if err != nil { return nil, err }
		if i < 0 || i >= rv.Len() {
			return nil, fmt.Errorf("index out of range: %d", i)
		}
		if rv.Kind() == reflect.String {
			return int(rv.Index(i).Interface().(uint8)), nil
		}
		return rv.Index(i).Interface(), nil
	case reflect.Struct:
		name := toString(ix)
		fv := rv.FieldByName(name)
		if !fv.IsValid() { return nil, fmt.Errorf("map has no key %v", ix) }
		return fv.Interface(), nil
	}
	return nil, fmt.Errorf("can't index item of type %s", rv.Type())
}
func isNumericKind(k reflect.Kind) bool {
	switch k {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64, reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Float32, reflect.Float64:
		return true
	}
	return false
}

func (f *CollFuncs) Keys(maps ...map[string]interface{}) ([]string, error) {
	if len(maps) == 0 { return nil, errors.New("need at least one argument") }
	var out []string
	for _, m := range maps {
		ks := make([]string, 0, len(m))
		for k := range m { ks = append(ks, k) }
		sort.Strings(ks)
		out = append(out, ks...)
	}
	if out == nil { out = []string{} }
	return out, nil
}
func (f *CollFuncs) Values(maps ...map[string]interface{}) ([]interface{}, error) {
	if len(maps) == 0 { return nil, errors.New("need at least one argument") }
	var out []interface{}
	for _, m := range maps {
		ks := make([]string, 0, len(m))
		for k := range m { ks = append(ks, k) }
		sort.Strings(ks)
		for _, k := range ks { out = append(out, m[k]) }
	}
	if out == nil { out = []interface{}{} }
	return out, nil
}

func (f *CollFuncs) Append(v interface{}, list interface{}) ([]interface{}, error) {
	l, err := toSlice(list); if err != nil { return nil, err }
	return append(l, v), nil
}
func (f *CollFuncs) Prepend(v interface{}, list interface{}) ([]interface{}, error) {
	l, err := toSlice(list); if err != nil { return nil, err }
	return append([]interface{}{v}, l...), nil
}
func (f *CollFuncs) Uniq(list interface{}) ([]interface{}, error) {
	l, err := toSlice(list); if err != nil { return nil, err }
	out := make([]interface{}, 0, len(l))
	for _, v := range l {
		found := false
		for _, o := range out { if reflect.DeepEqual(v, o) { found = true; break } }
		if !found { out = append(out, v) }
	}
	return out, nil
}

func flattenInto(dst []interface{}, v interface{}, depth int) []interface{} {
	rv := reflect.ValueOf(v)
	if rv.IsValid() {
