func toSlice(in interface{}) ([]interface{}, error) {
	if in == nil {
		return nil, errors.New("expected an array or slice, but got a reflect.Value")
	}
	rv := reflect.ValueOf(in)
	rv = indirectValue(rv)
	if rv.Kind() != reflect.Slice && rv.Kind() != reflect.Array {
		return nil, errors.New("expected an array or slice, but got a reflect.Value")
	}
	out := make([]interface{}, rv.Len())
	for i := 0; i < rv.Len(); i++ { out[i] = rv.Index(i).Interface() }
	return out, nil
