func indirectValue(rv reflect.Value) reflect.Value {
	for rv.IsValid() && (rv.Kind() == reflect.Interface || rv.Kind() == reflect.Ptr) {
		if rv.IsNil() { break }
		rv = rv.Elem()
	}
	return rv
}

// GoSlice replicates text/template's slice function.
func (f *CollFuncs) GoSlice(item interface{}, indexes ...interface{}) (interface{}, error) {
	if item == nil {
		return nil, errors.New("can't slice item of type <nil>")
	}
	rv := indirectValue(reflect.ValueOf(item))
	if !rv.IsValid() {
		return nil, errors.New("can't slice item of type <nil>")
	}
	if len(indexes) > 3 {
		return nil, fmt.Errorf("too many slice indexes: %d", len(indexes))
	}
	kind := rv.Kind()
	if kind != reflect.Array && kind != reflect.Slice && kind != reflect.String {
		return nil, fmt.Errorf("can't slice item of type %s", rv.Type())
	}
	if kind == reflect.String && len(indexes) == 3 {
		return nil, errors.New("cannot 3-index slice a string")
	}
	capv := rv.Len()
	if kind == reflect.Slice { capv = rv.Cap() }
	idx := make([]int, len(indexes))
	for i, ix := range indexes {
		iv, err := sliceIndexValue(ix)
		if err != nil { return nil, err }
		idx[i] = iv
	}
	low, high, max := 0, rv.Len(), capv
	switch len(idx) {
	case 0:
		return rv.Interface(), nil
	case 1:
		low = idx[0]
	case 2:
		low, high = idx[0], idx[1]
	case 3:
		low, high, max = idx[0], idx[1], idx[2]
	}
	// validation mimicking Go template slice()
	if low < 0 || low > rv.Len() {
		return nil, fmt.Errorf("index out of range: %d", low)
	}
	if high < 0 || high > max {
		// for strings/arrays max==len; for slices high may be <=cap in 2-index? Go template checks?
		if len(idx) < 3 && high > rv.Len() {
			return nil, fmt.Errorf("index out of range: %d", high)
		}
		if len(idx) == 3 && high > max {
			return nil, fmt.Errorf("index out of range: %d", high)
		}
	}
	if low > high {
		return nil, fmt.Errorf("invalid slice index: %d > %d", low, high)
	}
	if len(idx) == 3 {
		if max < 0 || max > capv {
			return nil, fmt.Errorf("index out of range: %d", max)
		}
		if high > max {
			return nil, fmt.Errorf("invalid slice index: %d > %d", high, max)
		}
