func sliceIndexValue(ix interface{}) (int, error) {
	rv := indirectValue(reflect.ValueOf(ix))
	if !rv.IsValid() { return 0, errors.New("cannot use nil as slice index") }
	switch rv.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return int(rv.Int()), nil
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return int(rv.Uint()), nil
	case reflect.Float32, reflect.Float64:
		return int(rv.Float()), nil
	}
	iv, err := toInt64(ix)
	if err != nil { return 0, fmt.Errorf("cannot use %v as slice index", ix) }
	return int(iv), nil
