	case reflect.Map:
		kt := rv.Type().Key()
		var kv reflect.Value
		if kt.Kind() == reflect.String {
			kv = reflect.ValueOf(item).Convert(kt)
		} else {
			// try convert string to key type via conversion helpers
			// int keys etc
			switch kt.Kind() {
			case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
				if iv, err := toInt64(item); err == nil { kv = reflect.ValueOf(iv).Convert(kt) }
