			kv = ixv
		} else if ixv.Type().ConvertibleTo(kt) {
			// Be careful with int->string conversion semantics: template's index
			// would require assignable kind? Use only same-kind conversions
			if ixv.Kind() == kt.Kind() || (isNumericKind(ixv.Kind()) && isNumericKind(kt.Kind())) {
				kv = ixv.Convert(kt)
			}
		}
		if !kv.IsValid() {
			// map key display
			return nil, fmt.Errorf("map has no key %v", ix)
		}
		mv := rv.MapIndex(kv)
		if !mv.IsValid() {
			return nil, fmt.Errorf("map has no key %v", ix)
		}
