// sortable comparison
func sortValues(l []interface{}) ([]interface{}, bool) {
	if len(l) == 0 { return l, true }
	// all strings?
	allStr := true; allNum := true; allBool := true; allTime := true
	for _, v := range l {
		if _, ok := v.(string); !ok { allStr = false }
