)

type DataFuncs struct { ctx context.Context }

// Exported parsers for use by datasource code
func ParseJSON(s string) (map[string]interface{}, error) {
	// EJSON handling
	if decrypted, handled, err := maybeDecryptEJSON(s); handled {
		if err != nil { return nil, err }
		s = decrypted
	}
	out := make(map[string]interface{})
	err := yaml.Unmarshal([]byte(s), &out)
	if err != nil {
		return nil, fmt.Errorf("unable to unmarshal object %s: %w", s, err)
	}
	return out, nil
}
func ParseJSONArray(s string) ([]interface{}, error) {
	if decrypted, handled, err := maybeDecryptEJSON(s); handled {
		if err != nil { return nil, err }
		s = decrypted
	}
	out := []interface{}{nil}
	err := yaml.Unmarshal([]byte(s), &out)
	if err != nil {
		return nil, fmt.Errorf("unable to unmarshal array %s: %w", s, err)
	}
	return out, nil
}
func ParseYAML(s string) (map[string]interface{}, error) {
	out := make(map[string]interface{})
	err := yaml.Unmarshal([]byte(s), &out)
	if err != nil { return nil, err }
	return out, nil
}
func ParseYAMLArray(s string) ([]interface{}, error) {
	out := []interface{}{nil}
	err := yaml.Unmarshal([]byte(s), &out)
	if err != nil { return nil, err }
	return out, nil
}
func ParseTOML(s string) (map[string]interface{}, error) {
	out := make(map[string]interface{})
	err := toml.Unmarshal([]byte(s), &out)
	if err != nil {
		return nil, fmt.Errorf("unable to unmarshal object %s: %s", s, tomlErrorString(err))
	}
	return out, nil
}

func tomlErrorString(err error) string {
	var pe toml.ParseError
	if errors.As(err, &pe) {
		line := pe.Position.Line
		// Old BurntSushi formatted line 0 for errors at very start in
		// some cases ("=1"); we approximate: if Position.Start==0 and
		// pe.LastKey=="" and message starts with "unexpected" the old
		// parser reported line 0.
		if pe.Position.Start == 0 && pe.LastKey == "" && strings.HasPrefix(pe.Message, "unexpected") {
			line = 0
		}
		msg := pe.Message
		// messages whose wording changed
		if strings.HasPrefix(msg, "invalid datetime:") {
			msg = "Invalid TOML Datetime:" + strings.TrimPrefix(msg, "invalid datetime:") + "."
		}
		return fmt.Sprintf("Near line %d (last key parsed '%s'): %s", line, pe.LastKey, msg)
	}
	// DecodeError etc
	type hasErrorWithPosition interface{ ErrorWithPosition() string }
	return err.Error()
}

func (f *DataFuncs) JSON(in interface{}) (map[string]interface{}, error) { return ParseJSON(toString(in)) }
func (f *DataFuncs) JSONArray(in interface{}) ([]interface{}, error) { return ParseJSONArray(toString(in)) }
func (f *DataFuncs) YAML(in interface{}) (map[string]interface{}, error) { return ParseYAML(toString(in)) }
func (f *DataFuncs) YAMLArray(in interface{}) ([]interface{}, error) { return ParseYAMLArray(toString(in)) }
func (f *DataFuncs) TOML(in interface{}) (map[string]interface{}, error) { return ParseTOML(toString(in)) }

// ---- CSV ----
type csvParsed struct {
	headers []string
	rows    [][]string
}

func autoHeaders(n int) []string {
	out := make([]string, n)
	for i := 0; i < n; i++ {
		letter := string(rune('A' + (i % 26)))
		out[i] = strings.Repeat(letter, i/26+1)
	}
	return out
}

func parseCSV(args ...string) (csvParsed, error) {
	delimStr := ","
	var headers []string
	headerMode := 0 //0 first row, 1 explicit, 2 auto
	in := ""
	switch len(args) {
	case 0:
		in = ""
	case 1:
		in = args[0]
	case 2:
		if len(args[0]) == 1 {
			delimStr = args[0]
		} else if args[0] == "" {
			headerMode = 2
		} else {
			headerMode = 1
			headers = strings.Split(args[0], ",")
		}
		in = args[1]
	case 3:
		delimStr = args[0]
		headerMode = 1
		// headers split happens after reader setup in original? delim[0] panic first if empty
		// We'll set headers here but need to index delimStr[0] before to panics match
		_ = delimStr[0]
		headers = strings.Split(args[1], delimStr)
		in = args[2]
	default:
		in = ""
	}
	r := csv.NewReader(strings.NewReader(in))
	r.Comma = rune(delimStr[0])
	records, err := r.ReadAll()
	if err != nil { return csvParsed{}, err }
	if len(records) == 0 {
		if headerMode == 1 {
			return csvParsed{headers: headers, rows: records}, nil
		}
		return csvParsed{headers: nil, rows: records}, nil
	}
	switch headerMode {
	case 0:
		return csvParsed{headers: records[0], rows: records[1:]}, nil
	case 2:
		return csvParsed{headers: autoHeaders(len(records[0])), rows: records}, nil
	default:
		return csvParsed{headers: headers, rows: records}, nil
	}
}

// ParseCSVForDatasource parses using default header=first row semantics but returns all rows
func ParseCSVRecords(s string) ([][]string, error) {
	p, err := parseCSV(s)
	if err != nil { return nil, err }
	out := [][]string{p.headers}
	out = append(out, p.rows...)
	return out, nil
}

func (f *DataFuncs) CSV(args ...string) ([][]string, error) {
	p, err := parseCSV(args...); if err != nil { return nil, err }
	out := [][]string{p.headers}
	out = append(out, p.rows...)
	return out, nil
}
func (f *DataFuncs) CSVByRow(args ...string) ([]map[string]string, error) {
	p, err := parseCSV(args...); if err != nil { return nil, err }
	if len(p.rows) == 0 { return nil, nil }
	out := make([]map[string]string, len(p.rows))
	for i, row := range p.rows {
		m := make(map[string]string, len(row))
		for j, val := range row {
			// Deliberately index headers without bounds check to match panic
			m[p.headers[j]] = val
		}
		out[i] = m
	}
	return out, nil
}
func (f *DataFuncs) CSVByColumn(args ...string) (map[string][]string, error) {
	p, err := parseCSV(args...); if err != nil { return nil, err }
	out := make(map[string][]string)
	for _, row := range p.rows {
		for j, val := range row {
			k := p.headers[j]
			out[k] = append(out[k], val)
		}
	}
	return out, nil
}

func (f *DataFuncs) ToCSV(args ...interface{}) (string, error) {
	if len(args) == 0 || len(args) > 2 { return "", nil }
	delim := ','
	var in interface{}
	if len(args) == 2 {
		d := toString(args[0])
		// Original uses first rune? test later; use first rune to avoid invalid byte
		rn := []rune(d)
		if len(rn) > 0 { delim = rn[0] }
		// if empty, accessing would panic in original for parse; for ToCSV check later
		in = args[1]
	} else {
		in = args[0]
	}
	rows, err := to2DStringArray(in)
	if err != nil { return "", err }
	buf := &bytes.Buffer{}
	w := csv.NewWriter(buf)
	w.Comma = delim
	if err := w.WriteAll(rows); err != nil { return "", err }
	w.Flush()
	return buf.String(), nil
}

func to2DStringArray(in interface{}) ([][]string, error) {
	errOut := fmt.Errorf("can't parse ToCSV input - must be a two-dimensional array (like [][]string or [][]any) (was %T)", in)
	// Fast paths
	switch v := in.(type) {
	case [][]string:
		return v, nil
	case [][]interface{}:
		out := make([][]string, len(v))
		for i, row := range v {
			r := make([]string, len(row))
			for j, c := range row { r[j] = toString(c) }
			out[i] = r
		}
		return out, nil
	}
	// Reflect generic: slice of slices
	rv := reflectValueOf(in)
	if !rv.IsValid() || (rv.Kind() != reflectSlice && rv.Kind() != reflectArray) {
		return nil, errOut
	}
	out := make([][]string, rv.Len())
	for i := 0; i < rv.Len(); i++ {
		elem := rv.Index(i)
		// unwrap interface
		for elem.Kind() == reflectInterface || elem.Kind() == reflectPtr {
			if elem.IsNil() { break }
			elem = elem.Elem()
		}
		if !elem.IsValid() || (elem.Kind() != reflectSlice && elem.Kind() != reflectArray) {
			return nil, errOut
		}
		r := make([]string, elem.Len())
		for j := 0; j < elem.Len(); j++ {
			r[j] = toString(elem.Index(j).Interface())
		}
		out[i] = r
	}
	return out, nil
}

// reflect helpers (avoid importing reflect twice in a confusing way)
const (
	reflectSlice = 23 // reflect.Slice value? not stable - replaced below
	reflectArray = 17
	reflectInterface = 20
	reflectPtr = 22
)

func (f *DataFuncs) ToJSON(in interface{}) (string, error) {
	b, err := json.Marshal(in)
	if err != nil { return "", err }
	return string(b), nil
}
func (f *DataFuncs) ToJSONPretty(indent string, in interface{}) (string, error) {
	b, err := json.MarshalIndent(in, "", indent)
	if err != nil { return "", err }
	return string(b), nil
}
func (f *DataFuncs) ToYAML(in interface{}) (string, error) {
	b, err := yaml.Marshal(in)
	if err != nil { return "", err }
	return string(b), nil
}
func (f *DataFuncs) ToTOML(in interface{}) (string, error) {
	buf := &bytes.Buffer{}
	err := toml.NewEncoder(buf).Encode(in)
	if err != nil {
		return "", fmt.Errorf("unable to marshal %v: %w", in, err)
	}
	return buf.String(), nil
}
GO"}

