package funcs

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"example.com/gomplate/internal/datafs"
)

type FileFuncs struct {
	ctx context.Context
	fs  *wdFS
}

// wdFS mimics the original *datafs.wdFS pointer in %#v (approx)
type wdFS struct{}

func newFileFuncs(ctx context.Context) *FileFuncs { return &FileFuncs{ctx: ctx, fs: &wdFS{}} }

func (f *FileFuncs) Exists(path interface{}) bool {
	_, err := datafs.Stat(toString(path))
	return err == nil
}
func (f *FileFuncs) IsDir(path interface{}) bool {
	fi, err := datafs.Stat(toString(path))
	return err == nil && fi.IsDir()
}
func (f *FileFuncs) Read(path interface{}) (string, error) {
	b, err := datafs.ReadFile(toString(path))
	if err != nil { return "", err }
	return string(b), nil
}
func (f *FileFuncs) ReadDir(path interface{}) ([]string, error) {
	ents, err := datafs.ReadDir(toString(path))
	if err != nil { return nil, err }
	out := make([]string, len(ents))
	for i, e := range ents { out[i] = e.Name() }
	return out, nil
}
func (f *FileFuncs) Stat(path interface{}) (os.FileInfo, error) {
	return datafs.Stat(toString(path))
}
func (f *FileFuncs) Walk(path interface{}) ([]string, error) {
	p := toString(path)
	abs := datafs.CleanAbs(p)
	// Use filepath.Walk on absolute path but adjust root display:
	// Original returns paths as given? For "/tmp/foo" returns "/tmp/foo..." with leading slash.
	// For relative "sub" likely returns "sub", "sub/file".
	// determining display root: if p is absolute, abs; if p == "." etc filepath.Walk(p) yields "." etc.
	// We'll walk abs and then relativize display if original was relative.
	var out []string
	err := filepath.Walk(abs, func(cur string, info os.FileInfo, err error) error {
		if err != nil { return err }
		if filepath.IsAbs(p) {
			out = append(out, cur)
		} else {
			rel, rerr := filepath.Rel(abs, cur)
			if rerr != nil { out = append(out, cur); return nil }
			if rel == "." { out = append(out, p) } else { out = append(out, filepath.Join(p, rel)) }
		}
		return nil
	})
	if err != nil {
		// filepath.Walk error for root is from Lstat with abs path; rewrite to root-relative
		return nil, datafs.RewritePathErr(err)
	}
	if out == nil { out = []string{} }
	return out, nil
}

func (f *FileFuncs) Write(filename interface{}, data interface{}) (string, error) {
	name := toString(filename)
	cwd, _ := os.Getwd()
	abs := datafs.CleanAbs(name)
	rel, _ := filepath.Rel(cwd, abs)
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("failed to open %s: path %s not contained by working directory %s (rel: %s)", name, name, cwd, rel)
	}
	// Create parent directories
	dir := filepath.Dir(abs)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return "", fmt.Errorf("failed to open %s: %w", name, err)
	}
	var b []byte
	if bb, ok := data.([]byte); ok { b = bb } else { b = []byte(toString(data)) }
	if err := os.WriteFile(abs, b, 0o644); err != nil {
		return "", fmt.Errorf("failed to open %s: %w", name, err)
	}
	return "", nil
}
