	dir := filepath.Dir(abs)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return "", fmt.Errorf("failed to open %s: %w", name, err)
	}
	var b []byte
	if bb, ok := data.([]byte); ok { b = bb } else { b = []byte(toString(data)) }
	if err := os.WriteFile(abs, b, 0o644); err != nil {
		return "", fmt.Errorf("failed to open %s: %w", name, err)
	}
	return "", nil
