package funcs

import (
	"context"
	"errors"
	"fmt"
	"math/rand/v2"
	"regexp/syntax"
	"unicode"
	"unicode/utf8"
)

type RandomFuncs struct { ctx context.Context }

func randomRunesFromRegexp(count int, pattern string) (string, error) {
	if pattern == "" { pattern = `[a-zA-Z0-9_.-]` }
	re, err := syntax.Parse(pattern, syntax.Perl)
	if err != nil { return "", err }
	re = re.Simplify()
	runes := make([]rune, count)
	for i := range runes {
		r, err := genRune(re)
		if err != nil { return "", err }
		runes[i] = r
	}
	return string(runes), nil
}

func genRune(re *syntax.Regexp) (rune, error) {
	switch re.Op {
	case syntax.OpCharClass:
		// choose rune uniformly by total range size
		total := int64(0)
		for i := 0; i < len(re.Rune); i += 2 {
			total += int64(re.Rune[i+1]-re.Rune[i]) + 1
		}
		if total <= 0 { panic("invalid argument to IntN") }
		n := rand.Int64N(total)
		for i := 0; i < len(re.Rune); i += 2 {
			lo, hi := re.Rune[i], re.Rune[i+1]
			sz := int64(hi-lo) + 1
			if n < sz { return lo + rune(n), nil }
			n -= sz
		}
		panic("invalid argument to IntN")
	case syntax.OpAnyChar, syntax.OpAnyCharNotNL:
		// random printable-ish rune
		for {
			r := rune(rand.IntN(0x2fff))
			if unicode.IsPrint(r) { return r, nil }
		}
	case syntax.OpLiteral:
		if len(re.Rune) == 1 { return re.Rune[0], nil }
		panic("invalid argument to IntN")
	case syntax.OpCapture:
		if len(re.Sub) == 1 { return genRune(re.Sub[0]) }
		panic("invalid argument to IntN")
	case syntax.OpAlternate:
		if len(re.Sub) == 0 { panic("invalid argument to IntN") }
		return genRune(re.Sub[rand.IntN(len(re.Sub))])
	case syntax.OpStar, syntax.OpPlus, syntax.OpQuest, syntax.OpRepeat:
		if len(re.Sub) == 1 { return genRune(re.Sub[0]) }
		panic("invalid argument to IntN")
	default:
		panic("invalid argument to IntN")
	}
}

func (f *RandomFuncs) ASCII(count int) (string, error) {
	// make with count may panic for negative - match original
	b := make([]rune, count)
	for i := range b {
		b[i] = rune(rand.IntN(95) + 32) // 32..126
	}
	return string(b), nil
}
func (f *RandomFuncs) Alpha(count int) (string, error) {
	b := make([]rune, count)
	for i := range b {
		r, _ := genRune(mustParse(`[a-zA-Z]`))
		b[i] = r
	}
	return string(b), nil
}
func (f *RandomFuncs) AlphaNum(count int) (string, error) {
	b := make([]rune, count)
	for i := range b {
		r, _ := genRune(mustParse(`[a-zA-Z0-9]`))
		b[i] = r
	}
	return string(b), nil
}
func mustParse(p string) *syntax.Regexp {
	re, _ := syntax.Parse(p, syntax.Perl)
	return re.Simplify()
}

func boundRune(v interface{}) rune {
	// numeric types or numeric strings? Check: if ToInt succeeds and arg is not
	// a single-rune string, treat as codepoint number. A one-rune string is that rune.
	if s, ok := v.(string); ok {
		r, size := utf8.DecodeRuneInString(s)
		if size == len(s) && s != "" {
			return r
		}
		if iv, err := toInt64(s); err == nil {
			return rune(iv)
		}
		if s == "" { return 0 }
		r, _ = utf8.DecodeRuneInString(s)
		return r
	}
	iv, _ := toInt64(v)
	return rune(iv)
}

func (f *RandomFuncs) String(args ...interface{}) (string, error) {
	if len(args) == 0 {
		// signature is variadic in our implementation; template would give wrong args if non-variadic
		// Original method signature likely String(count int, args ...?) - handled by alias registration with typed func
		return "", errors.New("count must be greater than 0")
	}
	count64, err := toInt64(args[0])
	if err != nil { return "", err }
	count := int(count64)
	if count == 0 {
		return "", errors.New("count must be greater than 0")
	}
	if len(args) == 1 {
		return randomRunesFromRegexp(count, "")
	}
	if len(args) == 2 {
		return randomRunesFromRegexp(count, toString(args[1]))
	}
	// 3 or more: lower, upper, ignore rest
	lo := boundRune(args[1])
	hi := boundRune(args[2])
	// make slice first to panic on negative like original
	out := make([]rune, count)
	if int64(hi)-int64(lo)+1 <= 0 {
		panic("invalid argument to IntN")
	}
	for i := 0; i < count; {
		r := lo + rune(rand.Int64N(int64(hi)-int64(lo)+1))
		if !unicode.IsPrint(r) { continue }
		out[i] = r
		i++
	}
	return string(out), nil
}

func (f *RandomFuncs) Item(in interface{}) (interface{}, error) {
	l, err := toSlice(in)
	if err != nil { return nil, err }
	if len(l) == 0 { return nil, errors.New("expected a non-empty array or slice") }
	return l[rand.IntN(len(l))], nil
}

func (f *RandomFuncs) Number(args ...interface{}) (int64, error) {
	var minv, maxv int64 = 0, 100
	var err error
	if len(args) == 1 {
		maxv, err = toInt64(args[0]); if err != nil { return 0, fmt.Errorf("max must be a number: %w", err) }
	} else if len(args) >= 2 {
		minv, err = toInt64(args[0]); if err != nil { return 0, fmt.Errorf("min must be a number: %w", err) }
		maxv, err = toInt64(args[1]); if err != nil { return 0, fmt.Errorf("max must be a number: %w", err) }
	}
	if minv > maxv { return 0, fmt.Errorf("min must not be greater than max (was %d, %d)", minv, maxv) }
	if minv == maxv { return minv, nil }
	return rand.Int64N(maxv-minv+1) + minv, nil
}

func (f *RandomFuncs) Float(args ...interface{}) (float64, error) {
	var minv, maxv float64 = 0, 1
	var err error
	if len(args) == 1 {
		maxv, err = toFloat64(args[0]); if err != nil { return 0, fmt.Errorf("max must be a number: %w", err) }
	} else if len(args) >= 2 {
		minv, err = toFloat64(args[0]); if err != nil { return 0, fmt.Errorf("min must be a number: %w", err) }
		maxv, err = toFloat64(args[1]); if err != nil { return 0, fmt.Errorf("max must be a number: %w", err) }
	}
	if minv > maxv { return 0, fmt.Errorf("min must not be greater than max (was %v, %v)", minv, maxv) }
	if minv == maxv { return minv, nil }
	return minv + rand.Float64()*(maxv-minv), nil
}
GO"}

