package funcs

import (
	"context"
	"crypto"
	"crypto/aes"
	"crypto/cipher"
	"crypto/ecdsa"
	"crypto/ed25519"
	"crypto/elliptic"
	"crypto/hmac"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha1"
	"crypto/sha256"
	"crypto/sha512"
	"crypto/x509"
	"encoding/hex"
	"encoding/pem"
	"errors"
	"fmt"
	"hash"
	"io"

	"golang.org/x/crypto/bcrypt"
	"golang.org/x/crypto/pbkdf2"
)

type CryptoFuncs struct { ctx context.Context }

func (f *CryptoFuncs) Bcrypt(args ...interface{}) (string, error) {
	if len(args) < 1 || len(args) > 2 {
		return "", fmt.Errorf("wrong number of args: want 1 or 2, got %d", len(args))
	}
	cost := bcrypt.DefaultCost
	in := args[len(args)-1]
	if len(args) == 2 {
		c, err := toInt64(args[0])
		if err != nil { return "", fmt.Errorf("bcrypt cost must be an integer: %w", err) }
		cost = int(c)
	}
	b, err := bcrypt.GenerateFromPassword(toBytes(in), cost)
	if err != nil { return "", err }
	return string(b), nil
}

func aesKey(key interface{}, keyBits int64) []byte {
	kb := toBytes(key)
	out := make([]byte, keyBits/8)
	copy(out, kb)
	return out
}

func parseAESArgs(key interface{}, args []interface{}) (keyBytes []byte, input []byte, err error) {
	if len(args) < 1 || len(args) > 2 {
		return nil, nil, fmt.Errorf("wrong number of args: want 2 or 3, got %d", len(args))
	}
	keyBits := int64(256)
	if len(args) == 2 {
		kb, err := toInt64(args[0])
		if err != nil { return nil, nil, fmt.Errorf("keyBits must be an integer: %w", err) }
		keyBits = kb
	}
	return aesKey(key, keyBits), toBytes(args[len(args)-1]), nil
}

func pkcs7Pad(data []byte, blockSize int) []byte {
	pad := blockSize - (len(data) % blockSize)
	out := append(append([]byte{}, data...), make([]byte, pad)...)
	for i := len(data); i < len(out); i++ { out[i] = byte(pad) }
	return out
}

func (f *CryptoFuncs) EncryptAES(key interface{}, args ...interface{}) ([]byte, error) {
	if err := checkExperimental(f.ctx); err != nil { return nil, err }
	keyBytes, input, err := parseAESArgs(key, args); if err != nil { return nil, err }
	block, err := aes.NewCipher(keyBytes); if err != nil { return nil, err }
	iv := make([]byte, aes.BlockSize)
	if _, err := io.ReadFull(rand.Reader, iv); err != nil { return nil, err }
	padded := pkcs7Pad(input, aes.BlockSize)
	out := make([]byte, aes.BlockSize+len(padded))
	copy(out, iv)
	cipher.NewCBCEncrypter(block, iv).CryptBlocks(out[aes.BlockSize:], padded)
	return out, nil
}

func decryptAES(key interface{}, args []interface{}) ([]byte, error) {
	keyBytes, input, err := parseAESArgs(key, args); if err != nil { return nil, err }
	block, err := aes.NewCipher(keyBytes); if err != nil { return nil, err }
	iv := input[:aes.BlockSize]
	data := append([]byte{}, input[aes.BlockSize:]...)
	cipher.NewCBCDecrypter(block, iv).CryptBlocks(data, data)
	// unpad without validation (matches original panics)
	pad := int(data[len(data)-1])
	return data[:len(data)-pad], nil
}

func (f *CryptoFuncs) DecryptAES(key interface{}, args ...interface{}) (string, error) {
	if err := checkExperimental(f.ctx); err != nil { return "", err }
	b, err := decryptAES(key, args); if err != nil { return "", err }
	return string(b), nil
}
func (f *CryptoFuncs) DecryptAESBytes(key interface{}, args ...interface{}) ([]byte, error) {
	if err := checkExperimental(f.ctx); err != nil { return nil, err }
	return decryptAES(key, args)
}

func (f *CryptoFuncs) ECDSAGenerateKey(args ...interface{}) (string, error) {
	if err := checkExperimental(f.ctx); err != nil { return "", err }
	curveName := "P-256"
	if len(args) > 0 { curveName = toString(args[0]) }
	var curve elliptic.Curve
	switch curveName {
	case "P-224": curve = elliptic.P224()
	case "P-256": curve = elliptic.P256()
	case "P-384": curve = elliptic.P384()
	case "P-521": curve = elliptic.P521()
	default:
		return "", fmt.Errorf("invalid curve %s", curveName)
	}
	key, err := ecdsa.GenerateKey(curve, rand.Reader)
	if err != nil { return "", err }
	der, err := x509.MarshalECPrivateKey(key)
	if err != nil { return "", err }
	return string(pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: der})), nil
}

func (f *CryptoFuncs) ECDSADerivePublicKey(in interface{}) (string, error) {
	if err := checkExperimental(f.ctx); err != nil { return "", err }
	block, _ := pem.Decode(toBytes(in))
	if block == nil { return "", errors.New("failed to decode PEM block") }
	key, err := x509.ParseECPrivateKey(block.Bytes)
	if err != nil {
		// try PKCS8
		k, err2 := x509.ParsePKCS8PrivateKey(block.Bytes)
		if err2 != nil { return "", err }
		ec, ok := k.(*ecdsa.PrivateKey); if !ok { return "", errors.New("not an EC private key") }
		key = ec
	}
	der, err := x509.MarshalPKIXPublicKey(&key.PublicKey)
	if err != nil { return "", err }
	return string(pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: der})), nil
}

func (f *CryptoFuncs) Ed25519GenerateKey() (string, error) {
	if err := checkExperimental(f.ctx); err != nil { return "", err }
	_, priv, err := ed25519.GenerateKey(rand.Reader)
	if err != nil { return "", err }
	der, err := x509.MarshalPKCS8PrivateKey(priv)
	if err != nil { return "", err }
	return string(pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: der})), nil
}

