// IPRange is a minimal re-implementation compatible with go4.org/netipx IPRange
// for the methods commonly used in templates.
type IPRange struct {
	from netip.Addr
	to   netip.Addr
}

func ParseIPRange(s string) (IPRange, error) {
	parts := strings.Split(s, "-")
	if len(parts) != 2 {
		return IPRange{}, fmt.Errorf("invalid IP range %q", s)
	}
	from, err := netip.ParseAddr(strings.TrimSpace(parts[0])); if err != nil { return IPRange{}, err }
	to, err := netip.ParseAddr(strings.TrimSpace(parts[1])); if err != nil { return IPRange{}, err }
	r := IPRange{from: from, to: to}
	if !r.IsValid() { return IPRange{}, fmt.Errorf("invalid IP range %q", s) }
	return r, nil
}

func FromToIPRange(from, to netip.Addr) IPRange { return IPRange{from, to} }
func (r IPRange) From() netip.Addr { return r.from }
func (r IPRange) To() netip.Addr { return r.to }
func (r IPRange) IsValid() bool { return r.from.IsValid() && r.to.IsValid() && r.from.Is4() == r.to.Is4() && !r.to.Less(r.from) }
func (r IPRange) String() string { return r.from.String() + "-" + r.to.String() }
func (r IPRange) Contains(addr netip.Addr) bool { return !addr.Less(r.from) && !r.to.Less(addr) }

// Prefix returns a prefix if range exactly matches one, else zero.
func (r IPRange) Prefix() netip.Prefix {
	prefixes := r.Prefixes()
	if len(prefixes) == 1 { return prefixes[0] }
	return netip.Prefix{}
}

// Prefixes decomposes range into CIDR prefixes.
func (r IPRange) Prefixes() []netip.Prefix {
	if !r.IsValid() { return nil }
	var out []netip.Prefix
	cur := r.from
	for {
		// find largest prefix at cur that stays within to
		bestBits := -1
		bits := cur.BitLen()
		for b := 0; b <= bits; b++ {
			p := netip.PrefixFrom(cur, b).Masked()
			if p.Addr() != cur { continue }
			last := lastAddr(p)
			if last.Less(r.from) || r.to.Less(last) { continue }
			// we want largest block (smallest bits) that fits? Actually iterative:
			// choose smallest b that fits => largest block
			bestBits = b
			break
		}
		if bestBits < 0 { break }
		p := netip.PrefixFrom(cur, bestBits).Masked()
		out = append(out, p)
		last := lastAddr(p)
		if last == r.to { break }
		cur = last.Next()
	}
	return out
}

func lastAddr(p netip.Prefix) netip.Addr {
	// Compute last by setting host bits
	a := p.Addr()
	bits := a.BitLen()
	prefixBits := p.Bits()
	hostBits := bits - prefixBits
	if a.Is4() {
		arr := a.As4()
		for i := 0; i < hostBits; i++ {
			byteIdx := 3 - i/8
			arr[byteIdx] |= 1 << uint(i%8)
		}
		return netip.AddrFrom4(arr)
	}
	arr := a.As16()
	for i := 0; i < hostBits; i++ {
		byteIdx := 15 - i/8
		arr[byteIdx] |= 1 << uint(i%8)
	}
	return netip.AddrFrom16(arr)
}
