{"command":"cat > sockaddr/sockaddr.go <<'GO'
package sockaddr

import (
	"fmt"
	"net"
	"net/netip"
	"os/exec"
	"sort"
	"strconv"
	"strings"
)

// SockAddrType identifies address type
type SockAddrType int
const (
	TypeUnknown SockAddrType = iota
	TypeUnix
	TypeIPv4
	TypeIPv6
)
func (t SockAddrType) String() string {
	switch t { case TypeUnix: return "Unix"; case TypeIPv4: return "IPv4"; case TypeIPv6: return "IPv6"; default: return "Unknown" }
}

type SockAddr interface {
	String() string
	Type() SockAddrType
	addressString() string
}

type IPAddr netip.Addr

type IPv4Address uint32
type IPv4Mask uint32
type IPv6Address [16]byte
type IPv6Mask [16]byte

type IPv4Addr struct {
	IPAddr
	Address IPv4Address
	Mask IPv4Mask
	Port uint16
}
type IPv6Addr struct {
	IPAddr
	Address *IPv6Address
	Mask *IPv6Mask
	Port uint16
}

// helpers to convert
func ipv4ToUint32(a netip.Addr) uint32 { arr:=a.As4(); return uint32(arr[0])<<24|uint32(arr[1])<<16|uint32(arr[2])<<8|uint32(arr[3]) }
func uint32ToIPv4(v uint32) netip.Addr { return netip.AddrFrom4([4]byte{byte(v>>24),byte(v>>16),byte(v>>8),byte(v)}) }
func mask4(bits int) uint32 { if bits==0 {return 0}; return ^uint32(0) << uint(32-bits) }
func mask6(bits int) [16]byte { var a [16]byte; for i:=0;i<bits;i++{a[i/8]|=1<<uint(7-(i%8))}; return a }
func ones4(m uint32) int { c:=0; for m!=0{c+=int(m&1); m>>=1}; return c }
func ones6(m [16]byte) int { c:=0; for _,b:=range m{ for b!=0{c+=int(b&1); b>>=1}}; return c }

func (a IPv4Addr) addr() netip.Addr { return uint32ToIPv4(uint32(a.Address)) }
func (a IPv4Addr) maskBits() int { return ones4(uint32(a.Mask)) }
func (a IPv4Addr) String() string {
	bits := a.maskBits()
	if bits == 32 { return a.addr().String() }
	return fmt.Sprintf("%s/%d", a.addr(), bits)
}
func (a IPv4Addr) Type() SockAddrType { return TypeIPv4 }
func (a IPv4Addr) addressString() string { return a.addr().String() }

func (a IPv6Addr) addr() netip.Addr { if a.Address==nil {return netip.Addr{}}; return netip.AddrFrom16(*a.Address) }
func (a IPv6Addr) maskBits() int { if a.Mask==nil {return 128}; return ones6(*a.Mask) }
func (a IPv6Addr) String() string {
	bits := a.maskBits()
	if bits == 128 { return a.addr().String() }
	return fmt.Sprintf("%s/%d", a.addr(), bits)
}
func (a IPv6Addr) Type() SockAddrType { return TypeIPv6 }
func (a IPv6Addr) addressString() string { return a.addr().String() }

type IfAddr struct {
	SockAddr
	Interface net.Interface
}
type IfAddrs []IfAddr

func makeSockAddr(ip net.IP, mask net.IPMask) SockAddr {
	addr, _ := netip.AddrFromSlice(ip)
	addr = addr.Unmap()
	ones, _ := mask.Size()
	if addr.Is4() {
		return IPv4Addr{Address: IPv4Address(ipv4ToUint32(addr)), Mask: IPv4Mask(mask4(ones))}
	}
	arr := addr.As16(); m := mask6(ones)
	return IPv6Addr{Address: &arr, Mask: &m}
}

func GetAllInterfaces() (IfAddrs, error) {
	ifs, err := net.Interfaces(); if err != nil { return nil, err }
	var out IfAddrs
	for _, ifi := range ifs {
		addrs, err := ifi.Addrs(); if err != nil { continue }
		for _, ad := range addrs {
			ipnet, ok := ad.(*net.IPNet); if !ok { continue }
			out = append(out, IfAddr{SockAddr: makeSockAddr(ipnet.IP, ipnet.Mask), Interface: ifi})
		}
	}
	if out == nil { out = IfAddrs{} }
	return out, nil
}

func defaultInterfaceNames() ([]string, error) {
	out, err := exec.Command("/sbin/ip", "route", "show", "default").Output()
	if err != nil {
		// exec error original: fork/exec /sbin/ip: no such file or directory
		return nil, err
	}
	var names []string
	for _, line := range strings.Split(string(out), "\n") {
		fields := strings.Fields(line)
		for i, f := range fields {
			if f == "dev" && i+1 < len(fields) { names = append(names, fields[i+1]) }
		}
	}
	return names, nil
}

func GetDefaultInterfaces() (IfAddrs, error) {
	names, err := defaultInterfaceNames(); if err != nil { return nil, err }
	all, err := GetAllInterfaces(); if err != nil { return nil, err }
	var out IfAddrs
	for _, a := range all {
		for _, n := range names { if a.Interface.Name == n { out = append(out, a) } }
	}
	if out == nil { out = IfAddrs{} }
	return out, nil
}

func AddrOf(a IfAddr) netip.Addr {
	switch v := a.SockAddr.(type) {
	case IPv4Addr: return v.addr()
	case IPv6Addr: return v.addr()
	default: return netip.Addr{}
	}
}
func MaskBitsOf(a IfAddr) int {
	switch v := a.SockAddr.(type) { case IPv4Addr: return v.maskBits(); case IPv6Addr: return v.maskBits(); default: return 0 }
}
func IsForwardable(a netip.Addr) bool {
	if !a.IsValid() || a.IsUnspecified() || a.IsLoopback() || a.IsMulticast() || a.IsLinkLocalUnicast() || a.IsLinkLocalMulticast() { return false }
	return true
}
func IsPrivateAddr(a netip.Addr) bool {
	// RFC6890 addresses that are considered private by go-sockaddr for GetPrivate*
	// netip IsPrivate covers RFC1918, RFC6598 and ULA
	return a.IsPrivate()
}

func GetPrivateInterfaces() (IfAddrs, error) {
	defs, err := GetDefaultInterfaces()
	if err != nil { return IfAddrs{}, nil }
	out := IfAddrs{}
	for _, a := range defs { addr:=AddrOf(a); if IsPrivateAddr(addr) && IsForwardable(addr) { out=append(out,a) } }
	return out, nil
}
func GetPublicInterfaces() (IfAddrs, error) {
	defs, err := GetDefaultInterfaces()
	if err != nil { return IfAddrs{}, nil }
	out := IfAddrs{}
	for _, a := range defs { addr:=AddrOf(a); if !IsPrivateAddr(addr) && IsForwardable(addr) && addr.IsGlobalUnicast() { out=append(out,a) } }
	return out, nil
}

func privateIPs(all IfAddrs) []string {
	var ips []string
	for _, a := range all { addr:=AddrOf(a); if IsPrivateAddr(addr) && IsForwardable(addr) { ips=append(ips, addr.String()) } }
	return ips
}
func publicIPs(all IfAddrs) []string {
	var ips []string
	for _, a := range all { addr:=AddrOf(a); if !IsPrivateAddr(addr) && IsForwardable(addr) && addr.IsGlobalUnicast() { ips=append(ips, addr.String()) } }
	return ips
}
func GetPrivateIP() string {
	ifs, _ := GetPrivateInterfaces()
	if len(ifs)==0 { return "" }
	return AddrOf(ifs[0]).String()
}
func GetPrivateIPs() string {
	all,_:=GetAllInterfaces(); return strings.Join(privateIPs(all)," ")
}
func GetPublicIP() string {
	ifs,_:=GetPublicInterfaces(); if len(ifs)==0 {return ""}; return AddrOf(ifs[0]).String()
}
func GetPublicIPs() string { all,_:=GetAllInterfaces(); return strings.Join(publicIPs(all)," ") }

func SortBySize(addrs IfAddrs) IfAddrs {
	out:=append(IfAddrs{},addrs...)
	sort.SliceStable(out, func(i,j int)bool{ return MaskBitsOf(out[i]) < MaskBitsOf(out[j]) })
	return out
}
func GetInterfaceIPs(name string) string {
	all,_:=GetAllInterfaces()
	var filtered IfAddrs
	for _,a:=range all{ if a.Interface.Name==name {filtered=append(filtered,a)} }
	filtered=SortBySize(filtered)
	ips:=make([]string,len(filtered)); for i,a:=range filtered{ips[i]=AddrOf(a).String()}
	return strings.Join(ips," ")
}
func GetInterfaceIP(name string) string {
	all,_:=GetAllInterfaces()
	var filtered IfAddrs
	for _,a:=range all{ addr:=AddrOf(a); if a.Interface.Name==name && IsForwardable(addr) {filtered=append(filtered,a)} }
	filtered=SortBySize(filtered)
	if len(filtered)==0 {return ""}
	return AddrOf(filtered[0]).String()
}

// helpers for selectors
func NetworkAddr(a IfAddr) netip.Addr {
	addr:=AddrOf(a); bits:=MaskBitsOf(a)
	return netip.PrefixFrom(addr,bits).Masked().Addr()
}
func BroadcastAddr(a IfAddr) netip.Addr {
	addr:=AddrOf(a); bits:=MaskBitsOf(a); p:=netip.PrefixFrom(addr,bits).Masked()
	// last addr of prefix - compute for v4/v6
	if addr.Is4() {
		base:=ipv4ToUint32(p.Addr()); host:=uint32(0); if bits<32 {host=(uint32(1)<<uint(32-bits))-1}; return uint32ToIPv4(base|host)
	}
	// v6
	arr:=p.Addr().As16(); for i:=bits;i<128;i++{arr[i/8]|=1<<uint(7-(i%8))}; return netip.AddrFrom16(arr)
}
func NetmaskAddr(a IfAddr) netip.Addr {
	addr:=AddrOf(a); bits:=MaskBitsOf(a)
	if addr.Is4(){ return uint32ToIPv4(mask4(bits)) }
	arr:=mask6(bits); return netip.AddrFrom16(arr)
}
func NetworkSize(a IfAddr) uint64 {
	addr:=AddrOf(a); total:=addr.BitLen(); mb:=MaskBitsOf(a); host:=total-mb
	if host>=64 { return ^uint64(0) }
	return uint64(1)<<uint(host)
}
func PortOf(a IfAddr) uint16 {
	switch v:=a.SockAddr.(type){case IPv4Addr:return v.Port;case IPv6Addr:return v.Port;default:return 0}
}
func SetPortOf(a *IfAddr, p uint16) { switch v:=a.SockAddr.(type){case IPv4Addr:v.Port=p;a.SockAddr=v;case IPv6Addr:v.Port=p;a.SockAddr=v} }
func TypeName(a IfAddr) string { if a.SockAddr==nil {return "Unknown"}; return a.SockAddr.Type().String() }

func Attr(name string, a IfAddr) (string,error) {
	switch strings.ToLower(name) {
	case "address": return AddrOf(a).String(),nil
	case "host": return AddrOf(a).String(),nil
	case "network": return NetworkAddr(a).String(),nil
	case "netmask": return NetmaskAddr(a).String(),nil
	case "broadcast": return BroadcastAddr(a).String(),nil
	case "port": return strconv.Itoa(int(PortOf(a))),nil
	case "size": return strconv.FormatUint(NetworkSize(a),10),nil
	case "type": return TypeName(a),nil
	case "name": return a.Interface.Name,nil
	case "flags": return a.Interface.Flags.String(),nil
	case "string": return a.SockAddr.String(),nil
	default:
		return "", fmt.Errorf("unsupported attribute name %q", strings.ToLower(name))
	}
}
GO"}

