func (f *SockaddrFuncs) GetDefaultInterfaces() (sockaddr.IfAddrs, error) { return sockaddr.GetDefaultInterfaces() }
func (f *SockaddrFuncs) GetPrivateInterfaces() (sockaddr.IfAddrs, error) { return sockaddr.GetPrivateInterfaces() }
func (f *SockaddrFuncs) GetPublicInterfaces() (sockaddr.IfAddrs, error) { return sockaddr.GetPublicInterfaces() }
