func (f *SockaddrFuncs) GetInterfaceIP(name string) string { return sockaddr.GetInterfaceIP(name) }
func (f *SockaddrFuncs) GetInterfaceIPs(name string) string { return sockaddr.GetInterfaceIPs(name) }

func sortKeyCompare(a,b sockaddr.IfAddr, selector string) int {
	switch strings.ToLower(selector) {
	case "address":
		return sockaddr.AddrOf(a).Compare(sockaddr.AddrOf(b))
	case "default":
		// approximate: default interfaces first if mismatch
		// determine names - caller can pass? use GetDefaultInterfaces but may error => equal
		return 0
	case "name":
		return strings.Compare(a.Interface.Name,b.Interface.Name)
	case "port":
		pa,pb:=sockaddr.PortOf(a),sockaddr.PortOf(b); if pa<pb{return -1}; if pa>pb{return 1}; return 0
	case "size":
		ba,bb:=sockaddr.MaskBitsOf(a),sockaddr.MaskBitsOf(b); if ba<bb{return -1}; if ba>bb{return 1}; return 0
	case "type":
		ord:=func(t string)int{switch t{case "Unix":return 0;case "IPv4":return 1;case "IPv6":return 2;default:return 3}}
		oa,ob:=ord(sockaddr.TypeName(a)),ord(sockaddr.TypeName(b)); if oa<ob{return -1}; if oa>ob{return 1}; return 0
