	case "down": return a.Interface.Flags&net.FlagUp==0,nil
	case "up": return a.Interface.Flags&net.FlagUp!=0,nil
	case "loopback": return addr.IsLoopback() || a.Interface.Flags&net.FlagLoopback!=0,nil
	case "multicast": return addr.IsMulticast() || a.Interface.Flags&net.FlagMulticast!=0,nil
	case "point-to-point": return a.Interface.Flags&net.FlagPointToPoint!=0,nil
	case "forwardable": return sockaddr.IsForwardable(addr),nil
	case "global unicast": return addr.IsGlobalUnicast(),nil
	case "interface-local multicast": return addr.IsInterfaceLocalMulticast(),nil
	case "link-local multicast": return addr.IsLinkLocalMulticast(),nil
	case "link-local unicast": return addr.IsLinkLocalUnicast(),nil
	case "unspecified": return addr.IsUnspecified(),nil
	default:
		return false, fmt.Errorf("unsupported flag %q", value)
	}
}
func rfcMatch(value string, addr netip.Addr) (bool,error) {
	switch value {
	case "1918": return addr.IsPrivate(),nil
	case "6598": // 100.64/10 shared - netip IsPrivate includes it
		p:=netip.MustParsePrefix("100.64.0.0/10"); return p.Contains(addr),nil
	case "6890":
		// Special ranges approximation: not global unicast OR private etc.
		// go-sockaddr RFC6890 includes many iana special registries. Use property:
		return !addr.IsGlobalUnicast() ,nil
	case "3330","3927":
		return addr.IsLinkLocalUnicast() || addr.IsLinkLocalMulticast(),nil
	case "4291": return addr.Is6(),nil
	case "919","1112","1122","1700","2544","2765","3068","3171","4038","4380","4773","4824","5735":
