		return !addr.IsGlobalUnicast(),nil
	}
	return false, fmt.Errorf("unsupported RFC %q", value)
}
func (f *SockaddrFuncs) Include(selector string, value string, in sockaddr.IfAddrs) (sockaddr.IfAddrs,error) {
	// Validate selector first even if empty list
	valid:=map[string]bool{"address":true,"flag":true,"name":true,"network":true,"port":true,"rfc":true,"size":true,"type":true}
	if !valid[strings.ToLower(selector)] { return nil, fmt.Errorf("invalid include selector %q", selector) }
	out:=sockaddr.IfAddrs{}
	for _,a:=range in { ok,err:=includeMatch(selector,value,a); if err!=nil{return nil,err}; if ok{out=append(out,a)} }
	return out,nil
}
func (f *SockaddrFuncs) Exclude(selector string, value string, in sockaddr.IfAddrs) (sockaddr.IfAddrs,error) {
	valid:=map[string]bool{"address":true,"flag":true,"name":true,"network":true,"port":true,"rfc":true,"size":true,"type":true}
	if !valid[strings.ToLower(selector)] { return nil, fmt.Errorf("invalid exclude selector %q", selector) }
	out:=sockaddr.IfAddrs{}
