		return v[0],nil
	case sockaddr.IfAddr:
		return v,nil
	default:
		// Try toSlice
		l,err:=toSlice(in); if err!=nil{return sockaddr.IfAddr{},err}
		if len(l)==0{return sockaddr.IfAddr{}, fmt.Errorf("no IfAddrs")}
		if a,ok:=l[0].(sockaddr.IfAddr);ok{return a,nil}
