	return strings.Join(parts,sep),nil
}
func (f *SockaddrFuncs) Limit(limit int, in sockaddr.IfAddrs) sockaddr.IfAddrs {
	if limit<0{return sockaddr.IfAddrs{}}; if limit>len(in){limit=len(in)}; return append(sockaddr.IfAddrs{},in[:limit]...)
}
func (f *SockaddrFuncs) Offset(offset int, in sockaddr.IfAddrs) sockaddr.IfAddrs {
	if offset<0{offset=0}; if offset>len(in){return sockaddr.IfAddrs{}}; return append(sockaddr.IfAddrs{},in[offset:]...)
}
