func WithAddr(orig IfAddr, na netip.Addr) IfAddr {
	bits := MaskBitsOf(orig)
	var mask net.IPMask
	if na.Is4() { mask = net.CIDRMask(bits, 32) } else { mask = net.CIDRMask(bits, 128) }
