package semver

import (
	"fmt"
	"strings"
)

func parseConstraintGroup(s string) ([]constraint, error) {
	// Split by commas not inside? simple, then tokens by whitespace merge operators
	s = strings.TrimSpace(s)
	if s=="" { return []constraint{{op:"*"}}, nil }
	// Split hyphen range "1.2 - 2.0" or "1.2-2.0" (complicated because prerelease hyphens)
	// Handle explicit " - " separator first
	if strings.Contains(s, " - ") {
		parts:=strings.SplitN(s," - ",2)
		lo,err:=NewVersion(strings.TrimSpace(parts[0])); if err!=nil{return nil,err}
		hi,err:=NewVersion(strings.TrimSpace(parts[1])); if err!=nil{return nil,err}
		return []constraint{{op:">=",v:lo},{op:"<=",v:hi}},nil
	}
	var cons []constraint
	for _, part := range strings.Split(s, ",") {
		part=strings.TrimSpace(part); if part==""{continue}
		// part may contain space separated multiple constraints like ">= 1.0 < 2.0" or ">=1.0 <2.0"
		toks:=tokenizeConstraint(part)
		for _, tok := range toks {
			c, err:=parseOneConstraint(tok); if err!=nil{return nil,err}
			cons=append(cons,c...)
		}
	}
	if len(cons)==0 { cons=append(cons,constraint{op:"*"}) }
	return cons,nil
}
func tokenizeConstraint(s string) []string {
	// Split by whitespace but ops may be attached; combine standalone op with following version
	fields:=strings.Fields(s)
	var out []string
	for i:=0;i<len(fields);i++{
		f:=fields[i]
		if isOperator(f) && i+1<len(fields) { out=append(out,f+fields[i+1]); i++ } else { out=append(out,f) }
	}
	return out
}
func isOperator(s string) bool {
	switch s{case ">",">=","<","<=","=","==","!=","~","^","~>",">=":return true}
	return false
}
func parseOneConstraint(tok string) ([]constraint,error) {
	tok=strings.TrimSpace(tok)
	if tok==""||tok=="*"||tok=="x"||tok=="X" {return []constraint{{op:"*"}},nil}
	orig:=tok
	op:="="
	rest:=tok
	for _, p := range []string{">=","<=",">","<","==","!=","~>", "~","^","="} {
		if strings.HasPrefix(tok,p){op=p; rest=strings.TrimSpace(strings.TrimPrefix(tok,p)); break}
	}
	if op=="=="{op="="}
	// Wildcards: 1.2.x, 1.x, v1.2.*
