	case "~", "~>":
		// ~1.2.3 := >=1.2.3 <1.3.0 ; ~1.2 := >=1.2.0 <1.3.0 ; ~1 := >=1.0.0 <2.0.0
		// parts count based on rest (strip v)
		parts:=countParts(rest)
		var hi *Version
		if parts>=3{ hi=&Version{major:v.major,minor:v.minor+1} } else if parts==2{ hi=&Version{major:v.major,minor:v.minor+1} } else { hi=&Version{major:v.major+1} }
		return []constraint{{op:">=",v:v},{op:"<",v:hi}},nil
	case "^":
		var hi *Version
		if v.major>0{ hi=&Version{major:v.major+1} } else if v.minor>0{ hi=&Version{major:0,minor:v.minor+1} } else { hi=&Version{major:0,minor:0,patch:v.patch+1} }
		return []constraint{{op:">=",v:v},{op:"<",v:hi}},nil
