func wildcardConstraints(op string, rest string, orig string) ([]constraint,error) {
	// Replace x/* with 0 for low; high is increment of last numeric part before wildcard
	clean:=strings.TrimPrefix(rest,"v")
	if idx:=strings.IndexAny(clean,"-+"); idx>=0 {clean=clean[:idx]}
	parts:=strings.Split(clean,".")
	// find wildcard index
	wi:=-1
	for i,p:=range parts{ if p=="x"||p=="X"||p=="*"{wi=i;break} }
	if wi==-1{return nil,fmt.Errorf("invalid constraint %q",orig)}
	if wi==0{return []constraint{{op:"*"}},nil}
	// low version with zeros
	lowParts:=make([]string,3); for i:=0;i<3;i++{ if i<wi && i<len(parts){lowParts[i]=parts[i]}else{lowParts[i]="0"} }
	low,_:=NewVersion(strings.Join(lowParts,"."))
	// high increments part wi-1
	highParts:=append([]string{},lowParts...)
	// increment
	// parse int
	var hi *Version
	switch wi-1{
	case 0: hi=&Version{major:low.major+1}
	case 1: hi=&Version{major:low.major,minor:low.minor+1}
	case 2: hi=&Version{major:low.major,minor:low.minor,patch:low.patch+1}
	}
	_ = highParts
	if op=="=" {
		return []constraint{{op:">=",v:low},{op:"<",v:hi}},nil
	}
	// For other ops Masterminds has complex semantics, approximate as wildcard range combined with op on low
	return []constraint{{op:op,v:low}},nil
