func checkOne(c constraint, v *Version) bool {
	switch c.op{
	case "*": return true
	case "=": return v.Compare(c.v)==0
	case "!=": return v.Compare(c.v)!=0
	case ">": return v.Compare(c.v)>0
	case "<": return v.Compare(c.v)<0
	case ">=": return v.Compare(c.v)>=0
	case "<=": return v.Compare(c.v)<=0
	}
	return false
}
