package funcs
import ("encoding/json"; "fmt"; "strings")
func maybeDecryptEJSON(s string) (string,bool,error) {
	// detect _public_key field in a JSON object (cheap)
	var probe map[string]json.RawMessage
	if err:=json.Unmarshal([]byte(s),&probe); err!=nil { return "",false,nil }
	raw,ok:=probe["_public_key"]; if !ok{return "",false,nil}
	var pub string
	if err:=json.Unmarshal(raw,&pub); err!=nil{ return "",true,fmt.Errorf("public key has invalid format") }
	_ = pub
	dec,err:=decryptEJSONDocument(s,pub)
	_ = strings.TrimSpace
	return dec,true,err
}
GO
cat > funcs/ejson_impl.go <<'GO'
package funcs
import "fmt"
func decryptEJSONDocument(s string, pub string) (string,error) {
	// validation for public key format - real implementation in ejson_decrypt.go
	if !isValidEJSONPublicKey(pub) { return "", fmt.Errorf("public key has invalid format") }
	return decryptEJSON(s,pub)
}
