{"command":"cat > io.go <<'GO'
package gomplate

import (
	"context"
	"io"
	"os"
)

type ioKey struct{}

type IO struct {
	Stdin  io.Reader
	Stdout io.Writer
	Stderr io.Writer
}

func WithIO(ctx context.Context, v IO) context.Context {
	return context.WithValue(ctx, ioKey{}, v)
}
func IOFromContext(ctx context.Context) IO {
	if ctx != nil {
		if v, ok := ctx.Value(ioKey{}).(IO); ok {
			if v.Stdin == nil { v.Stdin = os.Stdin }
			if v.Stdout == nil { v.Stdout = os.Stdout }
			if v.Stderr == nil { v.Stderr = os.Stderr }
			return v
		}
	}
	return IO{Stdin: os.Stdin, Stdout: os.Stdout, Stderr: os.Stderr}
}
GO
