func (c *Config) SetExtraHeaders(h map[string]http.Header) { c.extraHeaders = h }
func (c *Config) ExtraHeaders() map[string]http.Header { return c.extraHeaders }
'''
p.write_text(s)
# funcs export ToBoolValue
p=pathlib.Path("funcs/conv.go"); s=p.read_text()
