{"command":"cat > internal/config/parse.go <<'GO'
package config

import (
	"fmt"
	"net/http"
	"strings"
)

// ParseDataSourceArg parses alias=URL or implicit file forms.
func ParseDataSourceArg(arg string) (string, DataSource, error) {
	alias, rawURL, found := strings.Cut(arg, "=")
	if !found || rawURL == "" {
		rawCandidate := alias
		if strings.Contains(arg, "/") || rawCandidate == "" {
			return "", DataSource{}, fmt.Errorf("invalid argument (%s): must provide an alias with files not in working directory", arg)
		}
		alias = strings.Split(arg, ".")[0]
		rawURL = rawCandidate
	}
	u, err := ParseURL(rawURL)
	if err != nil {
		return "", DataSource{}, err
	}
	return alias, NewDataSource(u, nil), nil
}

// ParseTemplateArg parses alias=url or url forms.
func ParseTemplateArg(arg string) (string, DataSource, error) {
	alias, rawURL, found := strings.Cut(arg, "=")
	if !found {
		alias = arg
		rawURL = arg
	}
	if rawURL == "" {
		rawURL = alias
	}
	u, err := ParseURL(rawURL)
	if err != nil {
		return "", DataSource{}, err
	}
	return alias, NewDataSource(u, nil), nil
}

// ParseHeaderArgs parses alias=Name: value entries.
func ParseHeaderArgs(args []string) (map[string]http.Header, error) {
	out := make(map[string]http.Header)
	for _, arg := range args {
		alias, hdr, found := strings.Cut(arg, "=")
		if !found {
			return nil, fmt.Errorf("invalid datasource-header option '%s'", arg)
		}
		k, v, found := strings.Cut(hdr, ":")
		if !found {
			return nil, fmt.Errorf("invalid HTTP Header format '%s'", hdr)
		}
		if out[alias] == nil {
			out[alias] = http.Header{}
		}
		out[alias].Add(k, strings.TrimSpace(v))
	}
	return out, nil
}
GO"}

