{"command":"cat > internal/cmd/main.go <<'GO'
package cmd

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"net/http"
	"os"
	"os/exec"
	"strings"
	"time"

	"example.com/gomplate"
	"example.com/gomplate/funcs"
	"example.com/gomplate/internal/config"
	"example.com/gomplate/internal/datafs"
	"example.com/gomplate/internal/logging"
	"github.com/spf13/cobra"
	"gopkg.in/yaml.v3"
)

type flagValues struct {
	datasources []string
	headers     []string
	contexts    []string
	plugins     []string
	files       []string
	in          string
	inputDir    string
	excludes    []string
	excludeProc []string
	includes    []string
	outs        []string
	templates   []string
	outputDir   string
	outputMap   string
	chmod       string
	execPipe    bool
	leftDelim   string
	rightDelim  string
	missingKey  string
	experimental bool
	verbose     bool
	configFile  string
}

// Main runs gomplate and returns an exit code.
func Main(ctx context.Context, args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	logState := logging.NewState()
	ctx = logging.WithState(ctx, logState)
	cmd := NewGomplateCmd(ctx, logState)
	cmd.SetArgs(args)
	cmd.SetIn(stdin)
	cmd.SetOut(stdout)
	cmd.SetErr(stderr)
	// Store stdio in ctx for Run/logging? ctx is passed via ExecuteContext
	err := cmd.ExecuteContext(ctx)
	if err != nil {
		if logState.Initialized {
			logState.Logger.Error("", "err", err.Error())
		} else {
			logging.EarlyError(stderr, err)
		}
		return 1
	}
	return 0
}

func envOr(name, def string) string {
	if v := os.Getenv(name); v != "" {
		return v
	}
	return def
}

func NewGomplateCmd(ctx context.Context, logState *logging.State) *cobra.Command {
	fv := &flagValues{}
	cmd := &cobra.Command{
		Use:     "gomplate",
		Short:   "Process text files with Go templates",
		Version: "0.0.0",
		PersistentPreRun: func(cmd *cobra.Command, args []string) {
			logging.Setup(cmd.Context(), fv.verbose)
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := loadConfig(cmd, fv, args, logState)
			if err != nil {
				return err
			}
			cmd.SilenceUsage = true
			cmd.SilenceErrors = true
			logger := logging.Logger(cmd.Context())
			logger.Debug("starting gomplate")
			logger.Debug(fmt.Sprintf("config is:\n---\n%s", cfg.String()), "version", "0.0.0", "build", "HEAD")
			stdout := cmd.OutOrStdout()
			outWriter := stdout
			var buf *bytes.Buffer
			if cfg.ExecPipe {
				buf = &bytes.Buffer{}
				outWriter = buf
			}
			runCtx := gomplate.WithIO(cmd.Context(), gomplate.IO{Stdin: cmd.InOrStdin(), Stdout: outWriter, Stderr: cmd.ErrOrStderr()})
			if err := gomplate.Run(runCtx, cfg); err != nil {
				return err
			}
			if len(cfg.PostExec) > 0 {
				logging.Logger(cmd.Context()).Debug("running post-exec command", "args", cfg.PostExec)
				ec := exec.Command(cfg.PostExec[0], cfg.PostExec[1:]...)
				if cfg.ExecPipe {
					ec.Stdin = buf
				} else {
					ec.Stdin = cmd.InOrStdin()
				}
				ec.Stdout = stdout
				ec.Stderr = cmd.ErrOrStderr()
				if err := ec.Run(); err != nil {
					return err
				}
			}
			return nil
		},
	}
	flags := cmd.Flags()
	flags.SortFlags = false
