func buildFlagConfig(cmd *cobra.Command, fv *flagValues, args []string) (*gomplate.Config, map[string]http.Header, error) {
	cfg := &gomplate.Config{}
	// Datasources
	if len(fv.datasources) > 0 {
		cfg.Datasources = make(map[string]config.DataSource)
		for _, a := range fv.datasources {
			alias, ds, err := config.ParseDataSourceArg(a)
			if err != nil { return nil, nil, err }
			cfg.Datasources[alias] = ds
		}
	}
	// Context
	if len(fv.contexts) > 0 {
		cfg.Context = make(map[string]config.DataSource)
		for _, a := range fv.contexts {
			alias, ds, err := config.ParseDataSourceArg(a)
			if err != nil { return nil, nil, err }
			cfg.Context[alias] = ds
		}
	}
	// Templates
	if len(fv.templates) > 0 {
		cfg.Templates = make(map[string]config.DataSource)
		for _, a := range fv.templates {
			alias, ds, err := config.ParseTemplateArg(a)
			if err != nil { return nil, nil, err }
			cfg.Templates[alias] = ds
		}
	}
	// Headers
	headers, err := config.ParseHeaderArgs(fv.headers)
	if err != nil { return nil, nil, err }
	assignHeaders := func(m map[string]config.DataSource) {
		for alias, ds := range m {
			if h, ok := headers[alias]; ok {
				ds.Header = h
				m[alias] = ds
			}
		}
	}
	assignHeaders(cfg.Datasources)
	assignHeaders(cfg.Context)
	assignHeaders(cfg.Templates)
	cfg.SetExtraHeaders(headers)
	// Plugins
	if len(fv.plugins) > 0 {
		cfg.Plugins = make(map[string]gomplate.PluginConfig)
		for _, a := range fv.plugins {
			name, path, found := strings.Cut(a, "=")
			if !found {
				return nil, nil, errors.New("plugin requires both name and path")
			}
			cfg.Plugins[name] = gomplate.PluginConfig{Cmd: path}
		}
	}
	// Simple fields only if changed
	if changed(cmd, "in") { cfg.In = fv.in }
	if changed(cmd, "input-dir") { cfg.InputDir = fv.inputDir }
	if changed(cmd, "file") { cfg.InputFiles = append([]string{}, fv.files...) }
	if changed(cmd, "out") { cfg.OutputFiles = append([]string{}, fv.outs...) }
	if changed(cmd, "output-dir") { cfg.OutputDir = fv.outputDir }
	if changed(cmd, "output-map") { cfg.OutputMap = fv.outputMap }
	if changed(cmd, "chmod") { cfg.Chmod = fv.chmod }
	if changed(cmd, "left-delim") { cfg.LeftDelim = fv.leftDelim }
	if changed(cmd, "right-delim") { cfg.RightDelim = fv.rightDelim }
	if changed(cmd, "missing-key") { cfg.MissingKey = fv.missingKey }
	if changed(cmd, "exec-pipe") { cfg.ExecPipe = fv.execPipe }
	if changed(cmd, "experimental") { cfg.Experimental = fv.experimental }
	if changed(cmd, "exclude") || changed(cmd, "include") {
		var ex []string
		if len(fv.includes) > 0 {
			ex = append(ex, "*")
			for _, inc := range fv.includes { ex = append(ex, "!"+inc) }
		}
		ex = append(ex, fv.excludes...)
		cfg.Excludes = ex
	}
	if changed(cmd, "exclude-processing") { cfg.ExcludeProcessing = append([]string{}, fv.excludeProc...) }
	if len(args) > 0 { cfg.PostExec = append([]string{}, args...) }
	return cfg, headers, nil
}

func mergeFlagIntoFile(fileCfg, flagCfg *gomplate.Config) *gomplate.Config {
	cfg := fileCfg
	// maps
	if len(flagCfg.Datasources) > 0 {
		if cfg.Datasources == nil { cfg.Datasources = make(map[string]config.DataSource) }
		for k, v := range flagCfg.Datasources { cfg.Datasources[k] = v }
	}
	if len(flagCfg.Context) > 0 {
		if cfg.Context == nil { cfg.Context = make(map[string]config.DataSource) }
		for k, v := range flagCfg.Context { cfg.Context[k] = v }
	}
	if len(flagCfg.Templates) > 0 {
		if cfg.Templates == nil { cfg.Templates = make(map[string]config.DataSource) }
		for k, v := range flagCfg.Templates { cfg.Templates[k] = v }
	}
	if len(flagCfg.Plugins) > 0 {
		if cfg.Plugins == nil { cfg.Plugins = make(map[string]gomplate.PluginConfig) }
		for k, v := range flagCfg.Plugins { cfg.Plugins[k] = v }
	}
	// input mode by priority In > InputDir > InputFiles
	if flagCfg.In != "" || flagCfg.InputDir != "" || len(flagCfg.InputFiles) > 0 {
		keepOutputDir := cfg.OutputDir
		if flagCfg.In != "" {
			cfg.In = flagCfg.In; cfg.InputFiles = nil; cfg.InputDir = ""; cfg.OutputDir = ""
		} else if flagCfg.InputDir != "" {
			cfg.InputDir = flagCfg.InputDir; cfg.In = ""; cfg.InputFiles = nil; cfg.OutputDir = keepOutputDir
		} else {
			cfg.InputFiles = flagCfg.InputFiles; cfg.In = ""; cfg.InputDir = ""; cfg.OutputDir = ""
		}
	}
	// output mode by priority OutputFiles > OutputDir > OutputMap
	if len(flagCfg.OutputFiles) > 0 || flagCfg.OutputDir != "" || flagCfg.OutputMap != "" {
		if len(flagCfg.OutputFiles) > 0 {
			cfg.OutputFiles = flagCfg.OutputFiles; cfg.OutputDir = ""; cfg.OutputMap = ""
		} else if flagCfg.OutputDir != "" {
			cfg.OutputDir = flagCfg.OutputDir; cfg.OutputFiles = nil; cfg.OutputMap = ""
		} else {
			cfg.OutputMap = flagCfg.OutputMap; cfg.OutputFiles = nil; cfg.OutputDir = ""
		}
	}
	if len(flagCfg.Excludes) > 0 { cfg.Excludes = flagCfg.Excludes }
	if len(flagCfg.ExcludeProcessing) > 0 { cfg.ExcludeProcessing = flagCfg.ExcludeProcessing }
	if flagCfg.Chmod != "" { cfg.Chmod = flagCfg.Chmod }
	if flagCfg.LeftDelim != "" { cfg.LeftDelim = flagCfg.LeftDelim }
	if flagCfg.RightDelim != "" { cfg.RightDelim = flagCfg.RightDelim }
	if flagCfg.MissingKey != "" { cfg.MissingKey = flagCfg.MissingKey }
	if len(flagCfg.PostExec) > 0 { cfg.PostExec = flagCfg.PostExec }
	if flagCfg.PluginTimeout != 0 { cfg.PluginTimeout = flagCfg.PluginTimeout }
	cfg.ExecPipe = cfg.ExecPipe || flagCfg.ExecPipe
	cfg.Experimental = cfg.Experimental || flagCfg.Experimental
	if flagCfg.ExtraHeaders() != nil { cfg.SetExtraHeaders(flagCfg.ExtraHeaders()) }
	return cfg
}

func loadConfig(cmd *cobra.Command, fv *flagValues, args []string, logState *logging.State) (*gomplate.Config, error) {
	flagCfg, _, err := buildFlagConfig(cmd, fv, args)
	if err != nil { return nil, err }
	cfgFile := fv.configFile
	requested := changed(cmd, "config")
	disabled := false
	if v, present := os.LookupEnv("GOMPLATE_CONFIG"); present {
		if v == "" {
			disabled = true
		} else if !requested {
			cfgFile = v
			requested = true
		}
	}
	if cfgFile == "" { disabled = true }
	var cfg *gomplate.Config
	if disabled {
		cfg = flagCfg
	} else {
		f, err := datafs.Open(cfgFile)
		if err != nil {
			if requested {
				return nil, fmt.Errorf("config file requested, but couldn't be opened: %w", err)
			}
			if !errors.Is(err, fs.ErrNotExist) {
				return nil, fmt.Errorf("config file requested, but couldn't be opened: %w", err)
			}
			cfg = flagCfg
		} else {
			fileCfg := &gomplate.Config{}
			dec := yaml.NewDecoder(f)
			derr := dec.Decode(fileCfg)
			f.Close()
			if derr != nil && !errors.Is(derr, io.EOF) {
				return nil, fmt.Errorf("parsing config file %q: YAML decoding failed, syntax may be invalid: %w", cfgFile, derr)
			}
			logging.Logger(cmd.Context()).Debug("using config file", "cfgFile", cfgFile)
			cfg = mergeFlagIntoFile(fileCfg, flagCfg)
		}
	}
	// env fallbacks
	if cfg.LeftDelim == "" {
		if v, ok := os.LookupEnv("GOMPLATE_LEFT_DELIM"); ok && v != "" { cfg.LeftDelim = v }
	}
	if cfg.RightDelim == "" {
		if v, ok := os.LookupEnv("GOMPLATE_RIGHT_DELIM"); ok && v != "" { cfg.RightDelim = v }
	}
	if funcs.ToBoolValue(os.Getenv("GOMPLATE_EXPERIMENTAL")) {
		cfg.Experimental = true
	}
	if cfg.PluginTimeout == 0 {
		if v, present := os.LookupEnv("GOMPLATE_PLUGIN_TIMEOUT"); present && v != "" {
			d, err := time.ParseDuration(v)
			if err != nil {
				return nil, fmt.Errorf("GOMPLATE_PLUGIN_TIMEOUT set to invalid value %q: %w", v, err)
			}
			cfg.PluginTimeout = d
		}
	}
	if cfg.ExecPipe {
		cfg.OutputFiles = []string{"-"}
	}
	// If experimental flag was explicitly set on CLI, flagCfg already has it;
	// merge handled OR. For non-config case flag false explicit also fine.
	return cfg, nil
}
