// Main runs gomplate and returns an exit code.
func Main(ctx context.Context, args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	logState := logging.NewState()
	ctx = logging.WithState(ctx, logState)
	cmd := NewGomplateCmd(ctx, logState)
	cmd.SetArgs(args)
	cmd.SetIn(stdin)
	cmd.SetOut(stdout)
	cmd.SetErr(stderr)
	// Store stdio in ctx for Run/logging? ctx is passed via ExecuteContext
	err := cmd.ExecuteContext(ctx)
	if err != nil {
		if logState.Initialized {
			logState.Logger.Error("", "err", err.Error())
		} else {
			logging.EarlyError(stderr, err)
		}
		return 1
	}
	return 0
}

