	if cfg.LeftDelim == "" {
		if v, ok := os.LookupEnv("GOMPLATE_LEFT_DELIM"); ok && v != "" { cfg.LeftDelim = v }
	}
	if cfg.RightDelim == "" {
		if v, ok := os.LookupEnv("GOMPLATE_RIGHT_DELIM"); ok && v != "" { cfg.RightDelim = v }
	}
	if funcs.ToBoolValue(os.Getenv("GOMPLATE_EXPERIMENTAL")) {
		cfg.Experimental = true
	}
	if cfg.PluginTimeout == 0 {
		if v, present := os.LookupEnv("GOMPLATE_PLUGIN_TIMEOUT"); present && v != "" {
			d, err := time.ParseDuration(v)
			if err != nil {
				return nil, fmt.Errorf("GOMPLATE_PLUGIN_TIMEOUT set to invalid value %q: %w", v, err)
			}
			cfg.PluginTimeout = d
		}
	}
	if cfg.ExecPipe {
		cfg.OutputFiles = []string{"-"}
	}
	// If experimental flag was explicitly set on CLI, flagCfg already has it;
	// merge handled OR. For non-config case flag false explicit also fine.
	return cfg, nil
}
