package gomplate

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"strconv"
	"strings"

	"example.com/gomplate/internal/datafs"
)

type tmplData struct {
	name     string
	contents string
	output   string
	mode     os.FileMode
	noParse  bool // exclude-processing copy
	// raw bytes for noParse
	raw []byte
}

func parseChmod(cfg *Config) (os.FileMode, error) {
	if cfg.Chmod == "" {
		return 0, nil
	}
	v, err := strconv.ParseUint("0"+cfg.Chmod, 8, 32)
	if err != nil { return 0, err }
	return os.FileMode(v), nil
}

func gatherTemplates(ctxIO IO, cfg *Config, r *renderer) ([]tmplData, error) {
	chmod, err := parseChmod(cfg)
	if err != nil { return nil, err }
	chmodApply := func(def os.FileMode) os.FileMode {
		if chmod != 0 { return chmod }
		return def
	}
	if cfg.In != "" || (len(cfg.InputFiles) == 0 && cfg.InputDir == "" && cfg.In == "") {
		// In mode (also covers default where InputFiles may be ["-"] handled below)
		if cfg.In != "" {
			out := "-"
			if len(cfg.OutputFiles) > 0 { out = cfg.OutputFiles[0] }
			return []tmplData{{name: "<arg>", contents: cfg.In, output: out, mode: chmodApply(0o644)}}, nil
		}
	}
	if cfg.InputDir != "" {
		return gatherFromDir(ctxIO, cfg, r, chmodApply)
	}
	// InputFiles
	var out []tmplData
	for i, inFile := range cfg.InputFiles {
		outFile := cfg.OutputFiles[i] // may panic for execPipe multi, matching original
		if inFile == "-" {
			b, err := io.ReadAll(ctxIO.Stdin)
			if err != nil { return nil, err }
			out = append(out, tmplData{name: "-", contents: string(b), output: outFile, mode: chmodApply(0o644)})
			continue
		}
		td, err := fileToTemplate(inFile, outFile, chmodApply)
		if err != nil { return nil, fmt.Errorf("fileToTemplate: %w", err) }
		out = append(out, td)
	}
	return out, nil
}

func fileToTemplate(inFile, outFile string, chmodApply func(os.FileMode) os.FileMode) (tmplData, error) {
	fi, err := datafs.Stat(inFile)
	if err != nil {
		return tmplData{}, fmt.Errorf("stat %q: %w", inFile, err)
	}
	b, err := readAllRoot(inFile)
	if err != nil {
		return tmplData{}, fmt.Errorf("readAll %q: %w", inFile, err)
	}
	return tmplData{name: inFile, contents: string(b), output: outFile, mode: chmodApply(fi.Mode().Perm())}, nil
}

func readAllRoot(name string) ([]byte, error) {
	f, err := datafs.Open(name)
	if err != nil { return nil, err }
	defer f.Close()
	return io.ReadAll(f)
}

// ---- input dir ----

func gatherFromDir(ctxIO IO, cfg *Config, r *renderer, chmodApply func(os.FileMode) os.FileMode) ([]tmplData, error) {
	inputDir := cfg.InputDir
	// stat check with original error format: stat "in" ("tmp/in"): stat : ...
	abs := datafs.CleanAbs(inputDir)
	rootName := datafs.RootName(abs)
	if _, err := os.Stat(abs); err != nil {
		// inner error: stat with empty path (observed)
		inner := &fs.PathError{Op: "stat", Path: "", Err: unwrapPathErr(err)}
		return nil, fmt.Errorf("walkDir: stat %q (%q): %w", inputDir, rootName, inner)
	}
	// load .gomplateignore patterns recursively
	var templates []tmplData
	excludePatterns := cfg.Excludes
	// walk
	err := filepath.Walk(abs, func(cur string, info os.FileInfo, err error) error {
		if err != nil { return err }
		if info.IsDir() {
			// skip .git? Original walks all including .git? Probe later
			// If a .gomplateignore in this dir, its patterns are handled in match function (read on demand)
			return nil
