	// For now only within root.
	ignored := false
	for i, dir := range dirs {
		ignorePath := filepath.Join(dir, ".gomplateignore")
		b, err := os.ReadFile(ignorePath); if err != nil { continue }
		// Path relative to this dir
		relToDir := strings.Join(parts[i:], "/")
		for _, line := range strings.Split(string(b), "\n") {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") { continue }
			neg := false
			if strings.HasPrefix(line, "!") { neg = true; line = line[1:] }
			// gitignore dir pattern ending /
			isDirPat := strings.HasSuffix(line, "/")
			pat := strings.TrimSuffix(line, "/")
			matched := matchPattern(pat, relToDir)
			if !matched && isDirPat {
				// match any parent dir of relToDir
				segs := strings.Split(relToDir, "/")
				for j := 1; j < len(segs); j++ {
					if matchPattern(pat, strings.Join(segs[:j], "/")) { matched = true; break }
				}
			}
			if matched { ignored = !neg }
		}
		_ = full
	}
	return ignored
}

// doublestarMatch implements ** glob
func doublestarMatch(pattern, name string) bool {
	// Use path.Match for non-** patterns segment-wise
	patParts := strings.Split(pattern, "/")
	nameParts := strings.Split(name, "/")
	return matchParts(patParts, nameParts)
}
func matchParts(pat, name []string) bool {
	for len(pat) > 0 {
		if pat[0] == "**" {
			if len(pat) == 1 { return true }
			for i := 0; i <= len(name); i++ {
				if matchParts(pat[1:], name[i:]) { return true }
			}
			return false
		}
		if len(name) == 0 { return false }
		ok, _ := path.Match(pat[0], name[0])
		if !ok { return false }
		pat = pat[1:]; name = name[1:]
	}
	return len(name) == 0
}

// ---- output writer ----

type lazyWriter struct {
	create func() (io.WriteCloser, error)
	w      io.WriteCloser
	writer io.Writer
	buf    bytes.Buffer
	opened bool
}

func newLazyWriter(create func() (io.WriteCloser, error)) *lazyWriter { return &lazyWriter{create: create} }
func newSuppressWriter(w io.Writer) *lazyWriter {
	return &lazyWriter{create: func() (io.WriteCloser, error) { return nopWriteCloser{w}, nil }}
}
type nopWriteCloser struct { io.Writer }
func (nopWriteCloser) Close() error { return nil }

func (lw *lazyWriter) Write(p []byte) (int, error) {
	if lw.opened {
		return lw.writer.Write(p)
	}
	if len(bytes.TrimSpace(p)) == 0 {
		lw.buf.Write(p)
		return len(p), nil
	}
	wc, err := lw.create()
	if err != nil { return 0, err }
	lw.w = wc
	lw.writer = wc
	lw.opened = true
	if lw.buf.Len() > 0 {
		if _, err := lw.writer.Write(lw.buf.Bytes()); err != nil { return 0, err }
		lw.buf.Reset()
	}
	return lw.writer.Write(p)
}
func (lw *lazyWriter) Close() error {
	if lw.opened && lw.w != nil { return lw.w.Close() }
	return nil
}

func createOutFile(outPath string, mode os.FileMode) (io.WriteCloser, error) {
	abs := datafs.CleanAbs(outPath)
	dir := filepath.Dir(abs)
	base := filepath.Base(abs)
	if err := datafs.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("mkdirAll %q: %w", outPath, err)
	}
	f, err := datafs.CreateInDir(dir, base, mode)
	if err != nil { return nil, err }
	return f, nil
}
GO"}

