}
type stdinSource struct {
	data []byte
	read bool
}
type rawResult struct {
	isDir bool
	data []byte
	entries []string
	mime string
	err error
}

func newDSRegistry(cfg *Config, stdin io.Reader) *dsRegistry {
	src := make(map[string]config.DataSource)
	for k,v := range cfg.Datasources { src[k]=v }
	for k,v := range cfg.Context {
		if _, ok := src[k]; !ok { src[k]=v }
	}
	return &dsRegistry{cfg:cfg, sources:src, headers:cfg.ExtraHeaders(), stdin:stdin, stdinFS:make(map[string]*stdinSource), rawCache:make(map[string]*rawResult), gitCache:make(map[string]string)}
}

func (r *dsRegistry) list() []string {
	out := make([]string,0,len(r.sources))
	for k:=range r.sources{out=append(out,k)}
	// sort
	for i:=0;i<len(out);i++{for j:=i+1;j<len(out);j++{if out[j]<out[i]{out[i],out[j]=out[j],out[i]}}}
	return out
}
func (r *dsRegistry) exists(alias string) bool { _,ok:=r.sources[alias]; return ok }

func (r *dsRegistry) define(alias, urlStr string) (string,error) {
	if _, ok := r.sources[alias]; ok { return "", nil }
	u, err := config.ParseURL(urlStr)
	if err != nil { return "", err }
	ds := config.NewDataSource(u, nil)
	if h, ok := r.headers[alias]; ok { ds.Header=h }
	r.sources[alias]=ds
	return "", nil
}

func (r *dsRegistry) lookup(alias string) (config.DataSource,string,error) {
	if ds, ok := r.sources[alias]; ok {
		display := ds.URLString()
		return ds, display, nil
	}
	u, err := url.Parse(alias)
	if err != nil || u.Scheme == "" {
		// match original %!w(<nil>) bug
		if err != nil {
			return config.DataSource{}, "", fmt.Errorf("undefined datasource '%s': %v", alias, err)
		}
		return config.DataSource{}, "", fmt.Errorf("undefined datasource '%s': %%!w(<nil>)", alias)
	}
	ds := config.NewDataSource(u, nil)
	if h, ok := r.headers[alias]; ok { ds.Header=h }
	return ds, alias, nil
}

// joinURL joins subpath args to source URL.
func joinURL(base *url.URL, args []string) *url.URL {
	if len(args)==0 { return base }
	sub := strings.Join(args, "/") // original datasource function signature args is slice but typically one; joining multiple?
	// Actually datasource func passes args ... and original code likely uses only first? Check later.
	// If base is opaque, subpath is ignored (observed for env:HOME, merge:, file:)
	if base.Opaque != "" {
		return base
	}
	ref, err := url.Parse(sub)
	if err != nil {
		// treat as path
		ref = &url.URL{Path: sub}
	}
	if base.Scheme == "" {
		// relative file URL: filesystem path resolution
		basePath := base.Path
		if strings.HasPrefix(sub, "/") {
			// wdFS absolute name -> path with leading / for display, reading will trim
			return &url.URL{Path: sub, RawQuery: ref.RawQuery, Fragment: ref.Fragment, ForceQuery: ref.ForceQuery}
		}
		var dir string
		if strings.HasSuffix(basePath, "/") {
			dir = basePath
		} else if basePath == "." || basePath == ".." {
			dir = basePath + "/"
		} else {
			d := path.Dir(basePath)
			if d == "." { dir = "" } else { dir = d + "/" }
		}
		joinedPath := dir + ref.Path
		// Display for dir="" should be "/"+joined (original): keep as "/"+joined if dir empty
		// But reading relative file with leading / in scheme-empty url is treated by split as wd name trimmed.
		// Preserve a marker: return Path as joined with leading / when dir empty.
		p := joinedPath
		if dir == "" { p = "/" + p }
		// For dir "./" p is "./sub" fine. For "../" fine.
		return &url.URL{Path: p, RawQuery: ref.RawQuery, Fragment: ref.Fragment, ForceQuery: ref.ForceQuery}
	}
	return base.ResolveReference(ref)
}

func (r *dsRegistry) readParsed(ctx context.Context, alias string, args ...string) (interface{}, error) {
	ds, displayAlias, err := r.lookup(alias)
	if err != nil { return nil, err }
	// Merge datasources handled at parsed level
	finalURL := joinURL(ds.URL, args)
	if finalURL.Scheme == "merge" {
		return r.readMerge(ctx, alias, ds, finalURL)
	}
	raw, err := r.readRaw(ctx, alias, ds, finalURL)
	if err != nil {
		// raw errors are wrapped here as couldn't read
		return nil, fmt.Errorf("couldn't read datasource '%s' (%s): %w", displayForError(alias, ds, finalURL, args), displayURLForError(ds, finalURL, args), err)
	}
	_ = displayAlias
	if raw.isDir {
		out := make([]interface{}, len(raw.entries))
		for i,e:=range raw.entries{out[i]=e}
		if len(out)==0 { /* directory listing type? test %#v later */ }
		return out, nil
	}
	return parseDataBytes(raw.data, raw.mime)
}

func displayForError(alias string, ds config.DataSource, final *url.URL, args []string) string {
	return alias
}
func displayURLForError(ds config.DataSource, final *url.URL, args []string) string {
	if len(args)==0 {
		return ds.URLString()
	}
	return final.String()
}

func (r *dsRegistry) readInclude(ctx context.Context, alias string, args ...string) (string,error) {
	ds, _, err := r.lookup(alias)
	if err != nil { return "", err }
	finalURL := joinURL(ds.URL, args)
	if finalURL.Scheme == "merge" {
		v, err := r.readMerge(ctx, alias, ds, finalURL)
		if err != nil { return "", err }
		// include merge result as JSON? Original merge FS returns bytes of merged JSON maybe
		b, _ := json.Marshal(v)
		return string(b), nil
	}
	raw, err := r.readRaw(ctx, alias, ds, finalURL)
	if err != nil {
		return "", fmt.Errorf("couldn't read datasource '%s' (%s): %w", alias, displayURLForError(ds, finalURL, args), err)
	}
