		if strings.HasSuffix(basePath, "/") {
			dir = basePath
		} else if basePath == "." || basePath == ".." {
			dir = basePath + "/"
		} else {
			d := path.Dir(basePath)
			if d == "." { dir = "" } else { dir = d + "/" }
		}
		joinedPath := dir + ref.Path
		// Display for dir="" should be "/"+joined (original): keep as "/"+joined if dir empty
		// But reading relative file with leading / in scheme-empty url is treated by split as wd name trimmed.
		// Preserve a marker: return Path as joined with leading / when dir empty.
		p := joinedPath
		if dir == "" { p = "/" + p }
		// For dir "./" p is "./sub" fine. For "../" fine.
		return &url.URL{Path: p, RawQuery: ref.RawQuery, Fragment: ref.Fragment, ForceQuery: ref.ForceQuery}
	}
	return base.ResolveReference(ref)
}

func (r *dsRegistry) readParsed(ctx context.Context, alias string, args ...string) (interface{}, error) {
	ds, displayAlias, err := r.lookup(alias)
	if err != nil { return nil, err }
	// Merge datasources handled at parsed level
	finalURL := joinURL(ds.URL, args)
	if finalURL.Scheme == "merge" {
		return r.readMerge(ctx, alias, ds, finalURL)
	}
	raw, err := r.readRaw(ctx, alias, ds, finalURL)
	if err != nil {
		// raw errors are wrapped here as couldn't read
		return nil, fmt.Errorf("couldn't read datasource '%s' (%s): %w", displayForError(alias, ds, finalURL, args), displayURLForError(ds, finalURL, args), err)
	}
	_ = displayAlias
	if raw.isDir {
		out := make([]interface{}, len(raw.entries))
		for i,e:=range raw.entries{out[i]=e}
		if len(out)==0 { /* directory listing type? test %#v later */ }
		return out, nil
	}
	return parseDataBytes(raw.data, raw.mime)
}

func displayForError(alias string, ds config.DataSource, final *url.URL, args []string) string {
	return alias
}
func displayURLForError(ds config.DataSource, final *url.URL, args []string) string {
	if len(args)==0 {
		return ds.URLString()
	}
	return final.String()
}

func (r *dsRegistry) readInclude(ctx context.Context, alias string, args ...string) (string,error) {
	ds, _, err := r.lookup(alias)
	if err != nil { return "", err }
	finalURL := joinURL(ds.URL, args)
	if finalURL.Scheme == "merge" {
		v, err := r.readMerge(ctx, alias, ds, finalURL)
		if err != nil { return "", err }
		// include merge result as JSON? Original merge FS returns bytes of merged JSON maybe
		b, _ := json.Marshal(v)
		return string(b), nil
	}
	raw, err := r.readRaw(ctx, alias, ds, finalURL)
	if err != nil {
		return "", fmt.Errorf("couldn't read datasource '%s' (%s): %w", alias, displayURLForError(ds, finalURL, args), err)
	}
	if raw.isDir {
		// include of a directory: original likely errors reading dir. The raw reading
		// would have open/read a directory - for local, readRaw detects dir and lists.
		// For include, return ??? test later
		return strings.Join(raw.entries, "\n"), nil
	}
	return string(raw.data), nil
}

func (r *dsRegistry) reachable(ctx context.Context, alias string) bool {
	ds, _, err := r.lookup(alias)
	if err != nil { return false }
	// Stat-only would be more efficient; use readRaw but stdin cache etc could consume?
	// DatasourceReachable in original does try to read/stat and may consume stdin - acceptable.
	_, err = r.readRaw(ctx, alias, ds, ds.URL)
	return err == nil
}

// split FS for final URL
type fsSplit struct {
	fsURL string
	name string
	scheme string
	isRelative bool
	gitRepo string // for git schemes repo URL string
	gitRef string
}

func splitFinalURL(u *url.URL) fsSplit {
	if strings.HasPrefix(u.Scheme, "git") {
		// handle below in caller
	}
	if u.Scheme == "" {
		name := u.Path
		if name == "" { name = "." }
		return fsSplit{fsURL: "/", name: name, scheme: "", isRelative: true}
	}
	if u.Opaque != "" {
		name := u.Opaque
		if u.Scheme == "file" {
			name = "/" + name
			return fsSplit{fsURL: u.Scheme + ":///", name: name, scheme: u.Scheme}
		}
		return fsSplit{fsURL: u.Scheme + ":///", name: name, scheme: u.Scheme}
	}
	clone := *u
	clone.Path = "/"; clone.RawPath=""; clone.RawQuery=""; clone.Fragment=""; clone.RawFragment=""; clone.ForceQuery=false
	fsURL := clone.String()
	name := strings.TrimPrefix(u.Path, "/")
	if u.Scheme == "file" {
		name = u.Path
		if name == "" { name = "/" }
	}
	if name == "" { name = "." }
	return fsSplit{fsURL: fsURL, name: name, scheme: u.Scheme}
}

func fsErr(op string, sp fsSplit, err error) error {
	if err == nil { return nil }
	return fmt.Errorf("%s (url: %q, name: %q): %w", op, sp.fsURL, sp.name, err)
}

func (r *dsRegistry) readRaw(ctx context.Context, alias string, ds config.DataSource, finalURL *url.URL) (*rawResult, error) {
	cacheKey := alias + "\x00" + finalURL.String()
	if cached, ok := r.rawCache[cacheKey]; ok {
		if cached.err != nil { return nil, cached.err }
		return cached, nil
	}
	res, err := r.readRawUncached(ctx, alias, ds, finalURL)
	// Cache successes and stdin? Cache all to preserve stdin consumption per alias/url
	if err != nil {
		// Don't cache other errors? Stdin empty returns success so fine.
		return nil, err
	}
	r.rawCache[cacheKey] = res
	return res, nil
}

func (r *dsRegistry) readRawUncached(ctx context.Context, alias string, ds config.DataSource, finalURL *url.URL) (*rawResult, error) {
	scheme := finalURL.Scheme
	// git schemes
	if strings.HasPrefix(scheme, "git") {
		return r.readGit(ctx, alias, ds, finalURL)
	}
	sp := splitFinalURL(finalURL)
	switch scheme {
	case "", "file":
		return r.readLocal(sp, finalURL)
	case "env":
		return r.readEnv(sp)
	case "stdin":
		return r.readStdin(alias, sp, finalURL)
	case "http", "https":
		return r.readHTTP(ctx, ds, sp, finalURL)
	case "consul", "consul+http", "consul+https":
		return r.readConsul(ctx, ds, sp, finalURL)
	case "vault", "vault+http", "vault+https":
		return r.readVault(ctx, ds, sp, finalURL)
	case "gcp+meta":
		return r.readGCPMeta(ctx, sp, finalURL)
	case "s3":
		return r.readS3(ctx, ds, sp, finalURL)
	case "gs":
		return nil, fsErr("open", sp, errors.New("open: bucket opener: failed to retrieve GCP credentials: google: could not find default credentials. See https://cloud.google.com/docs/authentication/external/set-up-adc for more information"))
	case "aws+sm":
		return r.readAWS(ctx, "sm", ds, sp, finalURL)
	case "aws+smp":
		return r.readAWS(ctx, "smp", ds, sp, finalURL)
	case "merge":
		// handled in readParsed before raw; include path goes via marshalled JSON
		return nil, fsErr("open", sp, fmt.Errorf("open %s: need at least 2 datasources to merge", sp.name))
	default:
		return nil, fmt.Errorf("fsys for path %s: filesystem provider for %q unavailable: no filesystem registered for scheme %q", sp.fsURL, sp.fsURL, scheme)
	}
}

func mimeForURL(u *url.URL, nameForExt string, contentType string) string {
	typeParam := os.Getenv("GOMPLATE_TYPE_PARAM")
	if typeParam == "" { typeParam = "type" }
	if q := u.Query().Get(typeParam); q != "" {
		return q
	}
	ext := strings.ToLower(path.Ext(nameForExt))
	switch ext {
	case ".json": return "application/json"
	case ".yaml", ".yml": return "application/yaml"
	case ".toml": return "application/toml"
	case ".csv": return "text/csv"
	case ".env": return "application/x-env"
	case ".cue": return "application/cue"
	case ".txt": return "text/plain; charset=utf-8"
	}
	if contentType != "" { return contentType }
	if ext != "" {
		if mt := mimeByExtension(ext); mt != "" { return mt }
	}
	return "text/plain; charset=utf-8"
}
func mimeByExtension(ext string) string {
	// Use Go mime where available
	return mimeTypeByExtension(ext)
}

func (r *dsRegistry) readLocal(sp fsSplit, finalURL *url.URL) (*rawResult, error) {
	name := sp.name
	// For relative: name may be ./x, ../x, /x (meaning wd-relative x due subpath join), x
	// For file: name is absolute /path
	var b []byte
	var fi os.FileInfo
	var err error
	if sp.scheme == "file" {
		// Stat via Open fallback: errors op open
		b, err = datafs.ReadFile(name)
		if err != nil {
			// Determine if it is a directory: ReadFile on dir returns read error, but original
			// stats first via open and checks IsDir. Our datafs.Open can stat file
			if st, serr := datafs.Stat(name); serr == nil && st.IsDir() {
				ents, derr := datafs.ReadDir(name); if derr != nil { return nil, fsErr("open", sp, derr) }
				names := make([]string,len(ents)); for i,e:=range ents{names[i]=e.Name()}
				return &rawResult{isDir:true, entries:names}, nil
			}
			return nil, fsErr("open", sp, err)
		}
		fi, _ = datafs.Stat(name)
		if fi != nil && fi.IsDir() {
			// unreachable: ReadFile dir would error - handled above
		}
		return &rawResult{data:b, mime:mimeForURL(finalURL, name, "")}, nil
	}
	// relative wdFS: resolve name relative to cwd. A leading "/" in name from join
	// should be stripped to be wd-relative (observed for subpath absolute)
	// But name could be "/tmp/..." if source was absolute without scheme it would have been
	// converted to file:// in ParseURL, so not here.
	wdName := name
	// open via datafs which resolves relative to cwd and rewrites errors to root-relative (tmp/dstest/...)
	// datafs.ReadFile with wdName starting "/" would treat as fs root, wrong for subpath absolute.
	// Our joinURL produced "/nope" for wd-relative; strip single leading slash when name came from join?
	// Heuristic: if wdName starts "/" and original scheme empty, treat as relative to cwd by trimming leading /
	// Except finalURL was from a no-subpath request where name does not start with / (relative).
	readPath := wdName
	if strings.HasPrefix(readPath, "/") {
		readPath = strings.TrimPrefix(readPath, "/")
		if readPath == "" { readPath = "." }
	}
	// First check dir via Stat on readPath (datafs Stat errors rewrite root-relative)
	if st, serr := datafs.Stat(readPath); serr == nil && st.IsDir() {
		ents, derr := datafs.ReadDir(readPath); if derr != nil { return nil, fsErr("open", sp, derr) }
		names := make([]string,len(ents)); for i,e:=range ents{names[i]=e.Name()}
		return &rawResult{isDir:true, entries:names}, nil
	}
	b, err = datafs.ReadFile(readPath)
	if err != nil { return nil, fsErr("open", sp, err) }
	return &rawResult{data:b, mime:mimeForURL(finalURL, readPath, "")}, nil
}

func (r *dsRegistry) readEnv(sp fsSplit) (*rawResult, error) {
	// Stat op
	v, ok := os.LookupEnv(sp.name)
	if !ok || sp.name == "." {
		return nil, fsErr("stat", sp, fs.ErrNotExist)
	}
	// mime from type query handled by caller finalURL not passed here: use plaintext default,
	// but env datasource with ?type=application/json needs mime overridden.
	// readRaw caller must set mime after. We'll return plain and let readParsed override? Simpler:
	// This function is called with sp only; mime determination in readParsed after raw would need finalURL.
	// We'll set mime in readRawUncached wrapper? Instead pass final via splitting query encoded in sp? Not available.
	return &rawResult{data: []byte(v), mime: "text/plain; charset=utf-8"}, nil
}

func (r *dsRegistry) readStdin(alias string, sp fsSplit, finalURL *url.URL) (*rawResult, error) {
	src, ok := r.stdinFS[alias]
	if !ok { src = &stdinSource{}; r.stdinFS[alias]=src }
	if !src.read {
		b, err := io.ReadAll(r.stdin)
		if err != nil { return nil, fsErr("open", sp, err) }
		src.data = b; src.read = true
	}
	return &rawResult{data: src.data, mime: mimeForURL(finalURL, finalURL.Path, "")}, nil
}

func applyTypeOverrideMime(res *rawResult, finalURL *url.URL, name string) {
	// If type query present, override regardless provider's mime
	typeParam := os.Getenv("GOMPLATE_TYPE_PARAM"); if typeParam==""{typeParam="type"}
	if q := finalURL.Query().Get(typeParam); q != "" { res.mime = q; return }
	// If provider returned plain due env but extension in name indicates type, re-evaluate when name has ext?
	// For env:///FOO?type=... covered above. For env var values with name foo.json (?) env var name could contain dot - original uses name ext? Not usually.
	_ = name
}

func parseDataBytes(b []byte, mimeStr string) (interface{}, error) {
	origMime := mimeStr
	mt, _, err := mime.ParseMediaType(mimeStr)
	if err == nil { mimeStr = mt }
	s := string(b)
	switch mimeStr {
	case "application/json":
		// Try object, then array
		if v, err := funcs.ParseJSON(s); err == nil { return v, nil } else {
			v2, err2 := funcs.ParseJSONArray(s)
			if err2 != nil { return nil, err2 }
			return v2, nil
		}
	case "application/array+json":
		return funcs.ParseJSONArray(s)
	case "application/yaml", "application/x-yaml", "text/yaml":
		if v, err := funcs.ParseYAML(s); err == nil { return v, nil } else {
			v2, err2 := funcs.ParseYAMLArray(s)
			if err2 != nil { return nil, err2 }
			return v2, nil
		}
	case "application/array+yaml", "application/x-array+yaml":
		return funcs.ParseYAMLArray(s)
	case "application/toml", "application/x-toml", "text/toml":
		return funcs.ParseTOML(s)
	case "text/csv":
		return funcs.ParseCSVRecords(s)
	case "application/x-env":
		return parseDotEnv(s)
	case "application/cue", "text/cue":
		// use funcs CUE via DataFuncs
		df := &funcs.DataFuncsExported{}
		_ = df
		return parseCUEViaFuncs(s)
	case "text/plain":
		return s, nil
	default:
		return nil, fmt.Errorf("data of type %q not yet supported", origMime)
	}
}

var _ = bytes.Contains
var _ = xml.Decoder{}
var _ = base64.StdEncoding
var _ = time.Now
GO"}

{"command":"cat > datasource_providers.go <<'GO'
package gomplate

import (
	"context"
	"crypto/tls"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"net/http"
	"net/url"
	"os"
	"path"
	"strconv"
	"strings"
	"time"

	"example.com/gomplate/internal/config"
)

// HTTP
func (r *dsRegistry) readHTTP(ctx context.Context, ds config.DataSource, sp fsSplit, finalURL *url.URL) (*rawResult, error) {
	// Stat via HEAD first, error op stat
	client := &http.Client{}
	// Build request URL: Use finalURL directly (it is fully resolved)
	reqURL := finalURL.String()
	headReq, _ := http.NewRequestWithContext(ctx, "HEAD", reqURL, nil)
	for k, vs := range ds.Header { for _, v := range vs { headReq.Header.Add(k, v) } }
	resp, err := client.Do(headReq)
	if err != nil {
		return nil, fsErr("stat", sp, err)
	}
	io.Copy(io.Discard, resp.Body); resp.Body.Close()
	contentType := resp.Header.Get("Content-Type")
	if resp.StatusCode == http.StatusNotFound {
		return nil, fsErr("stat", sp, fs.ErrNotExist)
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 400 {
		// Original http FS Stat may succeed for some status? read will surface.
	}
	// Directory? HTTP dirs are not generally listable; if path ends with / and ... treat as file (GET)
	getReq, _ := http.NewRequestWithContext(ctx, "GET", reqURL, nil)
	for k, vs := range ds.Header { for _, v := range vs { getReq.Header.Add(k, v) } }
	gresp, err := client.Do(getReq)
	if err != nil { return nil, fsErr("open", sp, err) }
	defer gresp.Body.Close()
	if gresp.StatusCode < 200 || gresp.StatusCode >= 300 {
		// go-fsimpl http FS Open returns error with status? Probe later. Return an error mimicking fs PathError
		body, _ := io.ReadAll(gresp.Body)
		_ = body
		return nil, fsErr("open", sp, fmt.Errorf("http status %s", gresp.Status))
	}
	b, err := io.ReadAll(gresp.Body)
	if err != nil { return nil, fsErr("open", sp, err) }
	if ct := gresp.Header.Get("Content-Type"); ct != "" { contentType = ct }
	mime := mimeForURL(finalURL, finalURL.Path, contentType)
	// mimeForURL prefers extension over contentType currently for known extensions, and contentType for unknown.
	// For extensionless URLs with JSON content type, contentType is passed.
	return &rawResult{data: b, mime: mime}, nil
}

// Consul
func consulBase(finalURL *url.URL) (scheme string, addr string) {
	scheme = "http"
	if strings.HasSuffix(finalURL.Scheme, "+https") { scheme = "https" }
	if v := os.Getenv("CONSUL_HTTP_SSL"); v != "" {
		if b, err := strconv.ParseBool(v); err == nil {
			if b { scheme = "https" } else { scheme = "http" }
		}
	}
	addr = finalURL.Host
	if addr == "" {
		addr = os.Getenv("CONSUL_HTTP_ADDR")
		if addr == "" { addr = "localhost:8500" } else {
			// CONSUL_HTTP_ADDR may include scheme
			if strings.HasPrefix(addr, "http://") || strings.HasPrefix(addr, "https://") {
				if u, err := url.Parse(addr); err == nil { scheme = u.Scheme; addr = u.Host }
			}
		}
	}
	return scheme, addr
}
func consulClient() *http.Client {
	toSec := 10
	if v := os.Getenv("CONSUL_TIMEOUT"); v != "" { if iv, err := strconv.Atoi(v); err == nil { toSec = iv } }
	tr := &http.Transport{TLSClientConfig: &tls.Config{InsecureSkipVerify: os.Getenv("CONSUL_HTTP_SSL_VERIFY") == "false"}}
	return &http.Client{Timeout: time.Duration(toSec) * time.Second, Transport: tr}
}
func consulRequest(ctx context.Context, method, urlStr string) ([]byte, int, error) {
	req, _ := http.NewRequestWithContext(ctx, method, urlStr, nil)
	if tok := os.Getenv("CONSUL_HTTP_TOKEN"); tok != "" { req.Header.Set("X-Consul-Token", tok) }
	if auth := os.Getenv("CONSUL_HTTP_AUTH"); auth != "" {
		if u, p, ok := strings.Cut(auth, ":"); ok { req.SetBasicAuth(u, p) }
	}
	resp, err := consulClient().Do(req)
	if err != nil { return nil, 0, err }
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	return b, resp.StatusCode, nil
}
func (r *dsRegistry) readConsul(ctx context.Context, ds config.DataSource, sp fsSplit, finalURL *url.URL) (*rawResult, error) {
	scheme, addr := consulBase(finalURL)
	name := sp.name
	isDir := strings.HasSuffix(finalURL.Path, "/") || name == "."
	base := scheme + "://" + addr + "/v1/kv/"
	// Stat phase: kv.Get
	getURL := base + name
	if isDir {
		listURL := base + strings.TrimSuffix(name, "/")
		if name != "." { listURL += "/" } // Ensure prefix
		listURL += "?keys&separator=/"
		 b, code, err := consulRequest(ctx, "GET", listURL)
		if err != nil { return nil, fsErr("stat", sp, fmt.Errorf("stat %s: kv.Get: %w", name, err)) }
		if code == 404 { return nil, fsErr("stat", sp, fmt.Errorf("stat %s: %w", name, fs.ErrNotExist)) }
		var keys []string
		if err := json.Unmarshal(b, &keys); err != nil { return nil, fsErr("stat", sp, err) }
		// Entries are relative to prefix and immediate segments; consul returns full keys with separator logic.
		prefix := strings.TrimSuffix(name, "/")
		if prefix == "." { prefix = "" }
		var entries []string
		seen := map[string]bool{}
		for _, k := range keys {
			rel := strings.TrimPrefix(k, prefix)
			rel = strings.TrimPrefix(rel, "/")
			first := strings.Split(rel, "/")[0]
			if first != "" && !seen[first] { seen[first]=true; entries=append(entries, first) }
		}
		return &rawResult{isDir:true, entries:entries}, nil
	}
	b, code, err := consulRequest(ctx, "GET", getURL)
	if err != nil { return nil, fsErr("stat", sp, fmt.Errorf("stat %s: kv.Get: %w", name, err)) }
	if code == 404 {
		return nil, fsErr("stat", sp, fmt.Errorf("stat %s: %w", name, fs.ErrNotExist))
	}
	var arr []struct{ Value *string `json:"Value"` }
	if err := json.Unmarshal(b, &arr); err != nil { return nil, fsErr("open", sp, err) }
	if len(arr) == 0 || arr[0].Value == nil { return nil, fsErr("stat", sp, fmt.Errorf("stat %s: %w", name, fs.ErrNotExist)) }
	dec, err := base64.StdEncoding.DecodeString(*arr[0].Value)
	if err != nil { dec = []byte(*arr[0].Value) }
	return &rawResult{data: dec, mime: mimeForURL(finalURL, name, "text/plain; charset=utf-8")}, nil
}

// GCP meta
func (r *dsRegistry) readGCPMeta(ctx context.Context, sp fsSplit, finalURL *url.URL) (*rawResult, error) {
	endpoint := os.Getenv("GCP_META_ENDPOINT")
	if endpoint == "" { endpoint = "http://169.254.169.254" }
	endpoint = strings.TrimSuffix(endpoint, "/")
	name := sp.name
	urlStr := endpoint + "/computeMetadata/v1/" + strings.TrimPrefix(name, "/")
	get := func() ([]byte, error) {
		req, _ := http.NewRequestWithContext(ctx, "GET", urlStr, nil)
		req.Header.Set("Metadata-Flavor", "Google")
		resp, err := http.DefaultClient.Do(req)
		if err != nil { return nil, err }
		defer resp.Body.Close()
		if resp.StatusCode != 200 { io.Copy(io.Discard, resp.Body); return nil, fs.ErrNotExist }
		return io.ReadAll(resp.Body)
	}
	b, err := get()
	if err != nil {
		base := path.Base(name)
		return nil, fsErr("stat", sp, fmt.Errorf("stat %s: %w", base, err))
	}
	if strings.HasSuffix(finalURL.Path, "/") || name == "." {
		// Directory listing is newline-delimited (with ?alt=text default maybe)
		trimmed := strings.TrimSpace(string(b))
		if trimmed == "" { return &rawResult{isDir:true, entries: []string{}}, nil }
		lines := strings.Split(trimmed, "\n")
		for i:=range lines{lines[i]=strings.TrimSuffix(strings.TrimSpace(lines[i]),"/")}
		return &rawResult{isDir:true, entries:lines}, nil
	}
	return &rawResult{data:b, mime:"text/plain; charset=utf-8"}, nil
}

var _ = errors.Is
GO"}

