package gomplate

import (
	"context"
	"fmt"
	"net/url"
	"strings"

	"example.com/gomplate/internal/config"
)

func (r *dsRegistry) readMerge(ctx context.Context, alias string, ds config.DataSource, finalURL *url.URL) (interface{}, error) {
	sp := splitFinalURL(finalURL)
	// Name is parts string in opaque/path. For finalURL String display:
	// merge:foo|bar opaque name foo|bar; merge:///foo|bar?
	partsStr := sp.name
	if finalURL.Opaque != "" { partsStr = finalURL.Opaque }
	// For hierarchical merge:///... name trimmed
	parts := strings.Split(partsStr, "|")
	outerErr := func(err error) error {
		return fmt.Errorf("couldn't read datasource '%s' (%s): %w", alias, ds.URLString(), err)
	}
	if len(parts) < 2 {
		return nil, outerErr(fsErr("open", sp, fmt.Errorf("open %s: need at least 2 datasources to merge", partsStr)))
	}
	// Resolve each part to parsed data
	parsed := make([]map[string]interface{}, len(parts))
	for i, part := range parts {
		var v interface{}
		var err error
		if _, ok := r.sources[part]; ok && part != alias {
			v, err = r.readParsedNoMerge(ctx, part)
		} else {
			// Treat as URL/file - create dynamic source display alias as part
			u, perr := config.ParseURL(part)
			if perr != nil { return nil, outerErr(fsErr("open", sp, fmt.Errorf("open %s: %w", partsStr, perr))) }
			src := config.NewDataSource(u, nil)
			raw, rerr := r.readRaw(ctx, part, src, u)
			if rerr != nil {
				// error formats inside merge FS differ: for file part, inner is raw open error without wrapper
				// readRaw errors already fs-wrapped; need unwrap one layer? Our readRaw returns fsErr - original showed
				// `open foo|bar: opening merge part "foo": open tmp/...` for some cases.
				// Simplify to that for file-like parts:
				return nil, outerErr(fsErr("open", sp, fmt.Errorf("opening merge part %q: %v", part, stripFsWrap(rerr))))
			}
			if raw.isDir { return nil, outerErr(fsErr("open", sp, fmt.Errorf("opening merge part %q: is a directory", part))) }
			v, err = parseDataBytes(raw.data, raw.mime)
			if err != nil { return nil, outerErr(fsErr("open", sp, fmt.Errorf("opening merge part %q: %w", part, err))) }
		}
		if err != nil { return nil, err } // readParsed already wraps with couldn't read for that alias, but in merge context original may nest...keep
		m, ok := v.(map[string]interface{})
		if !ok {
			return nil, outerErr(fsErr("open", sp, fmt.Errorf("opening merge part %q: data is not a map", part)))
		}
		parsed[i] = m
	}
	// Merge right-to-left: leftmost wins
	result := parsed[len(parsed)-1]
	for i := len(parsed)-2; i>=0; i-- {
		result = mergeMaps(parsed[i], result)
	}
	return result, nil
}

func stripFsWrap(err error) error {
	// fsErr format: open (url: "..", name: ".."): <inner>
	// errors.Unwrap will give inner if wrapped with %w
	if u := unwrap(err); u != nil { return u }
	return err
}
func unwrap(err error) error {
	type unwrapper interface{ Unwrap() error }
	if u, ok := err.(unwrapper); ok { return u.Unwrap() }
	return nil
}

func (r *dsRegistry) readParsedNoMerge(ctx context.Context, alias string) (interface{}, error) {
	// same as readParsed but aliases are defined sources
	return r.readParsed(ctx, alias)
}

func mergeMaps(dst, src map[string]interface{}) map[string]interface{} {
	out := deepCopyMapRoot(dst)
	mergeIntoRoot(out, src)
	return out
}
func deepCopyMapRoot(m map[string]interface{}) map[string]interface{} {
	out := make(map[string]interface{}, len(m))
	for k,v:=range m { if vm,ok:=v.(map[string]interface{}); ok {out[k]=deepCopyMapRoot(vm)} else {out[k]=v} }
	return out
}
func mergeIntoRoot(dst, src map[string]interface{}) {
	for k,sv:=range src {
		if dv,ok:=dst[k]; ok {
			dm,dok:=dv.(map[string]interface{}); sm,sok:=sv.(map[string]interface{})
			if dok && sok { mergeIntoRoot(dm, sm) }
			continue
		}
		if sm,ok:=sv.(map[string]interface{}); ok {dst[k]=deepCopyMapRoot(sm)} else {dst[k]=sv}
	}
}
GO
