package gomplate

import (
	"os"
	"strconv"
	"strings"
)

func parseDotEnv(s string) (interface{}, error) {
	out := make(map[string]interface{})
	// Use a scanner handling quoted multiline values roughly like godotenv
	lines := strings.Split(s, "\n")
	for i:=0;i<len(lines);i++ {
		line := strings.TrimSpace(lines[i])
		if line=="" || strings.HasPrefix(line,"#") { continue }
		line = strings.TrimPrefix(line, "export ")
		line = strings.TrimSpace(line)
		k,v,found := strings.Cut(line,"=")
		if !found { continue }
		key := strings.TrimSpace(k)
		val := strings.TrimSpace(v)
		// quoted
		if len(val)>=1 && (val[0]=='\'' || val[0]=='"') {
			quote := val[0]
			// accumulate until closing quote found
			for (len(val)<2 || val[len(val)-1]!=quote) && i+1 < len(lines) {
				i++; val += "\n" + lines[i]
			}
			inner := ""
			if len(val)>=2 { inner = val[1:len(val)-1] }
			if quote=='"' {
				if unq, err := strconv.Unquote("\""+strings.ReplaceAll(inner,"`","`")+"\""); err==nil {
					// strconv handles \n etc but $ etc kept
					inner = unq
				} else {
					inner = strings.NewReplacer(`\n`,"\n",`\r`,"\r",`\t`,"\t").Replace(inner)
				}
				inner = expandEnvVars(inner, out)
			}
			out[key]=inner
			continue
		}
		// unquoted: strip inline comments preceded by whitespace/#
		if idx := strings.Index(val, " #"); idx>=0 { val = strings.TrimSpace(val[:idx]) }
		val = expandEnvVars(val, out)
		out[key]=val
	}
	return out, nil
}
func expandEnvVars(s string, local map[string]interface{}) string {
	return os.Expand(s, func(k string) string {
		if v,ok:=local[k]; ok { if vs,ok:=v.(string); ok {return vs} }
		return os.Getenv(k)
	})
}
GO"}

