cat > datasource_vault.go <<'GO'
package gomplate

import (
	"bytes"
	"context"
	"crypto/tls"
	"encoding/json"
	"fmt"
	"io"
	"io/fs"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"time"

	"example.com/gomplate/internal/config"
)

func envOrFile(name string) string {
	if v := os.Getenv(name); v != "" { return v }
	if f := os.Getenv(name+"_FILE"); f != "" {
		if b, err := os.ReadFile(f); err == nil { return strings.TrimSpace(string(b)) }
	}
	return ""
}

type vaultClient struct {
	addr string
	token string
	http *http.Client
}
func vaultAddr(finalURL *url.URL) string {
	scheme := "https"
	if finalURL.Scheme == "vault+http" { scheme = "http" }
	if finalURL.Host != "" {
		return scheme + "://" + finalURL.Host
	}
	if v := os.Getenv("VAULT_ADDR"); v != "" { return strings.TrimSuffix(v,"/") }
	return "https://localhost:8200"
}
func newVaultClient(finalURL *url.URL) *vaultClient {
	tr := &http.Transport{TLSClientConfig: &tls.Config{InsecureSkipVerify: os.Getenv("VAULT_SKIP_VERIFY")=="true"}}
	return &vaultClient{addr: vaultAddr(finalURL), http: &http.Client{Timeout: 60*time.Second, Transport: tr}}
}
func (vc *vaultClient) request(ctx context.Context, method, apipath string, body interface{}) ([]byte,int,error) {
	var rdr io.Reader
	if body != nil { b,_:=json.Marshal(body); rdr=bytes.NewReader(b) }
	req,_:=http.NewRequestWithContext(ctx,method,vc.addr+"/v1/"+strings.TrimPrefix(apipath,"/"),rdr)
	if vc.token!=""{req.Header.Set("X-Vault-Token",vc.token)}
	resp,err:=vc.http.Do(req); if err!=nil{return nil,0,err}
	defer resp.Body.Close(); b,_:=io.ReadAll(resp.Body); return b,resp.StatusCode,nil
}
func (vc *vaultClient) login(ctx context.Context) error {
	// approle
	roleID:=envOrFile("VAULT_ROLE_ID"); secretID:=envOrFile("VAULT_SECRET_ID")
	mountOr := func(envname, def string) string { if v:=os.Getenv(envname); v!=""{return v}; return def }
	doLogin := func(path string, body map[string]interface{}) error {
		b,code,err:=vc.request(ctx,"POST",path,body); if err!=nil{return err}
		if code<200||code>=300{ return fmt.Errorf("vault login failed with status %d: %s",code,string(b)) }
		var out struct{ Auth *struct{ClientToken string `json:"client_token"`} `json:"auth"` }
		if err:=json.Unmarshal(b,&out); err!=nil{return err}
		if out.Auth==nil||out.Auth.ClientToken==""{return fmt.Errorf("no token in login response")}
		vc.token=out.Auth.ClientToken; return nil
	}
	if roleID!="" && secretID!="" {
		return doLogin("auth/"+mountOr("VAULT_AUTH_APPROLE_MOUNT","approle")+"/login", map[string]interface{}{"role_id":roleID,"secret_id":secretID})
	}
	if tok:=envOrFile("VAULT_AUTH_GITHUB_TOKEN"); tok!="" {
		return doLogin("auth/"+mountOr("VAULT_AUTH_GITHUB_MOUNT","github")+"/login", map[string]interface{}{"token":tok})
	}
	if user:=envOrFile("VAULT_AUTH_USERNAME"); user!="" {
		pw:=envOrFile("VAULT_AUTH_PASSWORD")
		return doLogin("auth/"+mountOr("VAULT_AUTH_USERPASS_MOUNT","userpass")+"/login/"+user, map[string]interface{}{"password":pw})
	}
	if tok:=envOrFile("VAULT_TOKEN"); tok!=""{ vc.token=tok; return nil }
	if b,err:=os.ReadFile(filepath.Join(os.Getenv("HOME"),".vault-token")); err==nil { vc.token=strings.TrimSpace(string(b)); return nil }
	// AWS auth attempts in original produce a noisy last error when no credentials.
	if os.Getenv("AWS_ACCESS_KEY_ID")!="" || os.Getenv("VAULT_AUTH_AWS_ROLE")!="" {
		return fmt.Errorf("unable to authenticate with vault by any configured method. Last error was: vault aws auth not implemented")
	}
	return fmt.Errorf("unable to authenticate with vault by any configured method. Last error was: failed to retrieve credentials from credential chain: NoCredentialProviders: no valid providers in chain. Deprecated.\n\tFor verbose messaging see aws.Config.CredentialsChainVerboseErrors\n")
}

func (r *dsRegistry) readVault(ctx context.Context, ds config.DataSource, sp fsSplit, finalURL *url.URL) (*rawResult,error) {
	name := sp.name
	vc := newVaultClient(finalURL)
	statErr := func(err error) error {
		return fsErr("stat", sp, fmt.Errorf("stat %s: %w", name, err))
	}
	if err := vc.login(ctx); err != nil {
		return nil, statErr(fmt.Errorf("get mount info: vault login failure: %w", err))
	}
	// Determine mount: first path segment
	parts := strings.SplitN(strings.Trim(name,"/"),"/",2)
	mount := parts[0]
	rest := ""
	if len(parts)>1{rest=parts[1]}
	// mount info
	b,code,err:=vc.request(ctx,"GET","sys/internal/ui/mounts/"+mount,nil)
	if err!=nil{ return nil, statErr(fmt.Errorf("get mount info: %w",err)) }
	_ = code
	var mountInfo struct{ Data struct{ Type string `json:"type"`; Options map[string]string `json:"options"` } `json:"data"` }
	_ = json.Unmarshal(b,&mountInfo)
	isKVv2 := mountInfo.Data.Type=="kv" && mountInfo.Data.Options["version"]=="2"
	isDir := strings.HasSuffix(finalURL.Path,"/") || name=="."
	// query params from final URL (excluding type and version for dynamic)
	q := finalURL.Query()
	version := q.Get("version")
	params := map[string]interface{}{}
	for k,vs:=range q { if k!="version" && k!=typeParamName() && len(vs)>0 { params[k]=vs[0] } }
	if isDir {
		listPath := mount+"/"
		if isKVv2 { listPath = mount+"/metadata/" }
		if rest!=""{listPath+=rest}
		if !strings.HasSuffix(listPath,"/"){ /* list on exact prefix */ }
		// LIST method
		reqPath := listPath+"?list=true"
		bb,code,err:=vc.request(ctx,"GET",reqPath,nil)
		if err!=nil{return nil,statErr(err)}; if code==404{return nil,fsErr("stat",sp,fs.ErrNotExist)}
		var out struct{ Data struct{ Keys []string `json:"keys"` } `json:"data"` }
		if err:=json.Unmarshal(bb,&out);err!=nil{return nil,statErr(err)}
		return &rawResult{isDir:true,entries:out.Data.Keys},nil
	}
	readPath := name
	if isKVv2 {
		readPath = mount+"/data/"
		if rest!=""{readPath+=rest}
		if version!=""{readPath+="?version="+url.QueryEscape(version)}
	}
	var bb []byte; var code int
	if len(params)>0 {
		bb,code,err=vc.request(ctx,"POST",readPath,params)
	} else {
		bb,code,err=vc.request(ctx,"GET",readPath,nil)
	}
	if err!=nil{return nil,statErr(err)}
	if code==404{return nil,fsErr("stat",sp,fs.ErrNotExist)}
	if code<200||code>=300{return nil,statErr(fmt.Errorf("vault request failed with status %d: %s",code,string(bb)))}
	// Vault secret JSON is returned as data bytes for parsing by datasource layer.
	// Original datasource returns secret data as a map, not full response. Our readRaw returns bytes
	// that will be parsed as JSON/plain. Transform KV response to just secret data JSON.
	var resp struct{ Data json.RawMessage `json:"data"` }
	if err:=json.Unmarshal(bb,&resp);err==nil && len(resp.Data)>0 {
		data := resp.Data
		if isKVv2 {
			var wrapper struct{ Data json.RawMessage `json:"data"` }
			// resp.Data itself includes data and metadata for kvv2; original with ?version
			// docs shows .data.value, meaning it returns the outer Data object (containing data+metadata)
			// for kvv2 through datasource? Example: (ds "vault").data.value - yes return resp.Data.
			_ = wrapper
		}
		return &rawResult{data:data,mime:"application/json"},nil
	}
	return &rawResult{data:bb,mime:"application/json"},nil
}
func typeParamName() string { if v:=os.Getenv("GOMPLATE_TYPE_PARAM");v!=""{return v}; return "type" }
