	"sort"
	"strings"
	"time"

	"example.com/gomplate/internal/config"
	"example.com/gomplate/internal/datafs"
)

// ---- GIT ----
func splitGitURL(u *url.URL) (repoURL string, repoPath string, inPath string, ref string) {
	ref = u.Fragment
	// Path contains // separator between repo and file
	p := u.Path
	idx := strings.Index(p, "//")
	// For git+file:///tmp/repo//file, Path=/tmp/repo//file idx at after repo
	if idx >= 0 {
		repoPath = p[:idx]
		inPath = strings.TrimPrefix(p[idx+2:], "/")
		// git fs url display is scheme://host + repoPath (no trailing slash)
		ru := *u; ru.Path = repoPath; ru.Fragment=""; ru.RawQuery=""
		repoURL = ru.String()
		return
	}
	ru := *u; ru.Fragment=""; ru.RawQuery=""
	repoURL = ru.String(); repoPath = p; inPath = "."
	return
}
func (r *dsRegistry) readGit(ctx context.Context, alias string, ds config.DataSource, finalURL *url.URL) (*rawResult,error) {
	repoURL, repoPath, inPath, ref := splitGitURL(finalURL)
	sp := fsSplit{fsURL: repoURL, name: inPath, scheme: finalURL.Scheme}
	// Determine clone source and local repo path for file schemes
	isLocal := finalURL.Scheme=="git+file" || finalURL.Scheme=="git" && (finalURL.Host=="" )
	cloneURL := ""
	localRepo := ""
	switch {
	case finalURL.Scheme=="git+file":
		localRepo = repoPath
		cloneURL = "file://" + repoPath
	case finalURL.Scheme=="git+http": cloneURL = "http://" + finalURL.Host + repoPath
	case finalURL.Scheme=="git+https": cloneURL = "https://" + finalURL.Host + repoPath
	case finalURL.Scheme=="git+ssh": cloneURL = "ssh://" + finalURL.Host + repoPath; if finalURL.User!=nil{cloneURL="ssh://"+finalURL.User.String()+"@"+finalURL.Host+repoPath}
	case finalURL.Scheme=="git": cloneURL = finalURL.Scheme+"://"+finalURL.Host+repoPath; if finalURL.Host==""{localRepo=repoPath; cloneURL="file://"+repoPath}
	default: cloneURL = repoURL
	}
	// Add userinfo to clone URLs for https (password env handling simplified)
	if (strings.HasPrefix(cloneURL,"http://")||strings.HasPrefix(cloneURL,"https://")) && finalURL.User!=nil {
		if u,err:=url.Parse(cloneURL);err==nil{
			user:=finalURL.User.Username(); pw,has:=finalURL.User.Password()
			if !has { if v:=envOrFileRoot("GIT_HTTP_PASSWORD"); v!=""{pw=v;has=true} }
			if has{u.User=url.UserPassword(user,pw)}else{u.User=url.User(user)}
			cloneURL=u.String()
		}
	}
	if isLocal || localRepo!="" {
		// check repo existence like go-git error
		absRepo := localRepo
		if !filepath.IsAbs(absRepo){ if cwd,err:=os.Getwd();err==nil{absRepo=filepath.Join(cwd,absRepo)} }
		if _,err:=os.Stat(absRepo); err!=nil{
			return nil, fsErr("open",sp,fmt.Errorf("open: failed to clone: git clone for file://%s/.git failed: repository not found", strings.TrimSuffix(absRepo,"/")))
		}
		if _,err:=os.Stat(filepath.Join(absRepo,".git")); err!=nil {
			// bare repo?
			if _,err2:=os.Stat(filepath.Join(absRepo,"HEAD")); err2!=nil {
				return nil, fsErr("open",sp,fmt.Errorf("open: failed to clone: git clone for file://%s/.git failed: repository not found", strings.TrimSuffix(absRepo,"/")))
			}
		}
	}
	cacheKey := cloneURL+"\x00"+ref
	workdir, ok := r.gitCache[cacheKey]
	if !ok {
		tmp, err := os.MkdirTemp("", "gomplate-git-*")
		if err!=nil{return nil,fsErr("open",sp,err)}
		// Cleanup of tmp not done during process - process exits soon
		args := []string{"clone","--quiet"}
		// git CLI will use env for ssh etc if key file set
		env := os.Environ()
		if key := envOrFileRoot("GIT_SSH_KEY"); key!="" {
			// write to temp key file if content looks like key
			// ignored for ssh-agent case
			_ = key
		}
		_ = env
		cmd := exec.Command("git", append(args, cloneURL, tmp)...)
		cmd.Env = os.Environ()
		// Basic auth token for https via header env?
		if tok:=envOrFileRoot("GIT_HTTP_TOKEN"); tok!="" {
			cmd.Env = append(cmd.Env, "GIT_CONFIG_COUNT=1","GIT_CONFIG_KEY_0=http.extraHeader","GIT_CONFIG_VALUE_0=Authorization: Bearer "+tok)
		}
		out, err := cmd.CombinedOutput()
		if err!=nil {
			msg:=strings.TrimSpace(string(out))
			if isLocal || localRepo!="" { msg = "repository not found" }
			return nil, fsErr("open",sp,fmt.Errorf("open: failed to clone: %s", msg))
		}
		if ref!="" {
			co := exec.Command("git","-C",tmp,"checkout","--quiet",ref)
			if out,err:=co.CombinedOutput();err!=nil{ return nil, fsErr("open",sp,fmt.Errorf("open: %s",strings.TrimSpace(string(out)))) }
		}
		workdir = tmp; r.gitCache[cacheKey]=workdir
	}
	// Read inPath within workdir (use datafs to clean)
	targetPath := filepath.Join(workdir, filepath.FromSlash(inPath))
	if st,err:=os.Stat(targetPath); err==nil && st.IsDir() {
		ents,err:=os.ReadDir(targetPath); if err!=nil{return nil,fsErr("open",sp,err)}
		var names []string
		for _,e:=range ents{ if e.Name()==".git"{continue}; names=append(names,e.Name()) }
		return &rawResult{isDir:true,entries:names},nil
	}
	b,err:=os.ReadFile(targetPath)
	if err!=nil{
		return nil, fsErr("open",sp, fmt.Errorf("open %s: file does not exist", inPath))
	}
	return &rawResult{data:b,mime:mimeForURL(finalURL,inPath,"")},nil
}
func envOrFileRoot(name string) string {
	if v:=os.Getenv(name);v!=""{return v}
	if f:=os.Getenv(name+"_FILE");f!=""{ if b,err:=os.ReadFile(f);err==nil{return strings.TrimSpace(string(b))} }
	return ""
}

// ---- AWS helpers ----
func awsRegion(ctx context.Context, query url.Values) (string,error) {
	if q:=query.Get("region"); q!=""{return q,nil}
	if v:=os.Getenv("AWS_REGION");v!=""{return v,nil}
	if v:=os.Getenv("AWS_DEFAULT_REGION");v!=""{return v,nil}
	// Try IMDS
	endpoint:=os.Getenv("AWS_EC2_METADATA_SERVICE_ENDPOINT"); if endpoint==""{endpoint="http://169.254.169.254"}
	endpoint=strings.TrimSuffix(endpoint,"/")
	urlStr:=endpoint+"/latest/meta-data/placement/region"
	client:=&http.Client{Timeout:2*time.Second}
	resp,err:=client.Get(urlStr)
	if err!=nil{
		return "", fmt.Errorf("couldn't get region from IMDS: read region: getMetaData: operation error ec2imds: GetMetadata, exceeded maximum number of attempts, 3, request send failed, %s: GetMetadata", err.Error())
	}
	defer resp.Body.Close(); b,_:=io.ReadAll(resp.Body)
	if resp.StatusCode!=200 || len(b)==0 {
		return "", fmt.Errorf("couldn't get region from IMDS: read region: getMetaData: operation error ec2imds: GetMetadata, exceeded maximum number of attempts, 3, request send failed, Get %q: %s: GetMetadata", urlStr, resp.Status)
	}
	return strings.TrimSpace(string(b)),nil
}
type awsCreds struct{Key,Secret,Token string}
func getAWSCreds() awsCreds {
	return awsCreds{Key:os.Getenv("AWS_ACCESS_KEY_ID"),Secret:os.Getenv("AWS_SECRET_ACCESS_KEY"),Token:os.Getenv("AWS_SESSION_TOKEN")}
}
func signV4(req *http.Request, body []byte, service, region string, creds awsCreds) {
	if creds.Key==""||creds.Secret==""{return}
	now:=time.Now().UTC()
	amzDate:=now.Format("20060102T150405Z"); dateStamp:=now.Format("20060102")
	req.Header.Set("X-Amz-Date",amzDate)
	if creds.Token!=""{req.Header.Set("X-Amz-Security-Token",creds.Token)}
	// payload hash
	payloadHash:=sha256.Sum256(body); payloadHex:=hex.EncodeToString(payloadHash[:])
	req.Header.Set("X-Amz-Content-Sha256",payloadHex)
	// canonical headers: host;x-amz-content-sha256;x-amz-date (+token if present)
	headersToSign := []string{"host","x-amz-content-sha256","x-amz-date"}
	if creds.Token!=""{headersToSign=append(headersToSign,"x-amz-security-token")}
	sort.Strings(headersToSign)
	var canonHeaders strings.Builder
	for _,h:=range headersToSign{
		var v string
		if h=="host"{v=req.Host; if v==""{v=req.URL.Host}}else{v=req.Header.Get(h)}
		canonHeaders.WriteString(h+":"+strings.TrimSpace(v)+"\n")
	}
	signedHeaders:=strings.Join(headersToSign,";")
	canonURI:=req.URL.EscapedPath(); if canonURI==""{canonURI="/"}
	canonReq := req.Method+"\n"+canonURI+"\n"+req.URL.RawQuery+"\n"+canonHeaders.String()+"\n"+signedHeaders+"\n"+payloadHex
	scope:=fmt.Sprintf("%s/%s/%s/aws4_request",dateStamp,region,service)
	canonHash:=sha256.Sum256([]byte(canonReq))
	stringToSign:="AWS4-HMAC-SHA256\n"+amzDate+"\n"+scope+"\n"+hex.EncodeToString(canonHash[:])
	kDate:=hmacSHA256([]byte("AWS4"+creds.Secret),dateStamp)
	kRegion:=hmacSHA256(kDate,region); kService:=hmacSHA256(kRegion,service); kSigning:=hmacSHA256(kService,"aws4_request")
	sig:=hex.EncodeToString(hmacSHA256(kSigning,stringToSign))
	auth:=fmt.Sprintf("AWS4-HMAC-SHA256 Credential=%s/%s, SignedHeaders=%s, Signature=%s",creds.Key,scope,signedHeaders,sig)
	req.Header.Set("Authorization",auth)
}
func hmacSHA256(key []byte, data string) []byte { h:=hmac.New(sha256.New,key); h.Write([]byte(data)); return h.Sum(nil) }

func (r *dsRegistry) readAWS(ctx context.Context, kind string, ds config.DataSource, sp fsSplit, finalURL *url.URL) (*rawResult,error) {
	region,err:=awsRegion(ctx,finalURL.Query())
	if err!=nil{ return nil, fsErr("open",sp,err) }
	creds:=getAWSCreds()
	name:=sp.name
	if kind=="smp"{
		if strings.HasSuffix(finalURL.Path,"/") {
			// List parameters by path - approximate via GetParametersByPath
			body,_:=json.Marshal(map[string]interface{}{"Path":"/"+strings.Trim(name,"/"),"Recursive":false,"WithDecryption":true})
			status,b,err:=awsJSONRequest(ctx,"ssm",region,creds,"AmazonSSM.GetParametersByPath",body)
			if err!=nil{return nil,fsErr("open",sp,err)}; if status<200||status>=300{return nil,fsErr("open",sp,fmt.Errorf("%s",string(b)))}
			var out struct{ Parameters []struct{Name string `json:"Name"`} `json:"Parameters"` }
			_ = json.Unmarshal(b,&out); entries:=[]string{}; prefix:="/"+strings.Trim(name,"/")+"/"; for _,p:=range out.Parameters{entries=append(entries,strings.TrimPrefix(p.Name,prefix))}; return &rawResult{isDir:true,entries:entries},nil
		}
		paramName:="/"+strings.Trim(name,"/")
		if finalURL.Opaque!=""{paramName=finalURL.Opaque}
		body,_:=json.Marshal(map[string]interface{}{"Name":paramName,"WithDecryption":true})
		status,b,err:=awsJSONRequest(ctx,"ssm",region,creds,"AmazonSSM.GetParameter",body)
		if err!=nil{return nil,fsErr("open",sp,err)}; if status<200||status>=300{return nil,fsErr("open",sp,fmt.Errorf("%s",string(b)))}
		var out struct{ Parameter json.RawMessage `json:"Parameter"` }
		if err:=json.Unmarshal(b,&out);err!=nil{return nil,fsErr("open",sp,err)}
		// Parameter JSON from AWS uses fields Name,Type,Value,Version - pass through as JSON bytes for parsing as JSON map
		return &rawResult{data:out.Parameter,mime:"application/json"},nil
	}
	// secretsmanager
	secretID:=name
	if finalURL.Opaque!=""{secretID=finalURL.Opaque}
	body,_:=json.Marshal(map[string]interface{}{"SecretId":secretID})
	status,b,err:=awsJSONRequest(ctx,"secretsmanager",region,creds,"secretsmanager.GetSecretValue",body)
	if err!=nil{return nil,fsErr("open",sp,err)}; if status<200||status>=300{return nil,fsErr("open",sp,fmt.Errorf("%s",string(b)))}
	var out struct{ SecretString *string `json:"SecretString"`; SecretBinary string `json:"SecretBinary"` }
	if err:=json.Unmarshal(b,&out);err!=nil{return nil,fsErr("open",sp,err)}
	if out.SecretString!=nil{return &rawResult{data:[]byte(*out.SecretString),mime:mimeForURL(finalURL,name,"text/plain; charset=utf-8")},nil}
	dec,err:=base64Decode(out.SecretBinary); if err!=nil{return nil,fsErr("open",sp,err)}
	_ = dec
	return &rawResult{data:dec,mime:"text/plain; charset=utf-8"},nil
}
func base64Decode(s string) ([]byte,error){ return base64StdDecode(s) }
func awsJSONRequest(ctx context.Context, service, region string, creds awsCreds, target string, body []byte) (int,[]byte,error) {
	endpoint:="https://"+service+"."+region+".amazonaws.com/"
	req,_:=http.NewRequestWithContext(ctx,"POST",endpoint,strings.NewReader(string(body)))
	req.Header.Set("Content-Type","application/x-amz-json-1.1"); req.Header.Set("X-Amz-Target",target)
	signV4(req,body,service,region,creds)
	resp,err:=http.DefaultClient.Do(req); if err!=nil{return 0,nil,err}; defer resp.Body.Close(); b,_:=io.ReadAll(resp.Body); return resp.StatusCode,b,nil
}

// S3
func (r *dsRegistry) readS3(ctx context.Context, ds config.DataSource, sp fsSplit, finalURL *url.URL) (*rawResult,error) {
	// s3 FS open wraps as open: open bucket: <region error> for region failures
	q:=finalURL.Query()
	region,err:=awsRegion(ctx,q)
	if err!=nil{
		bucket:=finalURL.Host
		return nil, fsErr("open",sp,fmt.Errorf("open: open %s: %w",bucket,err))
	}
	bucket:=finalURL.Host
	key:=sp.name; if key=="."{key=""}
	endpoint:=q.Get("endpoint"); if endpoint==""{endpoint=os.Getenv("AWS_S3_ENDPOINT")}
	disableSSL:=q.Get("disableSSL")=="true"; forcePath:=q.Get("s3ForcePathStyle")=="true"
	anon:=os.Getenv("AWS_ANON")=="true"
	creds:=getAWSCreds(); if anon{creds=awsCreds{}}
	isDir:=strings.HasSuffix(finalURL.Path,"/") || key==""
	mkURL:=func(k string, query string) string {
		scheme:="https"; if disableSSL{scheme="http"}
		if endpoint!=""{
			ep:=endpoint; if !strings.Contains(ep,"://"){ep=scheme+"://"+ep}
			ep=strings.TrimSuffix(ep,"/")
			if forcePath{return ep+"/"+bucket+"/"+k+query}
			// if endpoint is custom, path style is common; use path if endpoint host is localhost etc, else virtual
			return ep+"/"+bucket+"/"+k+query
		}
		if forcePath{return fmt.Sprintf("%s://s3.%s.amazonaws.com/%s/%s%s",scheme,region,bucket,k,query)}
		return fmt.Sprintf("%s://%s.s3.%s.amazonaws.com/%s%s",scheme,bucket,region,k,query)
	}
	if isDir {
		prefix:=key
		listURL:=mkURL("", "?list-type=2&prefix="+url.QueryEscape(prefix))
		req,_:=http.NewRequestWithContext(ctx,"GET",listURL,nil); signV4(req,nil,"s3",region,creds)
		resp,err:=http.DefaultClient.Do(req); if err!=nil{return nil,fsErr("open",sp,fmt.Errorf("open: %w",err))}; defer resp.Body.Close(); b,_:=io.ReadAll(resp.Body)
		if resp.StatusCode<200||resp.StatusCode>=300{return nil,fsErr("open",sp,fmt.Errorf("open: %s",string(b)))}
		var list struct{ Contents []struct{Key string `xml:"Key"`} `xml:"Contents"` }
		if err:=xml.Unmarshal(b,&list);err!=nil{return nil,fsErr("open",sp,err)}
		seen:=map[string]bool{}; var entries []string
		for _,c:=range list.Contents{ rel:=strings.TrimPrefix(c.Key,prefix); first:=strings.Split(rel,"/")[0]; if first!=""&&!seen[first]{seen[first]=true;entries=append(entries,first)} }
		sort.Strings(entries); return &rawResult{isDir:true,entries:entries},nil
	}
	getURL:=mkURL(key,"")
	req,_:=http.NewRequestWithContext(ctx,"GET",getURL,nil); signV4(req,nil,"s3",region,creds)
	resp,err:=http.DefaultClient.Do(req); if err!=nil{return nil,fsErr("open",sp,fmt.Errorf("open: %w",err))}; defer resp.Body.Close(); b,_:=io.ReadAll(resp.Body)
	if resp.StatusCode<200||resp.StatusCode>=300{return nil,fsErr("open",sp,fmt.Errorf("open: %s",string(b)))}
	return &rawResult{data:b,mime:mimeForURL(finalURL,key,resp.Header.Get("Content-Type"))},nil
}

var _ = datafs.CleanAbs
GO

