cat > render.go <<'GO'
package gomplate

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"text/template"
	"time"

	"example.com/gomplate/funcs"
	"example.com/gomplate/tmpl"
)

func (r *renderer) renderTemplatesWithData(ctx context.Context, templates []tmplData, dataCtx interface{}) error {
	for _, td := range templates {
		start := time.Now()
		err := r.renderTemplate(ctx, td, dataCtx)
		r.duration += time.Since(start)
		if err != nil {
			return err
		}
		r.templatesRendered++
	}
	return nil
}

func (r *renderer) makeFuncContext(ctx context.Context) context.Context {
	st := &funcs.State{Experimental: r.cfg.Experimental}
	st.Datasource = func(c context.Context, alias string, args ...string) (interface{}, error) {
		return r.registry.readParsed(c, alias, args...)
	}
	st.Include = func(c context.Context, alias string, args ...string) (string, error) {
		return r.registry.readInclude(c, alias, args...)
	}
	st.DatasourceExists = func(alias string) bool { return r.registry.exists(alias) }
	st.DatasourceReachable = func(c context.Context, alias string) bool { return r.registry.reachable(c, alias) }
	st.ListDatasources = func() []string { return r.registry.list() }
	st.DefineDatasource = func(alias, url string) (string, error) { return r.registry.define(alias, url) }
	return funcs.WithState(ctx, st)
}

func (r *renderer) parseTemplate(ctx context.Context, name string, contents string, dataCtx interface{}) (*template.Template, error) {
	root := template.New(name)
	root.Delims(r.cfg.LeftDelim, r.cfg.RightDelim)
	mk := r.cfg.MissingKey
	root.Option("missingkey=" + mk)
	tmplObj := tmpl.New(root, dataCtx, name)
	fctx := r.makeFuncContext(ctx)
	funcMap := funcs.CreateFuncs(fctx, tmplObj)
	// plugins
	for pname, pcfg := range r.cfg.Plugins {
		funcMap[pname] = makePluginFunc(ctx, pcfg, r.cfg.PluginTimeout)
	}
	root.Funcs(funcMap)
	if _, err := root.Parse(contents); err != nil {
		return nil, err
	}
	if err := parseNestedTemplates(ctx, root, r); err != nil {
		return nil, fmt.Errorf("parse nested templates: %w", err)
	}
	return root, nil
}

func (r *renderer) renderTemplate(ctx context.Context, td tmplData, dataCtx interface{}) error {
	parsed, err := r.parseTemplate(ctx, td.name, td.contents, dataCtx)
	if err != nil {
		return fmt.Errorf("renderTemplate: parse template %s: %w", td.name, err)
	}
	ioCtx := IOFromContext(ctx)
	var lw *lazyWriter
	if td.output == "-" || td.output == "" {
		lw = newSuppressWriter(ioCtx.Stdout)
	} else {
		outPath := td.output
		mode := td.mode
		lw = newLazyWriter(func() (io.WriteCloser, error) {
			return createOutFile(outPath, mode)
		})
	}
	var execErr error
	if td.noParse {
		// write raw bytes through suppress-empty writer
		_, execErr = lw.Write(td.raw)
	} else {
		execErr = parsed.Execute(lw, dataCtx)
	}
	closeErr := lw.Close()
	if execErr != nil {
		r.errors++
		return fmt.Errorf("renderTemplate: failed to render template %s: %w", td.name, execErr)
	}
	if closeErr != nil {
		r.errors++
		return fmt.Errorf("renderTemplate: failed to render template %s: %w", td.name, closeErr)
	}
	return nil
}

// renderTemplateToString is used for OutputMap templates. It counts as a rendered template.
func (r *renderer) renderString(ctx context.Context, name string, contents string, dataCtx interface{}) (string, error) {
	start := time.Now()
	defer func(){ r.duration += time.Since(start) }()
	parsed, err := r.parseTemplate(ctx, name, contents, dataCtx)
	if err != nil {
		return "", fmt.Errorf("renderTemplate: parse template %s: %w", name, err)
	}
	buf := &bytes.Buffer{}
	// OutputMap templates should not be suppressed if whitespace? They trim output anyway.
	// Use buffer directly (not lazy) but count errors as render errors
	if err := parsed.Execute(buf, dataCtx); err != nil {
		r.errors++
		return "", fmt.Errorf("renderTemplate: failed to render template %s: %w", name, err)
	}
	r.templatesRendered++
	return buf.String(), nil
}

func (r *renderer) renderOutputMap(ctx context.Context, inPath string, dataCtx interface{}) (string, error) {
	// Build new context
	outCtx := make(tmplctx)
	// copy keys from original if it's tmplctx or map
	switch v := dataCtx.(type) {
	case *tmplctx:
		for k, val := range *v { outCtx[k]=val }
	case tmplctx:
		for k, val := range v { outCtx[k]=val }
	case map[string]interface{}:
		for k, val := range v { outCtx[k]=val }
	}
	outCtx["ctx"] = dataCtx
	outCtx["in"] = inPath
	s, err := r.renderString(ctx, "<OutputMap>", r.cfg.OutputMap, &outCtx)
	if err != nil {
		return "", fmt.Errorf("outFileNamer: failed to render outputMap with ctx %v and inPath %s: %w", &outCtx, inPath, err)
	}
	return strings.TrimSpace(s), nil
}

func makePluginFunc(ctx context.Context, pcfg PluginConfig, defaultTimeout time.Duration) func(args ...interface{}) (string, error) {
	return func(args ...interface{}) (string, error) {
		timeout := pcfg.Timeout
		if timeout == 0 { timeout = defaultTimeout }
		cctx := ctx
		var cancel context.CancelFunc
		if timeout > 0 {
			cctx, cancel = context.WithTimeout(ctx, timeout)
			defer cancel()
		}
		cmdArgs := append([]string{}, pcfg.Args...)
		var stdinData string
		hasStdin := false
		strArgs := make([]string, len(args))
		for i,a:=range args {
			// Use a simple fmt conversion compatible with conv.ToString? Plugin args are converted
			// in original via fmt.Sprintf("%v")? Test later. Use our docs: use plugin arg conv using ToString-like
			strArgs[i] = pluginArgString(a)
		}
		if pcfg.Pipe && len(strArgs) > 0 {
			stdinData = strArgs[len(strArgs)-1]
			hasStdin = true
			strArgs = strArgs[:len(strArgs)-1]
		}
		cmdArgs = append(cmdArgs, strArgs...)
		cmd := exec.CommandContext(cctx, pcfg.Cmd, cmdArgs...)
		if hasStdin { cmd.Stdin = strings.NewReader(stdinData) }
		// plugin stderr goes to gomplate stderr (os.Stderr) - original uses cmd.Stderr = os.Stderr?
		cmd.Stderr = os.Stderr
