	}
	st.Include = func(c context.Context, alias string, args ...string) (string, error) {
		return r.registry.readInclude(c, alias, args...)
	}
	st.DatasourceExists = func(alias string) bool { return r.registry.exists(alias) }
	st.DatasourceReachable = func(c context.Context, alias string) bool { return r.registry.reachable(c, alias) }
	st.ListDatasources = func() []string { return r.registry.list() }
