	root := template.New(name)
	root.Delims(r.cfg.LeftDelim, r.cfg.RightDelim)
	mk := r.cfg.MissingKey
	root.Option("missingkey=" + mk)
	tmplObj := tmpl.New(root, dataCtx, name)
	fctx := r.makeFuncContext(ctx)
	funcMap := funcs.CreateFuncs(fctx, tmplObj)
