package gomplate

import (
	"context"
	"fmt"
	"io"
	"io/fs"
	"net/http"
	"net/url"
	"path"
	"path/filepath"
	"strings"
	"text/template"

	"example.com/gomplate/internal/datafs"
)

func parseNestedTemplates(ctx context.Context, root *template.Template, r *renderer) error {
	for alias, src := range r.cfg.Templates {
		// Split into parent url and name
		parentURL, name := splitTemplateURL(src.URL)
		// Stat
		isDir, statErr := statTemplateSource(ctx, r, src, parentURL, name)
		if statErr != nil {
			return fmt.Errorf("stat %q: %w", name, statErr)
		}
		if isDir {
			entries, err := readDirTemplateSource(ctx, r, src, parentURL, name)
			if err != nil { return err }
			for _, entry := range entries {
				if entry.IsDir { continue }
				contents, err := readTemplateFile(ctx, r, src, parentURL, joinTemplateName(name, entry.Name))
				if err != nil { return err }
				tname := path.Join(alias, entry.Name)
				// path.Join cleans ./ etc - for aliases like "./top.t" this branch not used
				// Alias for directories: original joins alias + "/" + name without cleaning "./"?
				// Use simple slash join preserving alias prefix if alias ends with /?
				tname = strings.TrimSuffix(alias, "/") + "/" + entry.Name
				if alias == "" { tname = entry.Name }
				if _, err := root.New(tname).Parse(string(contents)); err != nil { return err }
			}
		} else {
			contents, err := readTemplateFile(ctx, r, src, parentURL, name)
			if err != nil {
				// readTemplateFile for http uses GET and errors may be wrapped as readFile in original for some FS,
				// but for file we only reach here after successful stat, so read errors are rare (permissions)
				return err
			}
			if _, err := root.New(alias).Parse(string(contents)); err != nil { return err }
		}
		_ = ctx
	}
	return nil
}

type dirEntry struct { Name string; IsDir bool }

func splitTemplateURL(u *url.URL) (*url.URL, string) {
	if u == nil { return &url.URL{}, "" }
	if u.Opaque != "" {
		// opaque e.g. file:foo, env:foo - parent is scheme root, name opaque path
		parent := &url.URL{Scheme: u.Scheme, Path: "/"}
		// For file:foo original stats foo in cwd(?) - name foo
		return parent, u.Opaque
	}
	p := u.Path
	if strings.HasSuffix(p, "/") {
		parent := *u
		return &parent, "."
	}
	dir, base := path.Split(p)
	parent := *u
	parent.Path = dir
	parent.RawPath = ""
	return &parent, base
}

func joinTemplateName(dirName string, base string) string {
	if dirName == "." { return base }
	if dirName == "" { return base }
	return strings.TrimSuffix(dirName, "/") + "/" + base
}

// localRootDir resolves parent URL to a local directory for file/relative schemes
func localRootDir(parent *url.URL) string {
	if parent.Scheme == "file" {
		// file:///tmp/ -> /tmp ; file:/tmp/ -> /tmp ; file://host/path -> /path (host ignored as original)
		return datafs.CleanAbs(parent.Path)
	}
	// relative
	if parent.Path == "" { return datafs.CleanAbs(".") }
