{"command":"cat > funcs/jsonpath.go <<'GO'
package funcs

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
)

// ---- JSONPath ----

type jpAction struct {
	kind string // root, child, recursive, wildcard, index, union, slice, filter
	name string
	index int
	indexes []int
	keys []string
	start *int
	end *int
	step *int
	filter *jpFilter
}
type jpFilter struct {
	left []string // path segments after @ (names / indexes as strings)
	op string
	right interface{}
	rightIsPath bool
	rightPath []string
}

func jsonPathQuery(expr string, in interface{}) (interface{}, error) {
	actions, err := parseJSONPath(expr)
	if err != nil {
		return nil, fmt.Errorf("couldn't parse JSONPath %s: %w", expr, err)
	}
	res, err := execJSONPath(actions, in)
	if err != nil {
		return nil, fmt.Errorf("executing JSONPath failed: %w", err)
	}
	return res, nil
}

func jpParseErr(format string, args ...interface{}) error { return fmt.Errorf(format, args...) }

func parseJSONPath(expr string) ([]jpAction, error) {
	if expr == "" {
		return []jpAction{{kind:"root"}}, nil
	}
	// tokenizer / parser loop
	var actions []jpAction
	i := 0
	// helper to report unrecognized char
	unrec := func(r rune) error {
		return jpParseErr("unrecognized character in action: U+%04X %q", r, r)
	}
	parseIdent := func() string {
		start := i
		for i < len(expr) {
			r := rune(expr[i])
			if unicode.IsLetter(r) || unicode.IsDigit(r) || r=='_' || r=='-' {
				i++
			} else { break }
		}
		return expr[start:i]
	}
	for i < len(expr) {
		c := expr[i]
		switch {
		case c == '$' || c == '@':
			// root only valid at start in our parser; treat any $ as root marker
			actions = append(actions, jpAction{kind:"root"})
			i++
		case c == '.':
			// check recursive
			recursive := false
			if i+1 < len(expr) && expr[i+1] == '.' { recursive = true; i += 2 } else { i++ }
			if i < len(expr) && expr[i] == '*' {
				if recursive {
					return nil, unrec('*')
				}
				actions = append(actions, jpAction{kind:"wildcard"})
				i++
				continue
			}
			if i < len(expr) && expr[i] == '[' && recursive {
				// $..[ ... ] handled as recursive bracket - mark by inserting a recursive marker action
				actions = append(actions, jpAction{kind:"recursive_wildcard"})
				continue
			}
			name := parseIdent()
			// name may be empty ($. at end)
			kind := "child"; if recursive { kind = "recursive" }
			actions = append(actions, jpAction{kind:kind, name:name})
		case c == '[':
			// find closing ]
			end := -1
			inS := byte(0)
			depthParen := 0
			for j:=i+1;j<len(expr);j++ {
				ch := expr[j]
				if inS != 0 { if ch==inS {inS=0}; continue }
				if ch=='\'' || ch=='"' { inS=ch; continue }
				if ch=='(' {depthParen++}
				if ch==')' {depthParen--}
				if ch==']' && depthParen==0 { end=j; break }
			}
			if end==-1 {
				content := expr[i+1:]
				if strings.Contains(content, "?") || strings.Contains(content,"(") {
					return nil, jpParseErr("unclosed array expect ]")
				}
				return nil, jpParseErr("unterminated array")
			}
			content := strings.TrimSpace(expr[i+1:end])
			act, err := parseBracket(content)
			if err != nil { return nil, err }
			actions = append(actions, act)
			i = end+1
		case c==' ':
			i++
		default:
			// identifier at start (unrecognized identifier at execution)
			if unicode.IsLetter(rune(c)) || c=='_' {
				name := parseIdent()
				actions = append(actions, jpAction{kind:"ident", name:name})
				continue
			}
			return nil, unrec(rune(c))
		}
	}
	if len(actions)==0 { actions = append(actions, jpAction{kind:"root"}) }
	return actions, nil
}

func parseBracket(content string) (jpAction, error) {
	if content == "*" { return jpAction{kind:"wildcard"}, nil }
	if strings.HasPrefix(content, "?") {
		f, err := parseFilter(content)
		if err != nil { return jpAction{}, err }
		return jpAction{kind:"filter", filter:f}, nil
	}
	// slice detection (colon at top-level, not in quotes)
	if strings.Contains(content, ":") && !strings.HasPrefix(content, "'") {
		parts := strings.Split(content, ":")
		if len(parts) < 2 || len(parts) > 3 {
			return jpAction{}, jpParseErr("invalid slice %q", content)
		}
		act := jpAction{kind:"slice"}
		parseOpt := func(idx int) (*int,error) {
			s:=strings.TrimSpace(parts[idx]); if s==""{return nil,nil}; v,err:=strconv.Atoi(s); if err!=nil{return nil,jpParseErr("invalid array index %q", s)}; return &v,nil
		}
		var err error
		act.start,err=parseOpt(0); if err!=nil{return act,err}
		act.end,err=parseOpt(1); if err!=nil{return act,err}
		if len(parts)==3{act.step,err=parseOpt(2); if err!=nil{return act,err}}
		return act,nil
	}
	// union split by commas at top level
	if strings.Contains(content, ",") {
		parts := splitTopCommas(content)
		// all numbers?
		var idxs []int; var keys []string; allNum:=true; allKey:=true
		for _,p:=range parts{
			p=strings.TrimSpace(p)
			if strings.HasPrefix(p,"'") && strings.HasSuffix(p,"'") && len(p)>=2 { keys=append(keys,p[1:len(p)-1]); allNum=false; continue }
			if v,err:=strconv.Atoi(p); err==nil { idxs=append(idxs,v); allKey=false; continue }
			// invalid like "store"
			return jpAction{}, jpParseErr("invalid array index %q", strings.Trim(p,"\""))
		}
		if allKey { return jpAction{kind:"union",keys:keys},nil }
		_ = allNum
		return jpAction{kind:"union",indexes:idxs,keys:keys},nil
	}
	// single quoted key
	if strings.HasPrefix(content,"'") && strings.HasSuffix(content,"'") && len(content)>=2 {
		return jpAction{kind:"child",name:content[1:len(content)-1]},nil
	}
	if strings.HasPrefix(content,"\"") {
		inside := strings.Trim(content,"\"")
		return jpAction{}, jpParseErr("invalid array index %q", inside)
	}
	if v,err:=strconv.Atoi(strings.TrimSpace(content)); err==nil {
		return jpAction{kind:"index",index:v},nil
	}
	return jpAction{}, jpParseErr("invalid array index %q", content)
}
func splitTopCommas(s string) []string {
	var out []string; var cur strings.Builder; var quote byte
	for i:=0;i<len(s);i++{ch:=s[i]; if quote!=0{cur.WriteByte(ch); if ch==quote{quote=0}; continue}; if ch=='\''||ch=='"'{quote=ch;cur.WriteByte(ch);continue}; if ch==','{out=append(out,cur.String());cur.Reset();continue}; cur.WriteByte(ch)}
	out=append(out,cur.String()); return out
}

func parseFilter(content string) (*jpFilter,error) {
	// content starts with ? ; expect (...)
	s:=strings.TrimSpace(strings.TrimPrefix(content,"?"))
	if !strings.HasPrefix(s,"(") || !strings.HasSuffix(s,")") {
		// yalp allows ?( ... ) only
		return nil, jpParseErr("unclosed array expect ]")
	}
	inner:=strings.TrimSpace(s[1:len(s)-1])
	// unsupported characters
	for _,r:=range inner {
		if r=='&' || r=='|' || r=='~' {
			return nil, jpParseErr("unrecognized character in action: U+%04X %q", r, r)
		}
	}
	// Split operator: find ==, !=, <=, >=, <, > at top level (outside quotes)
	op:=""; idx:=-1
	for _, candidate := range []string{"==","!=","<=" ,">=","<",">"} {
		if j:=strings.Index(inner,candidate); j>=0 { op=candidate; idx=j; break }
	}
	// Also find word in as pseudo-operator (treat as existence)
	if idx==-1 {
		if j:=strings.Index(inner," in "); j>=0 { op="in"; idx=j }
	}
	f:=&jpFilter{}
	leftStr:=inner
	var rightStr string
	if idx>=0 { leftStr=strings.TrimSpace(inner[:idx]); if op=="in" {rightStr=strings.TrimSpace(inner[idx+4:])} else {rightStr=strings.TrimSpace(inner[idx+len(op):])}; f.op=op }
	// left path
	lf, err:=parseFilterPath(leftStr); if err!=nil{return nil,err}; f.left=lf
	if idx>=0 {
		if op=="in" {
			// ignore right as in original weird behaviour - treat as existence
			f.op = ""
		} else if strings.HasPrefix(rightStr,"@") || strings.HasPrefix(rightStr,"$") {
			rp,err:=parseFilterPath(rightStr); if err!=nil{return nil,err}
			f.rightIsPath=true; f.rightPath=rp
		} else {
			v,err:=parseFilterLiteral(rightStr); if err!=nil{return nil,err}; f.right=v
		}
	}
	return f,nil
}
func parseFilterPath(s string) ([]string,error) {
	s=strings.TrimSpace(s)
	if s==""{return nil,nil}
	if s[0]=='@' || s[0]=='$' { s=s[1:] }
	var segs []string
	i:=0
