// Minimal JQ implementation (subset compatible with common gojq usage)

func jqQuery(expr string, in interface{}) (interface{}, error) {
	if strings.TrimSpace(expr) == "" {
		return nil, fmt.Errorf("jq execution: missing query (try \".\")")
	}
	p := &jqParser{s: expr}
	ast, err := p.parseTop()
	if err != nil {
		return nil, fmt.Errorf("jq parsing expression %q: %w", expr, err)
	}
	ctx := &jqCtx{vars: map[string]interface{}{}, funcs: map[string]*jqFuncDef{}}
	input := jqNormalize(in)
	out, err := ast.eval(ctx, input)
	if err != nil {
		return nil, fmt.Errorf("jq execution: %w", err)
	}
	if len(out) == 0 {
		return []interface{}{}, nil
	}
	if len(out) == 1 {
		return out[0], nil
	}
	return out, nil
}

func jqNormalize(v interface{}) interface{} {
	if v == nil { return nil }
	switch x := v.(type) {
	case bool, string, int, float64:
		return x
	case int64:
		return int(x)
	case int32:
		return int(x)
	case float32:
		return float64(x)
	case uint64:
		if x <= uint64(^uint(0)>>1) { return int(x) }
		return float64(x)
	case uint:
		return int(x)
	case []byte:
		return string(x)
	case map[string]interface{}:
		out := make(map[string]interface{}, len(x))
		for k, val := range x { out[k] = jqNormalize(val) }
		return out
	case []interface{}:
		out := make([]interface{}, len(x))
		for i, el := range x { out[i] = jqNormalize(el) }
		return out
	case json.Number:
		if iv, err := x.Int64(); err == nil { return int(iv) }
		fv, _ := x.Float64(); return fv
	}
	rv := reflect.ValueOf(v)
	rv = indirectValue(rv)
	if !rv.IsValid() { return nil }
	switch rv.Kind() {
	case reflect.Map:
		out := make(map[string]interface{})
		iter := rv.MapRange()
		for iter.Next() { out[toString(iter.Key().Interface())] = jqNormalize(iter.Value().Interface()) }
		return out
	case reflect.Slice, reflect.Array:
		out := make([]interface{}, rv.Len())
		for i:=0;i<rv.Len();i++ { out[i] = jqNormalize(rv.Index(i).Interface()) }
		return out
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return int(rv.Int())
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		return int(rv.Uint())
	case reflect.Float32, reflect.Float64:
		return rv.Float()
	case reflect.String:
		return rv.String()
	case reflect.Bool:
		return rv.Bool()
	}
	// try JSON marshal/unmarshal for structs etc
	if b, err := json.Marshal(v); err == nil {
		var out interface{}
		d := json.NewDecoder(strings.NewReader(string(b))); d.UseNumber()
		if err := d.Decode(&out); err == nil { return jqNormalize(out) }
	}
	return toString(v)
}

func jqType(v interface{}) string {
	switch v.(type) {
	case nil: return "null"
	case bool: return "boolean"
	case int, int64, float64, float32: return "number"
	case string: return "string"
	case []interface{}: return "array"
	case map[string]interface{}: return "object"
	default:
		if isNumericKind(reflect.ValueOf(v).Kind()) {return "number"}
		return "object"
	}
}

func jqJSON(v interface{}) string {
	b, _ := json.Marshal(v)
	return string(b)
}
func jqPreview(v interface{}) string {
	t := jqType(v)
	if v == nil { return "null" }
	j := jqJSON(v)
	if len(j) <= 32 { return fmt.Sprintf("%s (%s)", t, j) }
	// truncate like gojq-ish: include initial elements/entries
	switch t {
	case "object":
		m := v.(map[string]interface{})
		keys := sortedKeys(m)
		var parts []string
		size := 1
		for _, k := range keys {
			part := strconv.Quote(k) + ":" + jqJSON(m[k])
			if size+len(part)+6 > 32 && len(parts)>0 { break }
			parts = append(parts, part); size += len(part)+1
		}
		return fmt.Sprintf("object ({%s ...})", strings.Join(parts, ","))
	case "array":
		a := v.([]interface{}); var parts []string; size:=1
		for _, el := range a { part:=jqJSON(el); if size+len(part)+6>32 && len(parts)>0{break}; parts=append(parts,part); size+=len(part)+1 }
		return fmt.Sprintf("array ([%s ...])", strings.Join(parts,","))
	case "string":
		s := v.(string); if len(s)>20{s=s[:20]}; return fmt.Sprintf("string (%q...)", s)
	}
	return fmt.Sprintf("%s (%s)", t, j)
}
