type jqNode interface { eval(c *jqCtx, in interface{}) ([]interface{}, error) }

// parser
type jqParser struct { s string; pos int }
func (p *jqParser) parseTop() (jqNode,error) {
	// function definitions
	var defs []*jqDefNode
	for {
		p.skip()
		if p.consumeWord("def") {
			p.skip(); name:=p.parseIdentOrFuncName(); if name==""{return nil, errors.New("unexpected token")}
			var params []string
			p.skip()
			if p.peek()=='(' { p.pos++; for { p.skip(); if p.peek()==')'{p.pos++;break}; nm:=p.parseParamName(); params=append(params,nm); p.skip(); if p.peek()==';'{p.pos++;continue}; if p.peek()==')'{p.pos++;break}; return nil,p.errHere() } }
			p.skip(); if p.peek()!=':'{return nil,p.errHere()}; p.pos++
			body,err:=p.parsePipe(); if err!=nil{return nil,err}
			p.skip(); if p.peek()!=';'{return nil,p.errHere()}; p.pos++
			defs=append(defs,&jqDefNode{name:name,params:params,body:body})
			continue
		}
		break
	}
	n,err:=p.parsePipe(); if err!=nil{return nil,err}
	p.skip(); if p.pos<len(p.s){return nil,p.errHere()}
	if len(defs)>0{
