		nf:=make(map[string]*jqFuncDef,len(nc.funcs)); for k,v:=range nc.funcs{nf[k]=v}; nc.funcs=nf
	}
	for _,d:=range n.defs{nc.funcs[fmt.Sprintf("%s/%d",d.name,len(d.params))]=&jqFuncDef{params:d.params,body:d.body}}
