func (p *jqParser) parseIdentOrFuncName() string {
	// handle @format and :: names
	if p.peek()=='@'{start:=p.pos; p.pos++; _=p.parseIdent(); return p.s[start:p.pos]}
	name:=p.parseIdent()
	if p.peek()==':'&&p.peekAt(1)==':'{p.pos+=2; name+="::"+p.parseIdent()}
