func (p *jqParser) peekAt(n int) byte { if p.pos+n>=len(p.s){return 0}; return p.s[p.pos+n] }
func (p *jqParser) errHere() error {
	if p.pos>=len(p.s){return errors.New("unexpected EOF")}
