			combined:=&jqPipeNode{left:cur,right:right}
			return &jqBindNode{src:combined,patterns:[]jqBindPattern{pat},body:body},nil
		}
		p.pos=save2
		cur=&jqPipeNode{left:cur,right:right}
	}
