type jqBinaryNode struct{op string; left,right jqNode}
func (n *jqBinaryNode) eval(c *jqCtx,in interface{}) ([]interface{},error){
	// jq binary ops produce cross product of left/right outputs
	ls,err:=n.left.eval(c,in); if err!=nil{return nil,err}; rs,err:=n.right.eval(c,in); if err!=nil{return nil,err}
