			}
			return p.parsePostfix(&jqTryNode{body:body,catch:handler})
		case "true": return p.parsePostfix(&jqLiteralNode{true})
		case "false": return p.parsePostfix(&jqLiteralNode{false})
		case "null": return p.parsePostfix(&jqLiteralNode{nil})
		case "def": // handled in parseTop only, nested defs could occur as term? not supported
			return nil,errors.New("unexpected token \"def\"")
		default:
			// function call name possibly with ::
			name:=word
			if p.peek()==':' && p.peekAt(1)==':'{p.pos+=2; name+="::"+p.parseIdent()}
			p.skip()
			var args []jqNode
			if p.peek()=='('{
				p.pos++; p.skip()
				if p.peek()!=')'{
					for{
						arg,err:=p.parsePipe(); if err!=nil{return nil,err}; args=append(args,arg); p.skip(); if p.peek()==';'{p.pos++;continue}; break
					}
				}
				p.skip(); if p.peek()!=')'{return nil,p.errHere()}; p.pos++
