	cond,err:=p.parsePipeUntilThen(); if err!=nil{return nil,err}
	// parsePipeUntilThen leaves pos after 'then'? Implementation: parseExpr but stop before then keyword is handled in parseTerm returning a call named then awkward.
	// Instead parsePipeUntilThen is implemented specially below - it returns cond and consumes then.
	body,err:=p.parsePipeUntilElifElseEnd(); if err!=nil{return nil,err}
	branches=append(branches,branch{cond,body})
	for {
		p.skip()
