			c,err:=p.parsePipeUntilThen(); if err!=nil{return nil,err}
			b,err:=p.parsePipeUntilElifElseEnd(); if err!=nil{return nil,err}
			branches=append(branches,branch{c,b}); continue
		}
		if p.consumeWord("else") {
			b,err:=p.parsePipeUntilEnd(); if err!=nil{return nil,err}; elseBody=b; break
		}
		if p.consumeWord("end"){break}
		return nil,p.errHere()
	}
