// The following helpers parse a pipe but intercept keywords then/elif/else/end as terminators by temporarily
// parsing a pipe and rolling back a trailing call node named that keyword - simpler: we parse using parsePipe but
// stop when parser encounters terminator at term start. Our parseTerm for keywords 'then' would create a call node; to avoid,
// parsePipeUntilThen temporarily scans by parsing with parsePipe and trimming.
// Implementation approach: record start, parse a jq expression using parsePipe(), but parsePipe will encounter 'then' as a function call after pipe? Actually `if .n>40 then` - after parsing condition `.n>40`, parser is in parseMul etc and then word 'then' is not consumed as operator, it returns. Then parsePipe sees 'then' as leftover. So parsePipeUntilThen can just call parsePipe and then consume then.
func (p *jqParser) parsePipeUntilThen() (jqNode,error){
	n,err:=p.parsePipe(); if err!=nil{return nil,err}
	p.skip(); if !p.consumeWord("then"){return nil,p.errHere()}; return n,nil
}
func (p *jqParser) parsePipeUntilElifElseEnd() (jqNode,error){
	// Parse a pipe; following keyword will remain unconsumed because operators don't consume words except and/or.
	// But if body contains `and` etc it is fine. A body like `"big"` ends before else.
	return p.parsePipe()
}
func (p *jqParser) parsePipeUntilEnd() (jqNode,error){
	n,err:=p.parsePipe(); if err!=nil{return nil,err}
	p.skip(); if !p.consumeWord("end"){return nil,p.errHere()}
	return n,nil
}
type jqIfNode struct{cond,then,els jqNode}
func (n *jqIfNode) eval(c *jqCtx,in interface{}) ([]interface{},error){
	conds,err:=n.cond.eval(c,in); if err!=nil{return nil,err}
	var out []interface{}
	for _,condVal:=range conds{
		branch:=n.els; if jqTruthy(condVal){branch=n.then}
		if branch==nil{out=append(out,in);continue}
		r,err:=branch.eval(c,in); if err!=nil{return nil,err}; out=append(out,r...)
	}
	return out,nil
}
func jqTruthy(v interface{}) bool { return !(v==nil || v==false) }
type jqTryNode struct{body,catch jqNode}
func (n *jqTryNode) eval(c *jqCtx,in interface{}) ([]interface{},error){
	r,err:=n.body.eval(c,in); if err==nil{return r,nil}
	if n.catch==nil{return []interface{}{},nil}
