	return []interface{}{"gomplate"},nil
}
type jqArrayNode struct{inner jqNode}
func (n *jqArrayNode) eval(c *jqCtx,in interface{}) ([]interface{},error){
	if n.inner==nil{return []interface{}{[]interface{}{}},nil}
	vals,err:=n.inner.eval(c,in); if err!=nil{return nil,err}
	if vals==nil{vals=[]interface{}{}}
	return []interface{}{vals},nil
}

func isDigit(b byte) bool { return b>='0'&&b<='9' }
func isIdentStart(b byte) bool { return b=='_'||(b>='A'&&b<='Z')||(b>='a'&&b<='z') }
func (p *jqParser) parseNumber() jqNode {
	start:=p.pos
	for p.pos<len(p.s)&& isDigit(p.peek()){p.pos++}
	isFloat:=false
	if p.pos<len(p.s)&&p.s[p.pos]=='.'{ isFloat=true; p.pos++; for isDigit(p.peek()){p.pos++} }
	if p.pos<len(p.s)&&(p.s[p.pos]=='e'||p.s[p.pos]=='E'){ isFloat=true; p.pos++; if p.peek()=='+'||p.peek()=='-'{p.pos++}; for isDigit(p.peek()){p.pos++} }
	txt:=p.s[start:p.pos]
	if !isFloat{ if iv,err:=strconv.ParseInt(txt,10,64);err==nil{return &jqLiteralNode{int(iv)}} }
