func (p *jqParser) parseStringLiteral() (jqNode,error) {
	// current at "
	p.pos++
	var parts []interface{}
	var cur strings.Builder
	for p.pos<len(p.s){
		ch:=p.s[p.pos]
		if ch=='\\' && p.pos+1<len(p.s){
			nx:=p.s[p.pos+1]
			if nx=='('{
				if cur.Len()>0{parts=append(parts,cur.String());cur.Reset()}
				p.pos+=2
				n,err:=p.parsePipe(); if err!=nil{return nil,err}
				p.skip(); if p.peek()!=')'{return nil,p.errHere()}; p.pos++
				parts=append(parts,n); continue
			}
			// Handle escapes using JSON unquote for this escape sequence if simple
			// consume escape as a quoted fragment
			esc:=p.s[p.pos:p.pos+2]; p.pos+=2
