			case 'n':cur.WriteByte('\n');case 't':cur.WriteByte('\t');case 'r':cur.WriteByte('\r');case 'b':cur.WriteByte('\b');case 'f':cur.WriteByte('\f');case '"':cur.WriteByte('"');case '\\':cur.WriteByte('\\');case '/':cur.WriteByte('/');case 'u':
