func (p *jqParser) parseObject() (jqNode,error){
	p.pos++ // {
	var entries []jqObjEntry
	p.skip()
	if p.peek()=='}'{p.pos++; return &jqObjectNode{entries:entries},nil}
	for{
		p.skip()
		var keyNode jqNode; var key string; var isExprKey bool; var shorthandField string
		if p.peek()=='('{
			p.pos++; kn,err:=p.parsePipe(); if err!=nil{return nil,err}; p.skip(); if p.peek()!=')'{return nil,p.errHere()}; p.pos++; keyNode=kn; isExprKey=true
		} else if p.peek()=='"'{
			sn,err:=p.parseStringLiteral(); if err!=nil{return nil,err}; keyNode=sn; isExprKey=true
		} else if p.peek()=='.'{
			// shorthand .foo
			save:=p.pos; p.pos++; ident:=p.parseIdent(); if ident==""{p.pos=save; return nil,p.errHere()}; shorthandField=ident; key=ident
		} else {
			ident:=p.parseIdent(); if ident==""{return nil,p.errHere()}; key=ident
		}
		p.skip()
		var val jqNode
		if p.peek()==':'{
			p.pos++
			v,err:=p.parsePipe(); if err!=nil{return nil,err}; val=v
