		} else if key!=""{
			// {foo} shorthand equivalent to {"foo": .foo}
			val=&jqPathNode{segs:[]jqPathSegment{{kind:"field",name:key}}}
		} else { return nil,p.errHere() }
		entries=append(entries,jqObjEntry{key:key,keyNode:keyNode,isExprKey:isExprKey,value:val})
