		if p.peek()==','{p.pos++;continue}
		if p.peek()=='}'{p.pos++;break}
		return nil,p.errHere()
	}
	return &jqObjectNode{entries:entries},nil
}
type jqObjEntry struct{key string; keyNode jqNode; isExprKey bool; value jqNode}
type jqObjectNode struct{entries []jqObjEntry}
func (n *jqObjectNode) eval(c *jqCtx,in interface{}) ([]interface{},error){
	// Cartesian product over keys/values if multiple outputs
	results:=[]map[string]interface{}{{}}
	for _,e:=range n.entries{
		var keys []string
		if e.isExprKey{ kv,err:=e.keyNode.eval(c,in); if err!=nil{return nil,err}; for _,k:=range kv{keys=append(keys,jqToString(k))} } else {keys=[]string{e.key}}
		vals,err:=e.value.eval(c,in); if err!=nil{return nil,err}
		var newRes []map[string]interface{}
		for _,base:=range results{ for _,k:=range keys{ for _,v:=range vals{ nm:=make(map[string]interface{},len(base)+1); for kk,vv:=range base{nm[kk]=vv}; nm[k]=v; newRes=append(newRes,nm)}}}
		results=newRes
	}
	out:=make([]interface{},len(results)); for i,r:=range results{out[i]=r}; return out,nil
}
