func sliceJQRunes(a []rune, start,end *int) []rune {
	n:=len(a); s:=0; e:=n
	if start!=nil{s=*start; if s<0{s+=n}; if s<0{s=0}; if s>n{s=n}}
	if end!=nil{e=*end; if e<0{e+=n}; if e<0{e=0}; if e>n{e=n}}
