			base=&jqSpecialVarNode{name:name}; return p.parsePostfix(base)
		}
		base=&jqVarNode{name:"$"+name}; return p.parsePostfix(base)
	case c=='(':
		p.pos++; n,err:=p.parsePipe(); if err!=nil{return nil,err}; p.skip(); if p.peek()!=')'{return nil,p.errHere()}; p.pos++; return p.parsePostfix(n)
	case c=='[': // array construction
		p.pos++; p.skip(); if p.peek()==']'{p.pos++; return p.parsePostfix(&jqArrayNode{})}
		inner,err:=p.parsePipe(); if err!=nil{return nil,err}; p.skip(); if p.peek()!=']'{return nil,p.errHere()}; p.pos++; return p.parsePostfix(&jqArrayNode{inner:inner})
