package funcs

import (
	"strconv"
)

func (p *jqParser) parsePostfix(base jqNode) (jqNode,error) {
	// Applies path segments starting with '.' or '[' and optional '?'
	for {
		p.skip()
		// optional marker is handled inside segments - a standalone '?' after term makes it optional
		if p.peek()=='?' {
			p.pos++
			if pn,ok:=base.(*jqPathNode); ok { pn.optional=true; base=pn } else { base=&jqOptionalNode{node:base} }
			continue
		}
		var segs []jqPathSegment
		var err error
		if p.peek()=='.' && p.peekAt(1)!='.' {
			save:=p.pos; p.pos++
			segs,err=p.parseDotSegments(false)
			if err!=nil{return nil,err}
			if len(segs)==0{p.pos=save; break}
		} else if p.peek()=='[' {
			seg,err2:=p.parseBracketSegment(); if err2!=nil{return nil,err2}; segs=[]jqPathSegment{seg}
		} else { break }
		if pn,ok:=base.(*jqPathNode); ok && pn.base==nil {
			pn.segs=append(pn.segs,segs...); base=pn
		} else {
			base=&jqPathNode{base:base,segs:segs}
		}
	}
	return base,nil
}
type jqOptionalNode struct{node jqNode}
func (n *jqOptionalNode) eval(c *jqCtx,in interface{}) ([]interface{},error){
	r,err:=n.node.eval(c,in); if err!=nil{return []interface{}{},nil}; return r,nil
}
func (p *jqParser) parsePostfixOptional(base jqNode) (jqNode,error) {
	// Path nodes already built may be followed by '?' or more segments in parseTerm for identity/recursive -
	// Our recursive/identity creation returns base and parsePostfix handles segments.
	// For . path nodes, parsePostfix will merge extra segments.
	return p.parsePostfix(base)
}

// parseDotSegments parses segments after an initial dot has been consumed.
// first=true means this is the start of a .foo path (foo is a segment here).
// Subsequent .foo / [..] are also consumed.
func (p *jqParser) parseDotSegments(first bool) ([]jqPathSegment,error) {
	var segs []jqPathSegment
	// parse first segment right after dot if present
	if p.pos<len(p.s) {
		if isIdentStart(p.peek()) {
			name:=p.parseIdent(); segs=append(segs,jqPathSegment{kind:"field",name:name})
		} else if p.peek()=='"' {
			// ."foo"
			sn,err:=p.parseStringLiteral(); if err!=nil{return nil,err}
			// evaluate string node to static if simple
			key:=""
			if sNode,ok:=sn.(*jqStringNode);ok && len(sNode.parts)==1{ if str,ok:=sNode.parts[0].(string);ok{key=str} }
			segs=append(segs,jqPathSegment{kind:"field",name:key})
		} else if p.peek()=='[' {
			seg,err:=p.parseBracketSegment(); if err!=nil{return nil,err}; segs=append(segs,seg)
		}
	}
	// Our parsePostfix will handle further . / [ segments, so only parse one here to keep
	// optional handling centralized. But parseTerm for dot path expects entire chain initially:
	// It calls parsePostfix afterwards which will add remaining segments.
	_ = first
	// Consume an immediate '?' as optional on last segment
	if p.peek()=='?' && len(segs)>0 { segs[len(segs)-1].optional=true; p.pos++ }
