func (p *jqParser) parsePathSegmentsAfterRecursive() ([]jqPathSegment,error) {
	// after .., a field name or [..]
	if p.peek()=='[' { seg,err:=p.parseBracketSegment(); return []jqPathSegment{seg},err }
