func (p *jqParser) parseBracketSegment() (jqPathSegment,error) {
	// current '['
	p.pos++; p.skip()
	if p.peek()==']'{p.pos++; seg:=jqPathSegment{kind:"iter"}; if p.peek()=='?' {seg.optional=true;p.pos++}; return seg,nil}
	// string key ["foo"]
	if p.peek()=='"'{
		sn,err:=p.parseStringLiteral(); if err!=nil{return jqPathSegment{},err}
