			if len(sNode.parts)==1{ if str,ok:=sNode.parts[0].(string);ok{key=str} } else {
				seg:=jqPathSegment{kind:"exprindex",expr:sn}; p.skip(); if p.peek()!=']'{return seg,p.errHere()}; p.pos++; if p.peek()=='?' {seg.optional=true;p.pos++}; return seg,nil
