	for i:=save;i<len(p.s);i++{
		ch:=p.s[i]
		if quote!=0{if ch==quote{quote=0}; continue}
		if ch=='"'{quote=ch;continue}
		if ch=='['||ch=='('||ch=='{'{depth++}
		if ch==']'&&depth==0{closePos=i;break}
		if ch==']'||ch==')'||ch=='}'{depth--}
		if ch==':'&&depth==0&&colonPos<0{colonPos=i}
	}
	if closePos<0{return jqPathSegment{},p.errHere()}
	if colonPos>=0{
		// slice [start:end]
		content:=p.s[save:closePos]
		parts:=splitColon(content)
		seg:=jqPathSegment{kind:"slice"}
		parseNum:=func(s string)(*int,error){s=strTrim(s); if s==""{return nil,nil}; v,err:=strconv.Atoi(s); if err!=nil{
			// Could be expression for start/end in jq slices? Standard jq slice bounds are expressions - unsupported here
			return nil,p.errHere()
		}; return &v,nil}
		if len(parts)!=2{return seg,p.errHere()}
		var err error; seg.startVal,err=parseNum(parts[0]); if err!=nil{return seg,err}; seg.endVal,err=parseNum(parts[1]); if err!=nil{return seg,err}
		p.pos=closePos+1; if p.peek()=='?' {seg.optional=true;p.pos++}; return seg,nil
	}
	// expression index
	expr,err:=p.parsePipe(); if err!=nil{return jqPathSegment{},err}
	p.skip(); if p.peek()!=']'{return jqPathSegment{},p.errHere()}; p.pos++
	// If expr is a literal number, convert to index segment for simpler semantics (negative via unary)
	seg:=jqPathSegment{kind:"exprindex",expr:expr}
	if lit,ok:=expr.(*jqLiteralNode);ok{
		if iv,ok:=lit.v.(int);ok{seg=jqPathSegment{kind:"index",index:iv}}
	}
	if un,ok:=expr.(*jqUnaryMinusNode);ok{
		if lit,ok:=un.node.(*jqLiteralNode);ok{ if iv,ok:=lit.v.(int);ok{seg=jqPathSegment{kind:"index",index:-iv}} }
	}
	if p.peek()=='?' {seg.optional=true;p.pos++}
	return seg,nil
}
func splitColon(s string) []string {
	// no quotes expected in our caller
	out:=[]string{}; last:=0
	for i:=0;i<len(s);i++{if s[i]==':'{out=append(out,s[last:i]);last=i+1}}
	out=append(out,s[last:]);return out
}
func strTrim(s string) string { // tiny trim spaces
	for len(s)>0&&(s[0]==' '||s[0]=='\t'||s[0]=='\n'){s=s[1:]}; for len(s)>0&&(s[len(s)-1]==' '||s[len(s)-1]=='\t'||s[len(s)-1]=='\n'){s=s[:len(s)-1]}; return s
}
GO"}

