type jqCallNode struct{name string; args []jqNode}
func (n *jqCallNode) eval(c *jqCtx,in interface{}) ([]interface{},error){
	// user-defined function?
	key:=fmt.Sprintf("%s/%d",n.name,len(n.args))
	if def,ok:=c.funcs[key]; ok {
		nc:=c.clone()
		// Arguments are filters; a param either $name (value) or name (filter)
		for i,param:=range def.params {
			if strings.HasPrefix(param,"$") {
				vals,err:=n.args[i].eval(c,in); if err!=nil{return nil,err}
				// bind to first? In jq, $param can produce multiple via body evaluation per value - simplify single/multiple by evaluating body per combination is complex.
				// For common cases pick vals as a stream via a pseudo variable holding first, but also store a filter closure in a special map handled below.
				if len(vals)>0{nc.vars[param]=vals[0]}else{nc.vars[param]=nil}
				// store filter for possible call as param name
				nc.funcs[fmt.Sprintf("%s/0",strings.TrimPrefix(param,"$"))]=&jqFuncDef{body:&jqLiteralNode{v:vals}} // not perfect
			} else {
				// filter parameter: register a zero-arg function that eval's arg with caller context/input at call time?
				// Implement via closure node type
				nc.funcs[fmt.Sprintf("%s/0",param)]=&jqFuncDef{body:&jqClosureNode{node:n.args[i],ctx:c}}
			}
		}
		return def.body.eval(nc,in)
	}
	// Function variables for closure literals stored as []interface{}
	if def,ok:=c.funcs[fmt.Sprintf("%s/0",n.name)]; ok && len(n.args)==0 {
		if lit,ok:=def.body.(*jqLiteralNode);ok{
			if arr,ok:=lit.v.([]interface{});ok{return arr,nil}
		}
	}
	// format strings @xxx can be called as filters
	return jqCallBuiltin(c,n.name,n.args,in)
}
type jqClosureNode struct{node jqNode; ctx *jqCtx}
func (n *jqClosureNode) eval(c *jqCtx,in interface{}) ([]interface{},error){
	// When a filter parameter is invoked, its input should be the call-site input (in), not definition input,
	// but variables from definition context. Merge ctx vars (caller at def) with current funcs
	nc:=n.ctx.clone(); nc.funcs=c.funcs
	return n.node.eval(nc,in)
}
func jqEnvMap() map[string]interface{} {
	m:=map[string]interface{}{}
	for _,e:=range os.Environ(){k,v,_:=strings.Cut(e,"="); m[k]=v}
	return m
}

func jqCallBuiltin(c *jqCtx, name string, argNodes []jqNode, in interface{}) ([]interface{},error) {
	// Helpers to eval args as filters against in
	evalArg := func(i int, input interface{}) ([]interface{},error){ return argNodes[i].eval(c,input) }
	evalArg1 := func(i int, input interface{}) (interface{},error){ vals,err:=evalArg(i,input); if err!=nil{return nil,err}; if len(vals)==0{return nil,nil}; return vals[0],nil }
	needArgs := func(n int) error { if len(argNodes)!=n{ return fmt.Errorf("function not defined: %s/%d",name,len(argNodes)) }; return nil }
