	case "length","utf8bytelength":
		if err:=needArgs(0);err!=nil{return nil,err}
		if name=="utf8bytelength"{
			if s,ok:=in.(string);ok{return []interface{}{len(s)},nil}; return nil,fmt.Errorf("%s cannot be applied to: %s",name,jqPreview(in))
		}
		switch v:=in.(type){
		case nil: return []interface{}{0},nil
		case string: return []interface{}{utf8.RuneCountInString(v)},nil
		case []interface{}: return []interface{}{len(v)},nil
		case map[string]interface{}: return []interface{}{len(v)},nil
		default:
			if isNum(in){ f:=numFloat(in); if f<0{f=-f}; if numIsInt(in){return []interface{}{int(f)},nil}; return []interface{}{f},nil }
			return nil,fmt.Errorf("%s cannot be applied to: %s",name,jqPreview(in))
		}
	case "keys":
		if err:=needArgs(0);err!=nil{return nil,err}
		switch v:=in.(type){
		case map[string]interface{}: ks:=sortedKeys(v); out:=make([]interface{},len(ks)); for i,k:=range ks{out[i]=k}; return []interface{}{out},nil
		case []interface{}: out:=make([]interface{},len(v)); for i:=range v{out[i]=i}; return []interface{}{out},nil
		default: return nil,fmt.Errorf("keys cannot be applied to: %s",jqPreview(in))
		}
	case "keys_unsorted":
		// same as keys in practice (map order undefined) - use keys logic but sorted for determinism
		return jqCallBuiltin(c,"keys",argNodes,in)
	case "type": if err:=needArgs(0);err!=nil{return nil,err}; return []interface{}{jqType(in)},nil
	case "tostring": return []interface{}{jqToString(in)},nil
	case "tojson": return []interface{}{jqJSON(in)},nil
	case "fromjson": s:=toStringJQ(in); var v interface{}; dec:=jsonDecoder(s); if err:=dec.Decode(&v);err!=nil{return nil,err}; return []interface{}{jqNormalize(v)},nil
	case "tonumber":
		if isNum(in){return []interface{}{in},nil}
