		return nil,fmt.Errorf("%s cannot be applied to: %s",name,jqPreview(in))
	case "empty": return []interface{}{},nil
	case "not": return []interface{}{!jqTruthy(in)},nil
	case "values": if in!=nil{return []interface{}{in},nil}; return []interface{}{},nil
	case "nulls": if in==nil{return []interface{}{in},nil}; return []interface{}{},nil
	case "booleans": if _,ok:=in.(bool);ok{return []interface{}{in},nil}; return []interface{}{},nil
	case "numbers": if isNum(in){return []interface{}{in},nil}; return []interface{}{},nil
	case "strings": if _,ok:=in.(string);ok{return []interface{}{in},nil}; return []interface{}{},nil
	case "arrays": if _,ok:=in.([]interface{});ok{return []interface{}{in},nil}; return []interface{}{},nil
	case "objects": if _,ok:=in.(map[string]interface{});ok{return []interface{}{in},nil}; return []interface{}{},nil
	case "scalars": switch in.(type){case []interface{},map[string]interface{}:return []interface{}{},nil; default:return []interface{}{in},nil}
	case "iterables": switch in.(type){case []interface{},map[string]interface{}:return []interface{}{in},nil; default:return []interface{}{},nil}
	case "normals": 
		// gojq: numbers that are not NaN/Inf, otherwise like scalars? Simplify: return input if not NaN/Inf float
		if f,ok:=in.(float64);ok&&(math.IsNaN(f)||math.IsInf(f,0)){return []interface{}{},nil}; return []interface{}{in},nil
	case "env": return []interface{}{jqEnvMap()},nil
	case "input","inputs": return nil, fmt.Errorf("%s not implemented",name)
	case "splits","split":
		// split with regex/string depending name
		if len(argNodes)!=1{return nil,fmt.Errorf("function not defined: %s/%d",name,len(argNodes))}
		sepVal,err:=evalArg1(0,in); if err!=nil{return nil,err}
		s,ok:=in.(string); if !ok{return nil,fmt.Errorf("%s cannot be applied to: %s",name,jqPreview(in))}
		sep:=toStringJQ(sepVal)
		var parts []string
		if name=="splits"{
			re,err:=regexp.Compile(sep); if err!=nil{return nil,err}; parts=re.Split(s,-1)
		} else {
			if len(argNodes)==1 && false {}
			parts=strings.Split(s,sep)
		}
		out:=make([]interface{},len(parts)); for i,p:=range parts{out[i]=p}; return []interface{}{out},nil
	case "join":
		if len(argNodes)!=1{return nil,fmt.Errorf("function not defined: %s/%d",name,len(argNodes))}
		sepVal,err:=evalArg1(0,in); if err!=nil{return nil,err}
		arr,ok:=in.([]interface{}); if !ok{return nil,fmt.Errorf("join cannot be applied to: %s",jqPreview(in))}
		sep:=toStringJQ(sepVal); parts:=make([]string,len(arr))
		for i,el:=range arr{
			switch v:=el.(type){case string:parts[i]=v;case nil:parts[i]="";case bool:parts[i]=strconv.FormatBool(v);default:
				if isNum(el){parts[i]=jqNumberString(el)}else{return nil,fmt.Errorf("join cannot be applied to an array including: %s",jqPreview(el))}
			}
		}
		return []interface{}{strings.Join(parts,sep)},nil
	}
	// Large switch continues in jqCallBuiltin2
	return jqCallBuiltin2(c,name,argNodes,in,evalArg,evalArg1)
}
func toStringJQ(v interface{}) string { if s,ok:=v.(string);ok{return s}; return jqToString(v) }
func jqNumberString(v interface{}) string { if iv,ok:=v.(int);ok{return strconv.Itoa(iv)}; f:=numFloat(v); return strconv.FormatFloat(f,'g',-1,64) }
