	}
	return nil,fmt.Errorf("function not defined: %s",name)
}

func jqControlFuncs(c *jqCtx,name string,argNodes []jqNode,in interface{}) ([]interface{},error){
	switch name{
	case "recurse","recurse_down":
		if len(argNodes)==0{ var out []interface{}; collectJQRecursive(in,&out); return out,nil }
		// recurse(f): repeatedly apply f until empty, emitting each input including original
		var out []interface{}; queue:=[]interface{}{in}; seen:=0
		for len(queue)>0{ cur:=queue[0]; queue=queue[1:]; out=append(out,cur); seen++; if seen>10000{break}; nxt,err:=argNodes[0].eval(c,cur); if err!=nil{return nil,err}; queue=append(queue,nxt...) }
		return out,nil
	case "walk":
		if len(argNodes)!=1{return nil,fmt.Errorf("function not defined: walk/%d",len(argNodes))}
		walked,err:=jqWalk(c,argNodes[0],in); if err!=nil{return nil,err}; return []interface{}{walked},nil
	case "until":
		if len(argNodes)!=2{return nil,fmt.Errorf("function not defined: until/%d",len(argNodes))}
		cur:=in
		for i:=0;i<100000;i++{ cond,err:=argNodes[0].eval(c,cur); if err!=nil{return nil,err}; if len(cond)>0&&jqTruthy(cond[0]){return []interface{}{cur},nil}; nxt,err:=argNodes[1].eval(c,cur); if err!=nil{return nil,err}; if len(nxt)==0{return []interface{}{cur},nil}; cur=nxt[0] }
		return []interface{}{cur},nil
	case "while","repeat":
		// Very approximate and guard against infinite
		return nil,fmt.Errorf("function not defined: %s/%d",name,len(argNodes))
	case "foreach","reduce":
		// These are parsed as function calls here but jq syntax is: reduce TERM as $var (init; update), foreach TERM as $var (init; update; extract)
