		return nil,fmt.Errorf("function not defined: %s/%d",name,len(argNodes))
	}
	return nil,fmt.Errorf("function not defined: %s",name)
}
func jqWalk(c *jqCtx, f jqNode, v interface{}) (interface{},error){
	switch x:=v.(type){
	case map[string]interface{}:
		m:=make(map[string]interface{}); for k,val:=range x{ w,err:=jqWalk(c,f,val); if err!=nil{return nil,err}; m[k]=w }; v=m
	case []interface{}:
		a:=make([]interface{},len(x)); for i,el:=range x{ w,err:=jqWalk(c,f,el); if err!=nil{return nil,err}; a[i]=w }; v=a
	}
	vals,err:=f.eval(c,v); if err!=nil{return nil,err}; if len(vals)==0{return v,nil}; return vals[0],nil
}
func jqCombinations(c *jqCtx,argNodes []jqNode,in interface{}) ([]interface{},error){
	var sources [][]interface{}
	if len(argNodes)>0{
		for _,an:=range argNodes{ vals,err:=an.eval(c,in); if err!=nil{return nil,err}; if len(vals)>0{ if arr,ok:=vals[0].([]interface{});ok{sources=append(sources,arr)} } }
	} else {
		arr,ok:=in.([]interface{}); if !ok{return nil,fmt.Errorf("combinations cannot be applied to: %s",jqPreview(in))}
		for _,el:=range arr{ if sub,ok:=el.([]interface{});ok{sources=append(sources,sub)}else{sources=append(sources,[]interface{}{el})} }
	}
	results:=[][]interface{}{{}}
	for _,src:=range sources{ var nr [][]interface{}; for _,base:=range results{ for _,el:=range src{nr=append(nr,append(append([]interface{}{},base...),el))} }; results=nr }
	out:=make([]interface{},len(results)); for i,r:=range results{out[i]=r}; return out,nil
}

