func jqFormat(name string, in interface{}) (string,error) {
	switch name{
	case "@text": return jqToString(in),nil
	case "@json": return jqJSON(in),nil
	case "@csv","@tsv":
		arr,ok:=in.([]interface{}); if !ok{return "",fmt.Errorf("%s cannot format: %s",name,jqPreview(in))}
		delim:=','; if name=="@tsv"{delim='\t'}
		parts:=make([]string,len(arr))
		for i,el:=range arr{
			switch v:=el.(type){case nil:parts[i]="";case string:parts[i]=v;case bool:parts[i]=strconv.FormatBool(v);default: if isNum(el){parts[i]=jqNumberString(el)}else{return "",fmt.Errorf("%s cannot format: %s",name,jqPreview(el))}}
		}
		if name=="@csv"{
			var sb strings.Builder; w:=csv.NewWriter(&sb); _=w.Write(parts); w.Flush(); return strings.TrimSuffix(strings.TrimSuffix(sb.String(),"\n"),"\r"),nil
		}
		// tsv escapes
		for i,p:=range parts{parts[i]=strings.NewReplacer("\t","\\t","\n","\\n","\r","\\r","\\","\\\\").Replace(p)}
		_ = delim
		return strings.Join(parts,"\t"),nil
	case "@html": return html.EscapeString(jqToString(in)),nil
	case "@uri": return url.QueryEscape(jqToString(in)),nil
	case "@sh":
		switch v:=in.(type){
		case nil:return "null",nil
		case string:return shellQuoteStr(v),nil
		case []interface{}: parts:=make([]string,len(v)); for i,el:=range v{parts[i]=shellQuoteStr(jqToString(el))}; return strings.Join(parts," "),nil
		default:return jqToString(in),nil
		}
	case "@base64": return base64.StdEncoding.EncodeToString([]byte(jqToString(in))),nil
	case "@base64d": b,err:=base64.StdEncoding.DecodeString(jqToString(in)); if err!=nil{return "",err}; return string(b),nil
	case "@base32","@base64d2": return "",fmt.Errorf("unknown format: %s",name)
	}
	return "",fmt.Errorf("unknown format: %s",name)
}

func jqSortFamily(c *jqCtx, name string, argNodes []jqNode, in interface{}) ([]interface{},error){
	arr,ok:=in.([]interface{})
	if !ok{
		if name=="min"||name=="max"||strings.Contains(name,"_by")||name=="sort"||name=="unique"||name=="group_by" {
			// gojq reports `<func> cannot be applied to: <preview>` for some, sort_by reports cannot be applied?
			return nil,fmt.Errorf("%s cannot be applied to: %s",name,jqPreview(in))
		}
		return nil,fmt.Errorf("%s cannot be applied to: %s",name,jqPreview(in))
	}
	keyOf := func(el interface{}) (interface{},error){
		if len(argNodes)==0{return el,nil}
		if len(argNodes)==1{ vals,err:=argNodes[0].eval(c,el); if err!=nil{return nil,err}; if len(vals)==0{return nil,nil}; if len(vals)>1{
			// jq sort_by with multiple keys uses array of outputs as key
			return vals,nil
		}; return vals[0],nil }
		// multiple key expressions (sort_by(a;b)) key is array
		keys:=make([]interface{},len(argNodes)); for i,an:=range argNodes{vals,err:=an.eval(c,el); if err!=nil{return nil,err}; if len(vals)>0{keys[i]=vals[0]}}
		return keys,nil
	}
	type item struct{el,key interface{}}
	items:=make([]item,len(arr))
	for i,el:=range arr{ k,err:=keyOf(el); if err!=nil{return nil,err}; items[i]=item{el,k} }
	switch name{
	case "sort","sort_by":
		sort.SliceStable(items,func(i,j int)bool{return jqCompare(items[i].key,items[j].key)<0})
		out:=make([]interface{},len(items)); for i,it:=range items{out[i]=it.el}; return []interface{}{out},nil
	case "group_by":
		sort.SliceStable(items,func(i,j int)bool{return jqCompare(items[i].key,items[j].key)<0})
		var groups []interface{}; var curKey interface{}; var cur []interface{}
		for _,it:=range items{ if cur==nil||jqCompare(it.key,curKey)!=0{ if cur!=nil{groups=append(groups,cur)}; curKey=it.key; cur=[]interface{}{it.el} }else{cur=append(cur,it.el)} }
		if cur!=nil{groups=append(groups,cur)}; if groups==nil{groups=[]interface{}{}}; return []interface{}{groups},nil
	case "unique","unique_by":
		sort.SliceStable(items,func(i,j int)bool{return jqCompare(items[i].key,items[j].key)<0})
		var out []interface{}; var lastKey interface{}; first:=true
		for _,it:=range items{ if first||jqCompare(it.key,lastKey)!=0{out=append(out,it.el); lastKey=it.key; first=false} }
		if out==nil{out=[]interface{}{}}; return []interface{}{out},nil
	case "min","min_by":
		if len(items)==0{return []interface{}{nil},nil}; best:=items[0]; for _,it:=range items[1:]{if jqCompare(it.key,best.key)<0{best=it}}; return []interface{}{best.el},nil
	case "max","max_by":
		if len(items)==0{return []interface{}{nil},nil}; best:=items[0]; for _,it:=range items[1:]{if jqCompare(it.key,best.key)>0{best=it}}; return []interface{}{best.el},nil
	}
	return nil,fmt.Errorf("function not defined: %s/%d",name,len(argNodes))
}

func jqAnyAll(c *jqCtx, name string, argNodes []jqNode, in interface{}) ([]interface{},error){
	// any, any(cond), any(gen;cond) ; all similarly. Simplify common forms.
	var vals []interface{}
	if len(argNodes)==0{
		arr,ok:=in.([]interface{}); if !ok{return nil,fmt.Errorf("%s cannot be applied to: %s",name,jqPreview(in))}; vals=arr
	} else if len(argNodes)==1{
		// if input is array, apply cond to each; else evaluate stream generated by arg on input
		if arr,ok:=in.([]interface{});ok{
			for _,el:=range arr{ r,err:=argNodes[0].eval(c,el); if err!=nil{return nil,err}; vals=append(vals,r...) }
		} else {
			r,err:=argNodes[0].eval(c,in); if err!=nil{return nil,err}; vals=r
		}
	} else if len(argNodes)==2{
		gen,err:=argNodes[0].eval(c,in); if err!=nil{return nil,err}
		for _,g:=range gen{ r,err:=argNodes[1].eval(c,g); if err!=nil{return nil,err}; vals=append(vals,r...) }
