func jqRegexFuncs(c *jqCtx,name string,argNodes []jqNode,in interface{}) ([]interface{},error){
	// test(re;flags?), match, scan, capture, sub, gsub, splits(re;flags?)
	if len(argNodes)<1{return nil,fmt.Errorf("function not defined: %s/%d",name,len(argNodes))}
	s,ok:=in.(string); if !ok{return nil,fmt.Errorf("%s cannot be applied to: %s",name,jqPreview(in))}
	getArg:=func(i int)(string,error){ vals,err:=argNodes[i].eval(c,in); if err!=nil{return "",err}; if len(vals)==0{return "",nil}; return jqToString(vals[0]),nil }
	pat,err:=getArg(0); if err!=nil{return nil,err}
	flags:=""
	// Flags may be in arg index depending function: test(pat;flags), sub(pat;repl;flags)
	repl:=""
	if name=="sub"||name=="gsub"{
		if len(argNodes)>=2{repl,err=getArg(1); if err!=nil{return nil,err}}
		if len(argNodes)>=3{flags,err=getArg(2); if err!=nil{return nil,err}}
	} else if len(argNodes)>=2 { flags,err=getArg(1); if err!=nil{return nil,err} }
	// Convert jq flags gims to Go regexp flags prefix, ignore g
	goFlags:=""
	if strings.Contains(flags,"i"){goFlags+="i"}; if strings.Contains(flags,"m"){goFlags+="m"}; if strings.Contains(flags,"s"){goFlags+="s"}
	pattern:=pat; if goFlags!=""{pattern="(?"+goFlags+")"+pat}
	re,err:=regexp.Compile(pattern); if err!=nil{return nil,err}
	switch name{
	case "test": return []interface{}{re.MatchString(s)},nil
	case "splits": return []interface{}{func()[]interface{}{parts:=re.Split(s,-1); out:=make([]interface{},len(parts)); for i,p:=range parts{out[i]=p}; return out}()},nil
	case "scan":
		matches:=re.FindAllStringSubmatch(s,-1); var out []interface{}
		for _,m:=range matches{ if len(m)==1{out=append(out,m[0])}else{ arr:=make([]interface{},len(m)-1); for i:=1;i<len(m);i++{arr[i-1]=m[i]}; out=append(out,arr)} }
		return out,nil
	case "match":
		loc:=re.FindStringSubmatchIndex(s); if loc==nil{return []interface{}{},nil}
		m:=re.FindStringSubmatch(s)
		captures:=[]interface{}{}
		names:=re.SubexpNames()
		for i:=1;i<len(m);i++{ off:=loc[2*i]; capObj:=map[string]interface{}{"offset":off,"length":0,"string":nil,"name":nil}; if off>=0{capObj["length"]=(loc[2*i+1]-off); capObj["string"]=m[i]}; if i<len(names)&&names[i]!=""{capObj["name"]=names[i]}; captures=append(captures,capObj)}
		return []interface{}{map[string]interface{}{"offset":loc[0],"length":loc[1]-loc[0],"string":m[0],"captures":captures}},nil
	case "capture":
		m:=re.FindStringSubmatch(s); if m==nil{return []interface{}{},nil}
		out:=map[string]interface{}{}; names:=re.SubexpNames(); for i:=1;i<len(m);i++{if names[i]!=""{out[names[i]]=m[i]}}
		return []interface{}{out},nil
	case "sub": return []interface{}{replaceFirstMatch(re,s,repl)},nil
	case "gsub": return []interface{}{re.ReplaceAllString(s,expandJQReplacement(re,s,repl,true))},nil
	}
	return nil,fmt.Errorf("function not defined: %s",name)
}
func replaceFirstMatch(re *regexp.Regexp,s,repl string) string {
	loc:=re.FindStringSubmatchIndex(s); if loc==nil{return s}
	// Expand $name / $1 in replacement like gojq ($ followed by name/number, $$ => $?) Use regexp Expand
	var buf strings.Builder
	// Convert jq replacement interpolation? plain here, but $1 etc: use Expand for matched portion
	result:=re.ExpandString([]byte{},repl,s,re.FindStringSubmatchIndex(s))
	buf.WriteString(s[:loc[0]]); buf.Write(result); buf.WriteString(s[loc[1]:]); return buf.String()
