	}
	switch k:=seg.(type){
	case string: if m,ok:=in.(map[string]interface{});ok{cp:=make(map[string]interface{});for kk,v:=range m{cp[kk]=v};cp[k]=jqDeletePath(cp[k],path[1:]);return cp}
