func jqIndexFuncs(c *jqCtx,name string,argNodes []jqNode,in interface{},evalArg1 func(int,interface{})(interface{},error)) ([]interface{},error){
	if len(argNodes)!=1{return nil,fmt.Errorf("function not defined: %s/%d",name,len(argNodes))}
	needle,err:=evalArg1(0,in); if err!=nil{return nil,err}
	switch name{
