			resolved,_:=resolveCueRefs(v,scope,v)
			if arr,ok:=resolved.([]interface{});ok{ if idx<0||idx>=int64(len(arr)){return nil,fmt.Errorf("index out of range")}; v=arr[idx] } else { return nil,fmt.Errorf("cannot index %T",resolved) }
			continue
		}
		if p.peek()=='.'{
			// field selection on a reference or value
			save:=p.pos; p.pos++; name:=p.parseIdentCue(); if name==""{p.pos=save;break}
			if ref,ok:=v.(cueRef);ok{ ref.path=append(ref.path,name); v=ref; continue }
