			if m,ok:=resolved.(map[string]interface{});ok{ if fv,ok:=m[name];ok{v=fv;continue}; return nil,fmt.Errorf("field %q not found",name) }
			return nil,fmt.Errorf("cannot access field %s",name)
		}
		break
	}
	return v,nil
}
func (p *cueParser) parsePrimary(scope *cueScope) (interface{},error) {
	p.skipSpaceAndComments()
	if p.pos>=len(p.s){return nil,p.errExpected("operand")}
	c:=p.peek()
	switch {
	case c=='{':
		p.pos++; child:=&cueScope{fields:map[string]interface{}{},parent:scope}
		return p.parseStructFields(child,true)
	case c=='[':
		return p.parseList(scope)
	case c=='(':
		p.pos++; v,err:=p.parseExpr(scope); if err!=nil{return nil,err}; p.skipSpaceAndComments(); if p.peek()!=')'{return nil,p.errExpected("')'")}; p.pos++; return v,nil
