		start:=p.pos
		// bottom token
		if strings.HasPrefix(p.s[p.pos:],"_|_"){p.pos+=3; return nil,fmt.Errorf("explicit error (_|_ literal) in source")}
		// include leading #/_
		if p.peek()=='#'||p.peek()=='_'{p.pos++}
		idRest:=p.parseIdentCue()
		id:=p.s[start:p.pos]
		_ = idRest
		switch id{
		case "true": return true,nil
		case "false": return false,nil
		case "null": return nil,nil
		case "_": return nil,fmt.Errorf("incomplete value _")
		case "string","int","float","bool","number","bytes":
			return nil,fmt.Errorf("incomplete value %s",id)
		}
