}
func (p *cueParser) parseList(scope *cueScope) (interface{},error){
	p.pos++ // [
	var out []interface{}
	for{
		p.skipSpaceAndComments()
		if p.pos>=len(p.s){return nil,fmt.Errorf("expected ']', found 'EOF'")}
		if p.peek()==']'{p.pos++; break}
		v,err:=p.parseExpr(scope); if err!=nil{return nil,err}
		out=append(out,v)
		p.skipSpaceAndComments()
		if p.peek()==','{p.pos++;continue}
		if p.peek()==']'{p.pos++;break}
		// CUE allows newline separators inside []? Commas typically required, skipSpace already consumed - treat as separator
