}
func (p *cueParser) parseNumber() (interface{},error){
	start:=p.pos
	for p.pos<len(p.s)&& (unicode.IsDigit(rune(p.s[p.pos]))|| strings.ContainsRune("._eExXobKMGT",rune(p.s[p.pos]))){p.pos++}
