		if len(lines)>0{
			indent:=lines[len(lines)-1]; _=indent
			for i:=range lines{lines[i]=strings.TrimPrefix(lines[i],"\t")}
			content=strings.Join(lines[:len(lines)-1],"\n")+"\n"
			if strings.HasSuffix(content,"\n")&&len(lines)==1{/* keep */}
		}
		return content,nil
	}
