func (p *cueParser) parseBytesLiteral() (interface{},error){
	// '...' bytes
	p.pos++; start:=p.pos
	for p.pos<len(p.s)&&p.s[p.pos]!='\''{ if p.s[p.pos]=='\\'{p.pos++}; p.pos++ }
	if p.pos>=len(p.s){return nil,fmt.Errorf("unterminated bytes")}
	content:=p.s[start:p.pos]; p.pos++; return []byte(content),nil
