func resolveCueRefs(v interface{}, scope *cueScope, root interface{}) (interface{},error){
	switch x:=v.(type){
	case cueRef:
		// find first segment in scope chain
		if len(x.path)==0{return nil,nil}
		var cur interface{}; found:=false
		for sc:=scope; sc!=nil; sc=sc.parent{
			if val,ok:=sc.fields[x.path[0]]; ok{cur=val; found=true; break}
		}
		if !found{
			// try root map
			if rm,ok:=root.(map[string]interface{});ok{ if val,ok:=rm[x.path[0]];ok{cur=val;found=true} }
		}
		if !found{ return nil,fmt.Errorf("reference %q not found",x.path[0]) }
		// prevent self reference loops when field resolves to itself (same ref)
		cur2,err:=resolveCueRefs(cur,scope,root); if err!=nil{
			// reference errors in CUE are prefixed with field context by caller? Our parse wrapping at root does not add field - original error: "a: reference \"b\" not found" for field a referencing b.
			// That prefix is added when resolving struct fields in resolveStruct below - here just return err.
			return nil,err
		}
		cur=cur2
		for _,seg:=range x.path[1:]{
			if m,ok:=cur.(map[string]interface{});ok{ fv,ok:=m[seg]; if !ok{return nil,fmt.Errorf("field %q not found",seg)}; cur=fv } else {return nil,fmt.Errorf("cannot access field %s",seg)}
		}
		return cur,nil
	case map[string]interface{}:
		// This map is a struct scope - create child scope based on its fields for resolution of nested refs
		child:=&cueScope{fields:x,parent:scope}
		out:=make(map[string]interface{},len(x))
		for k,val:=range x{
			rv,err:=resolveCueRefs(val,child,root)
			if err!=nil{
				// Prefix with field name if not already
				msg:=err.Error()
				if strings.Contains(msg,"reference") && !strings.HasPrefix(msg,k+":") {
					return nil,fmt.Errorf("%s: %s",k,msg)
				}
				return nil,err
			}
			out[k]=rv
		}
		return out,nil
	case []interface{}:
		out:=make([]interface{},len(x)); for i,el:=range x{rv,err:=resolveCueRefs(el,scope,root); if err!=nil{return nil,err}; out[i]=rv}; return out,nil
	default:
		return v,nil
	}
}

// ToCUE formatting
func toCUEString(in interface{}) (string,error){
	v:=jqNormalizeForCUE(in)
	return formatCUEValue(v,0),nil
}
func jqNormalizeForCUE(v interface{}) interface{} {
	// Reuse generic normalization via JSON-ish reflection in jqNormalize (same package)
	return jqNormalize(v)
}
func formatCUEValue(v interface{}, indent int) string {
	switch x:=v.(type){
	case nil: return "null"
	case bool: return strconv.FormatBool(x)
	case int: return strconv.Itoa(x)
	case int64: return strconv.FormatInt(x,10)
	case float64: return strconv.FormatFloat(x,'g',-1,64)
	case string:
		if strings.Contains(x,"\n"){
			lines:=strings.Split(x,"\n")
			ind:=strings.Repeat("\t",indent+1)
			var b strings.Builder; b.WriteString("\"\"\"\n")
			for _,l:=range lines{b.WriteString(ind+l+"\n")}
			b.WriteString(ind+"\"\"\""); return b.String()
		}
		return strconv.Quote(x)
	case []interface{}:
		if len(x)==0{return "[]"}
		parts:=make([]string,len(x))
		isComplex:=false
		for i,el:=range x{parts[i]=formatCUEValue(el,indent); if _,ok:=el.(map[string]interface{});ok{isComplex=true} }
		if isComplex{
			// CUE formatter puts elements on new lines? Observed [{...}, {...}] with structs expanded in place
			return "["+strings.Join(parts,", ")+"]"
		}
		return "["+strings.Join(parts,", ")+"]"
	case map[string]interface{}:
		if len(x)==0{return "{}"}
		keys:=sortedKeys(x)
		var b strings.Builder; b.WriteString("{\n")
		ind:=strings.Repeat("\t",indent+1)
		for _,k:=range keys{
			label:=k
			if !isCUEIdent(k){label=strconv.Quote(k)}
			valStr:=formatCUEValue(x[k],indent+1)
			// For list of structs as field value, original format: a: [{\n\t\tx: 1\n\t}] -> inner struct indent should be indent+1 for its fields (our format call above used indent+1 which gives fields at +2 from current? Check observed: field a at indent1, its struct x at indent2 - formatCUE for field value called with indent+1 yields struct fields at indent+2 correct)
			b.WriteString(ind+label+": "+valStr+"\n")
		}
		b.WriteString(strings.Repeat("\t",indent)+"}")
		return b.String()
	case []byte:
		return "'" + string(x) + "'"
	default:
		b,_:=json.Marshal(x); return string(b)
	}
}
func isCUEIdent(s string) bool {
	if s==""{return false}
	for i,r:=range s{
		if i==0{ if !(unicode.IsLetter(r)||r=='_'||r=='#'){return false} } else if !(unicode.IsLetter(r)||unicode.IsDigit(r)||r=='_'){return false}
	}
	return true
}

func ParseCUEExported(s string) (interface{}, error) { return parseCUE(s) }
