{"command":"cat > funcs/ejson_decrypt.go <<'GO'
package funcs

import (
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"golang.org/x/crypto/nacl/box"
)
func isValidEJSONPublicKey(pub string) bool {
	b,err:=hex.DecodeString(pub); return err==nil && len(b)==32
}
func decryptEJSON(s string, pub string) (string,error) {
	priv, err := ejsonPrivateKey(pub)
	if err != nil { return "", err }
	var doc interface{}
	dec := json.NewDecoder(strings.NewReader(s)); dec.UseNumber()
	if err:=dec.Decode(&doc); err!=nil{ return "", err }
	out, err := decryptEJSONValue(doc, priv, false)
	if err!=nil{return "",err}
	b,err:=json.Marshal(out); if err!=nil{return "",err}
	return string(b),nil
}
func ejsonPrivateKey(pub string) (*[32]byte,error) {
	var privHex string
	if v:=getenvImpl("EJSON_KEY"); v!="" {
		privHex=v
	} else {
		dir:=os.Getenv("EJSON_KEYDIR"); if dir==""{dir="/opt/ejson/keys"}
		path:=filepath.Join(dir,pub)
		b,err:=os.ReadFile(path)
		if err!=nil{return nil,fmt.Errorf("couldn't read key file (%w)",err)}
		privHex=strings.TrimSpace(string(b))
	}
	b,err:=hex.DecodeString(privHex)
	if err!=nil{return nil,err}
	if len(b)!=32{return nil,fmt.Errorf("invalid private key")}
	var key [32]byte; copy(key[:],b); return &key,nil
}
func decryptEJSONValue(v interface{}, priv *[32]byte, skip bool) (interface{},error) {
	switch x:=v.(type){
	case map[string]interface{}:
		out:=make(map[string]interface{},len(x))
		for k,val:=range x{
			childSkip := strings.HasPrefix(k,"_")
			rv,err:=decryptEJSONValue(val,priv,childSkip); if err!=nil{return nil,err}; out[k]=rv
		}
		return out,nil
	case []interface{}:
		out:=make([]interface{},len(x)); for i,el:=range x{rv,err:=decryptEJSONValue(el,priv,skip); if err!=nil{return nil,err}; out[i]=rv}; return out,nil
	case string:
		if skip{return x,nil}
		return decryptEJSONMessage(x,priv)
	default:
		return v,nil
	}
}
func decryptEJSONMessage(s string, priv *[32]byte) (string,error) {
	if !strings.HasPrefix(s,"EJ[") || !strings.HasSuffix(s,"]"){return "",fmt.Errorf("invalid message format")}
	inner:=s[3:len(s)-1]
	parts:=strings.Split(inner,":")
	if len(parts)!=4 || parts[0]!="1"{return "",fmt.Errorf("invalid message format")}
	pubBytes,err1:=base64.StdEncoding.DecodeString(parts[1])
	nonceBytes,err2:=base64.StdEncoding.DecodeString(parts[2])
	boxBytes,err3:=base64.StdEncoding.DecodeString(parts[3])
	if err1!=nil||err2!=nil||err3!=nil||len(pubBytes)!=32||len(nonceBytes)!=24{return "",fmt.Errorf("invalid message format")}
	var pub [32]byte; copy(pub[:],pubBytes)
	var nonce [24]byte; copy(nonce[:],nonceBytes)
	out,ok:=box.Open(nil,boxBytes,&nonce,&pub,priv)
	if !ok{return "",fmt.Errorf("couldn't decrypt message")}
	return string(out),nil
}
