package funcs

import (
	"fmt"
	"os"
	"reflect"
	"strconv"
	"strings"
	"time"
)

func unixImpl(in interface{}) (time.Time,error) {
	switch v:=in.(type) {
	case float32, float64:
		fv,_:=toFloat64(in)
		return time.Time{}, fmt.Errorf("can not parse floating point number (%f) - use a string instead", fv)
	case string:
		parts:=strings.Split(v,".")
