package gomplate

import (
	"bytes"
	"context"
	"crypto/tls"
	"encoding/json"
	"fmt"
	"io"
	"io/fs"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"time"

	"example.com/gomplate/internal/config"
)

func envOrFile(name string) string {
	if v := os.Getenv(name); v != "" { return v }
	if f := os.Getenv(name + "_FILE"); f != "" {
		if b, err := os.ReadFile(f); err == nil { return strings.TrimSpace(string(b)) }
	}
	return ""
}

type Secret struct {
	Data map[string]interface{} `json:"data"`
}

type vaultClient struct {
	addr string
	token string
	http *http.Client
	loggedIn bool
	mountCache map[string]vaultMount
}
type vaultMount struct {
	path string
	isV2 bool
}
func vaultAddr(finalURL *url.URL) string {
	scheme := "https"
	if finalURL.Scheme == "vault+http" { scheme = "http" }
	if finalURL.Host != "" {
		return scheme + "://" + finalURL.Host
	}
	if v := os.Getenv("VAULT_ADDR"); v != "" { return strings.TrimSuffix(v, "/") }
	return "https://localhost:8200"
}
func newVaultClient(finalURL *url.URL) *vaultClient {
	tr := &http.Transport{TLSClientConfig: &tls.Config{InsecureSkipVerify: os.Getenv("VAULT_SKIP_VERIFY") == "true"}}
	return &vaultClient{addr: vaultAddr(finalURL), http: &http.Client{Timeout: 60 * time.Second, Transport: tr}, mountCache: map[string]vaultMount{}}
}

type vaultResponseError struct {
	Method string
	URL string
	Code int
	Errors []string
	Raw string
}
func (e *vaultResponseError) Error() string {
	s := fmt.Sprintf("Error making API request.\n\nURL: %s %s\nCode: %d. Errors:\n\n", e.Method, e.URL, e.Code)
	for _, msg := range e.Errors { s += "* " + msg + "\n" }
	// Vault api appends raw? When no errors, observed ending after blank line
	return s
}

func (vc *vaultClient) rawRequest(ctx context.Context, method, apipath string, body interface{}) ([]byte, int, error) {
	var rdr io.Reader
	if body != nil { b, _ := json.Marshal(body); rdr = bytes.NewReader(b) }
	urlStr := vc.addr + "/v1/" + strings.TrimPrefix(apipath, "/")
	req, _ := http.NewRequestWithContext(ctx, method, urlStr, rdr)
	req.Header.Set("X-Vault-Request", "true")
	if vc.token != "" { req.Header.Set("X-Vault-Token", vc.token) }
	resp, err := vc.http.Do(req)
	if err != nil { return nil, 0, err }
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	return b, resp.StatusCode, nil
}
func (vc *vaultClient) doSecret(ctx context.Context, method, apipath string, body interface{}) (*Secret, error) {
	b, code, err := vc.rawRequest(ctx, method, apipath, body)
	if err != nil { return nil, err }
	if code == 404 { return nil, nil }
	if code < 200 || code >= 300 {
		return nil, makeVaultResponseError(method, vc.addr+"/v1/"+strings.TrimPrefix(apipath,"/"), code, b)
	}
	// Vault Logical.Read parses into Secret; if b empty return nil
	if len(b) == 0 { return nil, nil }
	sec := &Secret{}
	// First unmarshal into generic with Data map - if data is array, this yields same json error as Vault's parser? Local unmarshal into Secret gives field name Secret.data
	if err := json.Unmarshal(b, sec); err != nil { return nil, err }
	return sec, nil
}
func makeVaultResponseError(method, urlStr string, code int, b []byte) error {
	var parsed struct{ Errors []string `json:"errors"` }
	_ = json.Unmarshal(b, &parsed)
	return &vaultResponseError{Method: method, URL: urlStr, Code: code, Errors: parsed.Errors, Raw: string(b)}
}

func (vc *vaultClient) login(ctx context.Context) error {
	if vc.loggedIn { return nil }
	vc.loggedIn = true
	roleID := envOrFile("VAULT_ROLE_ID"); secretID := envOrFile("VAULT_SECRET_ID")
	mountOr := func(envname, def string) string { if v:=os.Getenv(envname);v!=""{return v}; return def }
	doLogin := func(path string, body map[string]interface{}) error {
		b, code, err := vc.rawRequest(ctx, "POST", path, body)
		if err != nil { return err }
		if code < 200 || code >= 300 { return makeVaultResponseError("POST", vc.addr+"/v1/"+path, code, b) }
		var out struct{ Auth *struct{ ClientToken string `json:"client_token"` } `json:"auth"` }
		if err := json.Unmarshal(b, &out); err != nil { return err }
		if out.Auth == nil || out.Auth.ClientToken == "" { return fmt.Errorf("no token in login response") }
		vc.token = out.Auth.ClientToken; return nil
	}
	if roleID != "" && secretID != "" {
		return doLogin("auth/"+mountOr("VAULT_AUTH_APPROLE_MOUNT","approle")+"/login", map[string]interface{}{"role_id": roleID, "secret_id": secretID})
	}
	if tok := envOrFile("VAULT_AUTH_GITHUB_TOKEN"); tok != "" {
		return doLogin("auth/"+mountOr("VAULT_AUTH_GITHUB_MOUNT","github")+"/login", map[string]interface{}{"token": tok})
	}
	if user := envOrFile("VAULT_AUTH_USERNAME"); user != "" {
		return doLogin("auth/"+mountOr("VAULT_AUTH_USERPASS_MOUNT","userpass")+"/login/"+user, map[string]interface{}{"password": envOrFile("VAULT_AUTH_PASSWORD")})
	}
	if tok := envOrFile("VAULT_TOKEN"); tok != "" { vc.token = tok; return nil }
	if b, err := os.ReadFile(filepath.Join(os.Getenv("HOME"), ".vault-token")); err == nil { vc.token = strings.TrimSpace(string(b)); return nil }
	if os.Getenv("AWS_ACCESS_KEY_ID") != "" || os.Getenv("VAULT_AUTH_AWS_ROLE") != "" {
		return fmt.Errorf("unable to authenticate with vault by any configured method. Last error was: vault aws auth not implemented")
	}
	return fmt.Errorf("unable to authenticate with vault by any configured method. Last error was: failed to retrieve credentials from credential chain: NoCredentialProviders: no valid providers in chain. Deprecated.\n\tFor verbose messaging see aws.Config.CredentialsChainVerboseErrors\n")
}

func (vc *vaultClient) getMountInfo(ctx context.Context, secretPath string) (vaultMount, error) {
	// Determine candidate mount prefix as first segment for cache
	first := strings.SplitN(strings.Trim(secretPath,"/"),"/",2)[0]
	if m, ok := vc.mountCache[first]; ok { return m, nil }
	if err := vc.login(ctx); err != nil {
		return vaultMount{}, fmt.Errorf("vault login failure: %w", err)
	}
	b, code, err := vc.rawRequest(ctx, "GET", "sys/internal/ui/mounts", nil)
	if err != nil { return vaultMount{}, fmt.Errorf("read mount info: %w", err) }
	if code < 200 || code >= 300 {
		return vaultMount{}, fmt.Errorf("read mount info: %w", makeVaultResponseError("GET", vc.addr+"/v1/sys/internal/ui/mounts", code, b))
	}
	var sec Secret
	if err := json.Unmarshal(b, &sec); err != nil {
		return vaultMount{}, fmt.Errorf("parse mount info: %w", err)
	}
	// Find mount in grouped data
	var best *vaultMount
	for _, groupVal := range sec.Data {
		group, ok := groupVal.(map[string]interface{})
		if !ok { continue }
		for mountPath, infoVal := range group {
			info, ok := infoVal.(map[string]interface{})
			if !ok { continue }
			trimmed := strings.Trim(mountPath, "/")
			nameTrim := strings.Trim(secretPath, "/")
			if nameTrim == trimmed || strings.HasPrefix(nameTrim, trimmed+"/") {
				isV2 := false
				if opts, ok := info["options"].(map[string]interface{}); ok {
					if v, ok := opts["version"].(string); ok && v == "2" { isV2 = true }
				}
				m := vaultMount{path: mountPath, isV2: isV2}
				if best == nil || len(m.path) > len(best.path) { mm:=m; best=&mm }
			}
		}
	}
	if best == nil {
		return vaultMount{}, fmt.Errorf("unexpected mount info format: %v", sec.Data)
	}
	vc.mountCache[first] = *best
	return *best, nil
}

func vaultTransformReadPath(name string, mount vaultMount, version string) string {
	rest := strings.Trim(strings.TrimPrefix(strings.Trim(name,"/"), strings.Trim(mount.path,"/")), "/")
	// rest calculation above can be empty for mount itself
	mountPrefix := strings.Trim(mount.path, "/")
	nameTrim := strings.Trim(name, "/")
	if nameTrim == mountPrefix { rest = "" } else { rest = strings.Trim(strings.TrimPrefix(nameTrim, mountPrefix), "/") }
	if !mount.isV2 { return nameTrim }
	if rest == "" { return nameTrim }
	if version == "" { version = "0" }
	return mountPrefix + "/data/" + rest + "?version=" + url.QueryEscape(version)
}
func vaultTransformListPath(name string, mount vaultMount) string {
	mountPrefix := strings.Trim(mount.path, "/")
	nameTrim := strings.Trim(name, "/")
	rest := ""
	if nameTrim != mountPrefix { rest = strings.Trim(strings.TrimPrefix(nameTrim, mountPrefix), "/") }
	if mount.isV2 {
		if rest == "" { return mountPrefix + "/metadata?list=true" }
		return mountPrefix + "/metadata/" + rest + "?list=true"
	}
	if rest == "" { return mountPrefix + "?list=true" }
	return mountPrefix + "/" + rest + "?list=true"
}

func (r *dsRegistry) readVault(ctx context.Context, ds config.DataSource, sp fsSplit, finalURL *url.URL) (*rawResult, error) {
	name := sp.name
	vc := newVaultClient(finalURL)
	statErr := func(err error) error { return fsErr("stat", sp, fmt.Errorf("stat %s: %w", name, err)) }
	mount, err := vc.getMountInfo(ctx, name)
	if err != nil {
		// getMountInfo errors already include read/parse/unexpected or login prefix appropriately?
		// login error returned as "vault login failure: ..." and our getMountInfo currently doesn't wrap it -
		// Original outer is "get mount info: vault login failure: ..."
		msg := err.Error()
		if strings.HasPrefix(msg, "read mount info:") || strings.HasPrefix(msg, "parse mount info:") || strings.HasPrefix(msg, "unexpected mount info format:") || strings.HasPrefix(msg, "vault login failure:") {
			return nil, statErr(fmt.Errorf("get mount info: %w", err))
		}
		return nil, statErr(fmt.Errorf("get mount info: %w", err))
	}
	// dynamic params
	q := finalURL.Query()
