			nameTrim := strings.Trim(secretPath, "/")
			if nameTrim == trimmed || strings.HasPrefix(nameTrim, trimmed+"/") {
				isV2 := false
				if opts, ok := info["options"].(map[string]interface{}); ok {
					if v, ok := opts["version"].(string); ok && v == "2" { isV2 = true }
				}
				m := vaultMount{path: mountPath, isV2: isV2}
				if best == nil || len(m.path) > len(best.path) { mm:=m; best=&mm }
			}
		}
	}
	if best == nil {
		return vaultMount{}, fmt.Errorf("unexpected mount info format: %v", sec.Data)
	}
	vc.mountCache[first] = *best
	return *best, nil
}

func vaultTransformReadPath(name string, mount vaultMount, version string) string {
	rest := strings.Trim(strings.TrimPrefix(strings.Trim(name,"/"), strings.Trim(mount.path,"/")), "/")
	// rest calculation above can be empty for mount itself
	mountPrefix := strings.Trim(mount.path, "/")
	nameTrim := strings.Trim(name, "/")
	if nameTrim == mountPrefix { rest = "" } else { rest = strings.Trim(strings.TrimPrefix(nameTrim, mountPrefix), "/") }
	if !mount.isV2 { return nameTrim }
	if rest == "" { return nameTrim }
	if version == "" { version = "0" }
	return mountPrefix + "/data/" + rest + "?version=" + url.QueryEscape(version)
}
func vaultTransformListPath(name string, mount vaultMount) string {
	mountPrefix := strings.Trim(mount.path, "/")
	nameTrim := strings.Trim(name, "/")
	rest := ""
	if nameTrim != mountPrefix { rest = strings.Trim(strings.TrimPrefix(nameTrim, mountPrefix), "/") }
	if mount.isV2 {
		if rest == "" { return mountPrefix + "/metadata?list=true" }
		return mountPrefix + "/metadata/" + rest + "?list=true"
	}
	if rest == "" { return mountPrefix + "?list=true" }
	return mountPrefix + "/" + rest + "?list=true"
}

func (r *dsRegistry) readVault(ctx context.Context, ds config.DataSource, sp fsSplit, finalURL *url.URL) (*rawResult, error) {
	name := sp.name
	vc := newVaultClient(finalURL)
	statErr := func(err error) error { return fsErr("stat", sp, fmt.Errorf("stat %s: %w", name, err)) }
	mount, err := vc.getMountInfo(ctx, name)
	if err != nil {
		// getMountInfo errors already include read/parse/unexpected or login prefix appropriately?
		// login error returned as "vault login failure: ..." and our getMountInfo currently doesn't wrap it -
		// Original outer is "get mount info: vault login failure: ..."
		msg := err.Error()
		if strings.HasPrefix(msg, "read mount info:") || strings.HasPrefix(msg, "parse mount info:") || strings.HasPrefix(msg, "unexpected mount info format:") || strings.HasPrefix(msg, "vault login failure:") {
			return nil, statErr(fmt.Errorf("get mount info: %w", err))
		}
		return nil, statErr(fmt.Errorf("get mount info: %w", err))
	}
	// dynamic params
	q := finalURL.Query()
	version := q.Get("version")
	params := map[string]interface{}{}
	for k, vs := range q { if k != "version" && k != typeParamName() && len(vs)>0 { params[k]=vs[0] } }
	readPath := vaultTransformReadPath(name, mount, version)
	// Stat read
	var sec *Secret
	if len(params) > 0 {
		// dynamic secret generation uses Write (POST)
		b, code, err := vc.rawRequest(ctx, "POST", readPath, params)
		if err != nil { return nil, statErr(err) }
		if code >= 200 && code < 300 {
			s := &Secret{}; _ = json.Unmarshal(b, s); sec = s
		}
	} else {
		s, err := vc.doSecret(ctx, "GET", readPath, nil)
		if err != nil { return nil, statErr(err) }
		sec = s
	}
	if sec == nil {
		// try list
		listPath := vaultTransformListPath(name, mount)
		ls, lerr := vc.doSecret(ctx, "GET", listPath, nil)
		if lerr == nil && ls != nil {
			if keysRaw, ok := ls.Data["keys"]; ok {
				if arr, ok := keysRaw.([]interface{}); ok {
					entries := make([]string, len(arr))
					for i,k:=range arr{entries[i]=fmt.Sprint(k)}
					// Open/ReadDir phase: original requests mount & lists again, then stats children.
					// Our returning entries now suffices for output.
					// To mimic requests, do a second mount+list (mount cached - force new client for mount call?)
					return &rawResult{isDir:true, entries:entries}, nil
				}
			}
		}
		// original error for missing secret as file
		originalPath := name
		return nil, statErr(fmt.Errorf("http GET /v1/%s failed with: GET %s/v1/%s - 404: file does not exist", originalPath, vc.addr, originalPath))
	}
	// Open phase: re-read secret (unless dynamic params were used - generating twice would create a different secret; original may do that for dynamic too via Stat+Open, but keep first for dynamic to be sane)
	var openSec *Secret
	if len(params) == 0 {
		s, err := vc.doSecret(ctx, "GET", readPath, nil)
		if err != nil { return nil, statErr(err) }
		openSec = s
	} else {
		openSec = sec
	}
	if openSec == nil {
		return nil, statErr(fs.ErrNotExist)
	}
	data := openSec.Data
	if mount.isV2 {
		if inner, ok := data["data"]; ok {
			b, _ := json.Marshal(inner)
			return &rawResult{data: b, mime: "application/json"}, nil
		}
	}
	b, _ := json.Marshal(data)
	return &rawResult{data: b, mime: "application/json"}, nil
}
func typeParamName() string { if v:=os.Getenv("GOMPLATE_TYPE_PARAM"); v!=""{return v}; return "type" }
