		var cancel context.CancelFunc
		if timeout > 0 {
			cctx, cancel = context.WithTimeout(ctx, timeout)
			defer cancel()
		}
		cmdArgs := append([]string{}, pcfg.Args...)
		var stdinData string
		hasStdin := false
		strArgs := make([]string, len(args))
		for i, a := range args {
			strArgs[i] = pluginArgString(a)
		}
		if pcfg.Pipe && len(strArgs) > 0 {
			stdinData = strArgs[len(strArgs)-1]
			hasStdin = true
			strArgs = strArgs[:len(strArgs)-1]
		}
		cmdArgs = append(cmdArgs, strArgs...)
		cmd := exec.CommandContext(cctx, pcfg.Cmd, cmdArgs...)
		if hasStdin {
			cmd.Stdin = strings.NewReader(stdinData)
		}
		cmd.Stderr = os.Stderr
		stdoutPipe, err := cmd.StdoutPipe()
		if err != nil {
			return "", err
		}
		start := time.Now()
		if err := cmd.Start(); err != nil {
			return "", fmt.Errorf("starting command: %w", err)
		}
		type result struct {
			out []byte
			err error
		}
		done := make(chan result, 1)
		go func() {
			b, _ := readAllPlugin(stdoutPipe)
			werr := cmd.Wait()
			done <- result{b, werr}
		}()
		select {
