				if cctx.Err() != nil {
					return "", fmt.Errorf("plugin timed out after %s: %w", time.Since(start), cctx.Err())
				}
				return "", res.err
			}
			return string(res.out), nil
		case <-cctx.Done():
			res := <-done
			_ = res
			return "", fmt.Errorf("plugin timed out after %s: %w", time.Since(start), cctx.Err())
		}
	}
}
