	left, err := p.parseAlt()
	if err != nil { return nil, err }
	p.skip()
	isUpdate := false
	if p.pos+1 < len(p.s) && p.s[p.pos] == '|' && p.s[p.pos+1] == '=' {
		isUpdate = true
		p.pos += 2
	} else if p.peek() == '=' && p.peekAt(1) != '=' {
		// Only treat as assignment for path/variable LHS
		switch left.(type) {
