type jqAssignNode struct{ left, rhs jqNode; update bool }
func (n *jqAssignNode) eval(c *jqCtx, in interface{}) ([]interface{}, error) {
	paths, err := jqExpandAssignPaths(c, n.left, in)
	if err != nil { return nil, err }
	results := []interface{}{in}
	for _, path := range paths {
		var newResults []interface{}
		for _, curInput := range results {
			// current value at path
			curVal, _ := jqGetPathVal(curInput, path)
			var cand []interface{}
			if n.update {
				cand, err = n.rhs.eval(c, curVal)
			} else {
				cand, err = n.rhs.eval(c, in)
			}
			if err != nil { return nil, err }
			if len(cand) == 0 {
				newResults = append(newResults, jqDeletePath(curInput, path))
				continue
			}
			for _, nv := range cand {
				newResults = append(newResults, jqSetPath(curInput, path, nv))
			}
		}
		results = newResults
	}
	return results, nil
}
func jqGetPathVal(in interface{}, path []interface{}) (interface{}, bool) {
	cur := in
	for _, seg := range path {
		v, found, _ := childLookupJQ(cur, seg)
		if !found { return nil, false }
		cur = v
	}
	return cur, true
}
func jqExpandAssignPaths(c *jqCtx, node jqNode, in interface{}) ([][]interface{}, error) {
	switch pn := node.(type) {
	case *jqPathNode:
		var basePaths [][]interface{}
		if pn.base == nil {
			basePaths = [][]interface{}{ {} }
		} else {
			bp, err := jqExpandAssignPaths(c, pn.base, in)
			if err != nil { return nil, err }
			basePaths = bp
		}
		paths := basePaths
		for _, seg := range pn.segs {
			var next [][]interface{}
			for _, prefix := range paths {
				curVal, _ := jqGetPathVal(in, prefix)
				switch seg.kind {
				case "field":
					next = append(next, append(append([]interface{}{}, prefix...), seg.name))
				case "index":
					next = append(next, append(append([]interface{}{}, prefix...), seg.index))
				case "iter":
					if arr, ok := curVal.([]interface{}); ok {
						for i := range arr { next = append(next, append(append([]interface{}{}, prefix...), i)) }
					} else if m, ok := curVal.(map[string]interface{}); ok {
						for _, k := range sortedKeys(m) { next = append(next, append(append([]interface{}{}, prefix...), k)) }
					}
				case "exprindex":
					vals, err := seg.expr.eval(c, curVal); if err != nil { return nil, err }
					for _, v := range vals { next = append(next, append(append([]interface{}{}, prefix...), v)) }
				default:
					return nil, fmt.Errorf("invalid path expression for assignment")
				}
			}
			paths = next
		}
		return paths, nil
	case *jqIdentityNode:
		return [][]interface{}{ {} }, nil
	}
	return nil, fmt.Errorf("invalid path expression for assignment")
}

