{"command":"cat > datasource_dotenv.go <<'GO'
package gomplate

import (
	"fmt"
	"os"
	"strings"
)

func parseDotEnv(s string) (interface{}, error) {
	out := make(map[string]interface{})
	lines := strings.Split(s, "\n")
	// Need original source offsets for errors: reconstruct line starts
	lineStarts := make([]int, len(lines))
	pos := 0
	for i,l:=range lines{lineStarts[i]=pos; pos += len(l)+1}
	for i:=0;i<len(lines);i++ {
		origLine := lines[i]
		line := strings.TrimSpace(origLine)
		if line=="" || strings.HasPrefix(line,"#") { continue }
		line = strings.TrimPrefix(line, "export ")
		line = strings.TrimSpace(line)
		k,v,found := strings.Cut(line,"=")
		if !found {
			remainder := ""
			if lineStarts[i] < len(s) { remainder = s[lineStarts[i]:] }
			// The unexpected char is the newline at end of this line (or EOF)
			return nil, fmt.Errorf("unexpected character %q in variable name near %q", "\n", remainder)
		}
		key := strings.TrimSpace(k)
		val := strings.TrimSpace(v)
		if len(val)>=1 && (val[0]=='\'' || val[0]=='"') {
			quote := val[0]
			for (len(val)<2 || val[len(val)-1]!=quote) && i+1 < len(lines) {
				i++; val += "\n" + lines[i]
			}
			inner := ""
			if len(val)>=2 { inner = val[1:len(val)-1] }
			if quote=='"' {
				out[key] = expandDotEnvDouble(inner, out)
			} else {
				out[key] = inner
			}
			continue
		}
		if idx := strings.Index(val, " #"); idx>=0 { val = strings.TrimSpace(val[:idx]) }
		val = expandEnvVars(val, out)
		out[key]=val
	}
	return out, nil
}
func expandDotEnvDouble(inner string, local map[string]interface{}) string {
	var b strings.Builder
	for i:=0;i<len(inner);i++ {
		c:=inner[i]
		if c=='\\' && i+1<len(inner) {
			nx:=inner[i+1]; i++
			switch nx {
			case 'n': b.WriteByte('\n')
			case 'r': b.WriteByte('\r')
			default: b.WriteByte(nx)
