import pathlib
p=pathlib.Path("funcs/net.go"); s=p.read_text()
# Subnets validation
s=s.replace('''	newBits := prefix.Bits() + int(nb)
	if nb < 0 || newBits > prefix.Addr().BitLen() {
		return nil, fmt.Errorf("newbits %d out of range", nb)
	}
