	if nb < 1 {
		return nil, fmt.Errorf("must extend prefix by at least one bit")
	}
	if nb <= 32 && newBits > prefix.Addr().BitLen() {
		return nil, fmt.Errorf("insufficient address space to extend prefix of %d by %d", prefix.Bits(), nb)
	}
	if nb > 63 {
		return []netip.Prefix{}, nil
	}
	count := 1 << uint(nb)
	if nb > 32 {
		// Original overflows / OOMs for huge counts; avoid allocating by returning empty for >32 like for >=64
		return []netip.Prefix{}, nil
	}''')
# Replace SubnetSizes function body using markers
start=s.index('func (f *NetFuncs) CIDRSubnetSizes')
end=s.index('func subnetSize')
new=r'''func (f *NetFuncs) CIDRSubnetSizes(args ...interface{}) ([]netip.Prefix, error) {
	if err := checkExperimental(f.ctx); err != nil {
		return nil, err
	}
	if len(args) < 2 {
		return nil, fmt.Errorf("wrong number of args: want 2 or more, got %d", len(args))
	}
	prefix, err := parsePrefixArg(args[len(args)-1])
	if err != nil {
		return nil, err
	}
	// Validate all newbits first (go-cidr style messages)
	nbs := make([]int64, len(args)-1)
	for i, a := range args[:len(args)-1] {
		nb, err := toInt64(a)
		if err != nil { return nil, err }
		if nb < 1 { return nil, fmt.Errorf("must extend prefix by at least one bit") }
		if nb > 32 { return nil, fmt.Errorf("may not extend prefix by more than 32 bits") }
		if prefix.Bits()+int(nb) > prefix.Addr().BitLen() {
			fam := "IPv4"; if prefix.Addr().Is6() { fam = "IPv6" }
			return nil, fmt.Errorf("would extend prefix to %d bits, which is too long for an %s address", prefix.Bits()+int(nb), fam)
		}
		nbs[i] = nb
	}
	// Big-int allocation aligned from base
	addrBits := prefix.Addr().BitLen()
	baseInt := addrToBig(prefix.Masked().Addr())
	endInt := new(big.Int).Add(baseInt, new(big.Int).Lsh(big.NewInt(1), uint(addrBits-prefix.Bits())))
	cur := new(big.Int).Set(baseInt)
	out := make([]netip.Prefix, 0, len(nbs))
	var last *netip.Prefix
	for _, nb := range nbs {
		newBits := prefix.Bits() + int(nb)
		size := new(big.Int).Lsh(big.NewInt(1), uint(addrBits-newBits))
		// align cur up to size boundary relative to 0
		rem := new(big.Int).Mod(cur, size)
		aligned := new(big.Int).Set(cur)
		if rem.Sign() != 0 {
			aligned.Sub(aligned, rem); aligned.Add(aligned, size)
		}
		endAlloc := new(big.Int).Add(aligned, size)
		if endAlloc.Cmp(endInt) > 0 {
			after := prefix.String()
			if last != nil { after = last.String() }
			return nil, fmt.Errorf("not enough remaining address space for a subnet with a prefix of %d bits after %s", newBits, after)
		}
		pfx := netip.PrefixFrom(bigToAddr(aligned, prefix.Addr().Is4()), newBits)
		out = append(out, pfx)
		lastCopy := pfx; last = &lastCopy
		cur = endAlloc
	}
	return out, nil
}
func addrToBig(a netip.Addr) *big.Int {
	if a.Is4() { arr:=a.As4(); return new(big.Int).SetBytes(arr[:]) }
	arr:=a.As16(); return new(big.Int).SetBytes(arr[:])
}
func bigToAddr(v *big.Int, is4 bool) netip.Addr {
	if is4 { var arr [4]byte; b:=v.Bytes(); copy(arr[4-len(b):],b); return netip.AddrFrom4(arr) }
	var arr [16]byte; b:=v.Bytes(); copy(arr[16-len(b):],b); return netip.AddrFrom16(arr)
}

'''
s=s[:start]+new+s[end:]
if '"math/big"' not in s:
    s=s.replace('"math/bits"','"math/big"\n\t"math/bits"')
p.write_text(s)
