package funcs

import (
	"fmt"
	"strconv"
	"strings"
	"time"
)

func jqNow() time.Time { return time.Now() }
func parseJQDate(s string) (time.Time,error) {
	// RFC3339 with optional fractional
	if t,err:=time.Parse(time.RFC3339Nano,s);err==nil{return t,nil}
	if t,err:=time.Parse(time.RFC3339,s);err==nil{return t,nil}
	return time.Time{}, fmt.Errorf("date %q does not match format \"%%Y-%%m-%%dT%%H:%%M:%%SZ\"", s)
}
func epochToTime(v interface{}) time.Time {
	f:=numFloat(v); sec:=int64(f); nsec:=int64((f-float64(sec))*1e9); return time.Unix(sec,nsec)
}
func jqBrokenDown(t time.Time) []interface{} {
	// [year, month(0-11), day, hour, minute, second, day-of-week(0 Sun), day-of-year(0-based)]
	return []interface{}{t.Year(), int(t.Month())-1, t.Day(), t.Hour(), t.Minute(), t.Second(), int(t.Weekday()), t.YearDay()-1}
}
func jqMkTime(arr []interface{}, local bool) (time.Time,error){
	if len(arr)<6{return time.Time{},fmt.Errorf("mktime requires an array of 6+ elements")}
	iv:=func(i int)int{v,_:=toInt64(arr[i]); return int(v)}
	loc:=time.UTC; if local{loc=time.Local}
	return time.Date(iv(0), time.Month(iv(1)+1), iv(2), iv(3), iv(4), iv(5), 0, loc),nil
}
func jqTimeFromInput(v interface{}, local bool) (time.Time,error){
	if isNum(v){t:=epochToTime(v); if local{return t.Local(),nil}; return t.UTC(),nil}
	if arr,ok:=v.([]interface{});ok{return jqMkTime(arr,local)}
	return time.Time{},fmt.Errorf("cannot format: %s",jqPreview(v))
}
// Convert strftime format (%Y etc) to Go layout by scanning fmt string literal segments
func jqStrftime(format string, t time.Time) string {
	// Iterate directives and format individually to avoid layout conversion pitfalls
	var b strings.Builder
	for i:=0;i<len(format);i++{
		if format[i]!='%'||i+1>=len(format){b.WriteByte(format[i]);continue}
		i++; code:=format[i]
		switch code{
		case 'Y': b.WriteString(strconv.Itoa(t.Year()))
		case 'y': b.WriteString(fmt.Sprintf("%02d",t.Year()%100))
		case 'm': b.WriteString(fmt.Sprintf("%02d",int(t.Month())))
		case 'd': b.WriteString(fmt.Sprintf("%02d",t.Day()))
		case 'H': b.WriteString(fmt.Sprintf("%02d",t.Hour()))
		case 'M': b.WriteString(fmt.Sprintf("%02d",t.Minute()))
		case 'S': b.WriteString(fmt.Sprintf("%02d",t.Second()))
		case 'f': b.WriteString(fmt.Sprintf("%06d",t.Nanosecond()/1000))
		case 'z': b.WriteString(t.Format("-0700"))
		case 'Z': n,_:=t.Zone(); b.WriteString(n)
		case 'a': b.WriteString(t.Format("Mon"))
		case 'A': b.WriteString(t.Format("Monday"))
		case 'b','h': b.WriteString(t.Format("Jan"))
		case 'B': b.WriteString(t.Format("January"))
		case 'p': b.WriteString(t.Format("PM"))
		case 'I': b.WriteString(t.Format("03"))
		case 'j': b.WriteString(fmt.Sprintf("%03d",t.YearDay()))
		case 'u': wd:=int(t.Weekday()); if wd==0{wd=7}; b.WriteString(strconv.Itoa(wd))
		case 'w': b.WriteString(strconv.Itoa(int(t.Weekday())))
		case 'F': b.WriteString(t.Format("2006-01-02"))
		case 'T': b.WriteString(t.Format("15:04:05"))
		case '%': b.WriteByte('%')
		case 'n': b.WriteByte('\n')
		case 't': b.WriteByte('\t')
		default: b.WriteByte('%'); b.WriteByte(code)
		}
	}
	return b.String()
