	// Convert common strftime directives to Go reference layout for Parse
	replacer:=[]struct{in,out string}{
		{"%Y","2006"},{"%y","06"},{"%m","01"},{"%d","02"},{"%H","15"},{"%M","04"},{"%S","05"},{"%f","000000"},{"%z","-0700"},{"%Z","MST"},{"%a","Mon"},{"%A","Monday"},{"%b","Jan"},{"%h","Jan"},{"%B","January"},{"%p","PM"},{"%I","03"},{"%j","002"},
	}
	out:=format
	for _,r:=range replacer{out=strings.ReplaceAll(out,r.in,r.out)}
	return out
}
func parseTimeWithLayout(layout,s string) (time.Time,error){ return time.Parse(layout,s) }
