package funcs

import (
	"fmt"
	"math"
	"time"
)

func jqPathBuiltin(c *jqCtx, arg jqNode, in interface{}) ([]interface{},error) {
	// Validate by evaluating arg (discard result) to surface type errors like gojq
	if _,err:=arg.eval(c,in); err!=nil{return nil,err}
	paths,err:=jqExpandAssignPaths(c,arg,in)
	if err!=nil{return nil,fmt.Errorf("invalid path expression")}
	out:=make([]interface{},len(paths))
	for i,p:=range paths{ out[i]=append([]interface{}{},p...) }
	return out,nil
}

func jqMathBuiltin(c *jqCtx,name string,args []jqNode,in interface{}) ([]interface{},error,bool) {
	// returns handled?
	unary := map[string]func(float64)float64{
		"acos":math.Acos,"acosh":math.Acosh,"asin":math.Asin,"asinh":math.Asinh,"atan":math.Atan,"atanh":math.Atanh,
		"cbrt":math.Cbrt,"ceil":math.Ceil,"cos":math.Cos,"cosh":math.Cosh,"erf":math.Erf,"erfc":math.Erfc,"exp":math.Exp,"exp10":func(x float64)float64{return math.Pow(10,x)},"exp2":math.Exp2,"expm1":math.Expm1,"fabs":math.Abs,"floor":math.Floor,"gamma":math.Gamma,"log":math.Log,"log10":math.Log10,"log1p":math.Log1p,"log2":math.Log2,"nearbyint":math.Round,"rint":math.Round,"significand":func(x float64)float64{ if x==0{return 0}; _,exp:=math.Frexp(x); return math.Ldexp(x,-exp+1) },"sin":math.Sin,"sinh":math.Sinh,"sqrt":math.Sqrt,"tan":math.Tan,"tanh":math.Tanh,"tgamma":math.Gamma,"trunc":math.Trunc,
	}
	if fn,ok:=unary[name];ok{
		if len(args)!=0{return nil,fmt.Errorf("function not defined: %s/%d",name,len(args)),true}
		if !isNum(in){return nil,fmt.Errorf("%s cannot be applied to: %s",name,jqPreview(in)),true}
		r:=fn(numFloat(in))
		if name=="floor"||name=="ceil"||name=="rint"||name=="nearbyint"||name=="trunc"||name=="round" {
			// jq math floor etc return int when integral? gojq returns int for floor, float for many
			if name=="floor"||name=="ceil"||name=="trunc" {return []interface{}{int(r)},nil,true}
		}
		return []interface{}{r},nil,true
	}
	if name=="round"{
		if !isNum(in){return nil,fmt.Errorf("round cannot be applied to: %s",jqPreview(in)),true}
		return []interface{}{int(math.Round(numFloat(in)))},nil,true
	}
	// binary math functions: arguments are filters evaluated against input
	binary := map[string]func(float64,float64)float64{
		"pow":math.Pow,"atan2":math.Atan2,"hypot":math.Hypot,"remainder":math.Remainder,"drem":math.Remainder,"fmod":math.Mod,"ldexp":func(x,y float64)float64{return math.Ldexp(x,int(y))},"scalbln":func(x,y float64)float64{return math.Ldexp(x,int(y))},"jn":func(n,x float64)float64{return math.Jn(int(n),x)},"yn":func(n,x float64)float64{return math.Yn(int(n),x)},
	}
	if fn,ok:=binary[name];ok{
		if len(args)!=2{return nil,fmt.Errorf("function not defined: %s/%d",name,len(args)),true}
		av,err:=args[0].eval(c,in); if err!=nil{return nil,err,true}; bv,err:=args[1].eval(c,in); if err!=nil{return nil,err,true}
		if len(av)==0||len(bv)==0{return []interface{}{},nil,true}
		if !isNum(av[0])||!isNum(bv[0]){return nil,fmt.Errorf("%s cannot be applied to: %s",name,jqPreview(in)),true}
		return []interface{}{fn(numFloat(av[0]),numFloat(bv[0]))},nil,true
	}
	if name=="exponent"{
		if !isNum(in){return nil,fmt.Errorf("exponent cannot be applied to: %s",jqPreview(in)),true}
		_,e:=math.Frexp(numFloat(in)); return []interface{}{e},nil,true
	}
	return nil,nil,false
}

func jqWhileRepeat(c *jqCtx,name string,args []jqNode,in interface{}) ([]interface{},error,bool){
	switch name{
	case "while":
		if len(args)!=2{return nil,fmt.Errorf("function not defined: while/%d",len(args)),true}
		var out []interface{}
		cur:=in
		for i:=0;i<100000;i++{
			conds,err:=args[0].eval(c,cur); if err!=nil{return nil,err,true}
			truthy:=false; for _,v:=range conds{if jqTruthy(v){truthy=true}}
			if !truthy{break}
			out=append(out,cur)
			next,err:=args[1].eval(c,cur); if err!=nil{return nil,err,true}
			if len(next)==0{break}; cur=next[0]
			// If update produces multiple, jq branching becomes multiple streams - simplification: process first only for extra branches by ignoring
		}
		return out,nil,true
	case "repeat":
		if len(args)!=1{return nil,fmt.Errorf("function not defined: repeat/%d",len(args)),true}
		var out []interface{}
		// Cap to 10000 as this evaluator is eager; consumers such as limit/first only need first values.
		for i:=0;i<10000;i++{
			vals,err:=args[0].eval(c,in); if err!=nil{return nil,err,true}
			out=append(out,vals...)
			if len(vals)==0{break}
		}
		return out,nil,true
	case "halt":
		return nil, fmt.Errorf("halt error: null"),true
	case "halt_error":
		return nil,&jqUserError{v:in},true
	}
	return nil,nil,false
}

var _ = time.Now
