func gsCredentialsError() error {
	return errors.New("open: bucket opener: failed to retrieve GCP credentials: google: could not find default credentials. See https://cloud.google.com/docs/authentication/external/set-up-adc for more information")
}

func (r *dsRegistry) readGS(ctx context.Context, ds config.DataSource, sp fsSplit, finalURL *url.URL) (*rawResult, error) {
	bucket := finalURL.Host
	key := sp.name
	if key == "." { key = "" }
	emulator := os.Getenv("STORAGE_EMULATOR_HOST")
	var authHeader string
	base := ""
	if emulator != "" {
		base = strings.TrimSuffix(emulator, "/")
		if !strings.Contains(base, "://") { base = "http://" + base }
	} else {
		credPath := os.Getenv("GOOGLE_APPLICATION_CREDENTIALS")
		// query params private_key_path/access_id are for signed URLs in original, ignored here
		if credPath == "" {
			return nil, fsErr("open", sp, gsCredentialsError())
		}
		tok, err := gsAccessToken(ctx, credPath)
		if err != nil { return nil, fsErr("open", sp, err) }
		authHeader = "Bearer " + tok
		base = "https://storage.googleapis.com"
	}
	isDir := strings.HasSuffix(finalURL.Path, "/") || key == ""
	if isDir {
		prefix := key
		if prefix != "" && !strings.HasSuffix(prefix, "/") { prefix += "/" }
		q := url.Values{"prefix": {prefix}, "delimiter": {"/"}}
		reqURL := fmt.Sprintf("%s/storage/v1/b/%s/o?%s", base, url.PathEscape(bucket), q.Encode())
		b, err := gsGet(ctx, reqURL, authHeader)
		if err != nil { return nil, fsErr("open", sp, fmt.Errorf("open: %w", err)) }
		var list struct{
			Items []struct{ Name string `json:"name"` } `json:"items"`
			Prefixes []string `json:"prefixes"`
		}
		if err := json.Unmarshal(b, &list); err != nil { return nil, fsErr("open", sp, err) }
		seen:=map[string]bool{}; var entries []string
		for _,it:=range list.Items{ rel:=strings.TrimPrefix(it.Name,prefix); first:=strings.Split(rel,"/")[0]; if first!=""&&!seen[first]{seen[first]=true;entries=append(entries,first)} }
		for _,p:=range list.Prefixes{ rel:=strings.Trim(strings.TrimPrefix(p,prefix),"/"); first:=strings.Split(rel,"/")[0]; if first!=""&&!seen[first]{seen[first]=true;entries=append(entries,first)} }
		sort.Strings(entries)
		if entries==nil{entries=[]string{}}
		return &rawResult{isDir:true, entries:entries}, nil
	}
	var reqURL string
	if emulator != "" {
		// fake-gcs-server download endpoint
		reqURL = fmt.Sprintf("%s/download/storage/v1/b/%s/o/%s?alt=media", base, url.PathEscape(bucket), url.QueryEscape(key))
	} else {
		reqURL = fmt.Sprintf("%s/storage/v1/b/%s/o/%s?alt=media", base, url.PathEscape(bucket), url.QueryEscape(key))
	}
	b, err := gsGet(ctx, reqURL, authHeader)
	if err != nil { return nil, fsErr("open", sp, fmt.Errorf("open: %w", err)) }
	var ct string
	// gsGet discards headers - mime from key extension/url type is fine
	return &rawResult{data:b, mime:mimeForURL(finalURL, key, ct)}, nil
}
func gsGet(ctx context.Context, urlStr, auth string) ([]byte,error) {
	req,_:=http.NewRequestWithContext(ctx,"GET",urlStr,nil)
	if auth!=""{req.Header.Set("Authorization",auth)}
	resp,err:=http.DefaultClient.Do(req); if err!=nil{return nil,err}
	defer resp.Body.Close(); b,_:=io.ReadAll(resp.Body)
	if resp.StatusCode<200||resp.StatusCode>=300{return nil,fmt.Errorf("%s",string(b))}
