		PrivateKey string `json:"private_key"`
		TokenURI string `json:"token_uri"`
		Type string `json:"type"`
	}
	if err:=json.Unmarshal(b,&cred);err!=nil{return "",err}
	if cred.ClientEmail==""||cred.PrivateKey==""{return "",gsCredentialsError()}
	block,_:=pem.Decode([]byte(cred.PrivateKey)); if block==nil{return "",fmt.Errorf("invalid private key")}
